const e=[{id:1,icon:"Flame",accent:"#dc2626",title:"النار ومخاطرها",subtitle:"كيف نحمي أنفسنا من النار",grades:"1-2",ages:"6-8",summary:"النار تفاعلٌ كيميائي بين ثلاثة أشياء: الحرارة والوقود والأكسجين. إذا غاب واحدٌ منها، تنطفئ النار.",blocks:[{heading:"مثلث النار",body:"تتكوّن النار من ثلاثة أشياء: الحرارة والوقود والأكسجين.",image:"media/images/fire_triangle.png"},{heading:"قف، انبطح، تدحرج",body:"إذا اشتعلت النار في ملابسك، فلا تركض! قف، وألقِ بنفسك على الأرض، وغطِّ وجهك بيديك، وتدحرج على الأرض حتى تنطفئ النار.",image:"media/images/stop_drop_roll.png"},{heading:"الخروج الآمن",body:"اعرف طرق الخروج. إذا كان هناك دخان، فانخفض وازحف على يديك وركبتيك. وفي الخارج، قف عند نقطة التجمع وأخبر أحد الكبار.",image:"media/images/fire_exit.png"}],examples:["اختبر جهاز إنذار الدخان كل شهر مع الكبار.","ضع مع عائلتك خطةً للخروج من المنزل.","احفظ الرقم 115.","اعرف نقطة التجمع في مدرستك."],tips:["لا تلعب بأعواد الثقاب والولّاعة.","إذا رأيت دخانًا، فانخفض.","اعرف دائمًا طريقين للخروج."],warnings:["أثناء الحريق، لا تختبئ أبدًا تحت السرير أو داخل الخزانة! فلن يستطيع فريق الدفاع المدني أن يراك. اخرج وأخبر أحد الكبار."],realCase:"في إحدى المدارس، رأى تلميذٌ دخانًا، فأخبر معلّمه فورًا، وخرج الجميع بسلام.",video:"media/videos/lesson_fire.mp4",game:{instruction:"أيّ هذه التصرفات صحيحة أثناء الحريق؟",items:[{text:"قف، انبطح، تدحرج",emoji:"🔄",correct:!0},{text:"اركض عندما تشتعل النار في ملابسك",emoji:"🏃",correct:!1},{text:"ابقَ منخفضًا تحت الدخان",emoji:"🐢",correct:!0},{text:"استخدم المصعد",emoji:"🛗",correct:!1}]},activity:{prompt:"أنت في المنزل وترى نارًا في المطبخ. ماذا ستفعل؟",image:"media/images/activity_fire.png",options:[{text:"أخرج من المنزل فورًا، وأخبر أحد الكبار، ونتصل بالرقم 115",correct:!0,feedback:"الخروج فورًا وإخبار أحد الكبار والاتصال بالرقم 115 هو التصرّف الآمن."},{text:"أحاول إطفاء النار بالماء",correct:!1,feedback:"الأطفال لا يُطفئون النار، والماء على الزيت المشتعل خطر؛ اخرج وأخبر أحد الكبار."},{text:"أختبئ",correct:!1,feedback:"إذا اختبأت فلن يستطيع فريق الدفاع المدني أن يراك؛ اخرج وأخبر أحد الكبار."},{text:"أبقى هناك وأتفرّج",correct:!1,feedback:"البقاء قرب النار ليس آمنًا؛ اخرج من المنزل فورًا وأخبر أحد الكبار."}]},quiz:[{question:"إذا اشتعلت النار في ملابسك، فماذا تفعل؟",options:[{text:"أركض بسرعة لأجد ماءً وأطفئ النار",correct:!1,feedback:"الركض يجعل النار أكبر!"},{text:"أتوقّف، وألقي بنفسي على الأرض، وأتدحرج",correct:!0,feedback:"أحسنت!"},{text:"أبكي وأنتظر أن يأتي أحد",correct:!1,feedback:"البكاء لا يطفئ النار."}]},{question:"ما عناصر النار الثلاثة؟",options:[{text:"الحرارة، الوقود، الأكسجين",correct:!0,feedback:"الحرارة والوقود والأكسجين معًا تكوّن مثلث النار."},{text:"الماء، الرياح، الحرارة",correct:!1,feedback:"لا. النار تحتاج إلى الحرارة والوقود والأكسجين، والماء ليس منها. ولا يُسكب الماء أبدًا على زيت مشتعل أو على الأجهزة الكهربائية."},{text:"الدخان، الماء، الثلج",correct:!1,feedback:"الدخان والماء والثلج لا تكوّن النار؛ فالنار تحتاج إلى الحرارة والوقود والأكسجين."}],explanation:"تتكوّن النار من ثلاثة أشياء: الحرارة والوقود والأكسجين. وإذا غاب واحدٌ منها، تنطفئ النار."},{question:"ما رقم الدفاع المدني؟",options:[{text:"115",correct:!0,feedback:"الرقم 115 هو رقم الدفاع المدني، وقد حفظته جيدًا!"},{text:"122",correct:!1,feedback:"لا، الرقم 122 هو رقم الإسعاف."},{text:"9-1-1",correct:!1,feedback:"لا، هذا رقم الطوارئ في أمريكا، وليس في كوردستان."}],explanation:"في كوردستان، الرقم 115 هو رقم الدفاع المدني. احفظ هذا الرقم!"},{question:"في المنزل حريق، ولعبتك المفضّلة في غرفتك. ماذا تفعل؟",options:[{text:"أترك اللعبة وأخرج فورًا",correct:!0,feedback:"صحيح. اللعبة ليست أهمّ من حياتك. اخرج وابقَ في الخارج."},{text:"أركض بسرعة إلى غرفتي لأحضر اللعبة",correct:!1,feedback:"لا. النار والدخان ينتشران بسرعة. اترك اللعبة واخرج فورًا."},{text:"أختبئ تحت سريري حتى تنطفئ النار",correct:!1,feedback:"لا. لن يستطيع فريق الدفاع المدني أن يجدك هناك. اخرج وأخبر أحد الكبار."}],explanation:"اخرج فورًا واترك أشياءك. لا تختبئ أبدًا، ولا تعُد إلى الداخل."},{question:"خرجت من الحريق بأمان. ماذا تفعل بعد ذلك؟",options:[{text:"أعود إلى الداخل لأبحث عن حيواني الأليف",correct:!1,feedback:"لا. لا تعُد إلى الداخل أبدًا. أخبر أحد الكبار أو فريق 115 بمكان حيوانك."},{text:"أبقى عند نقطة التجمع وأُخبر أحد الكبار",correct:!0,feedback:"صحيح. هكذا يعرف الكبار أنك بأمان، ويستطيعون أن يخبروا فريق 115 بمن هو مفقود."},{text:"أعود إلى الداخل لأساعد في إطفاء النار",correct:!1,feedback:"لا. الأطفال لا يُطفئون النار. فريق 115 يُطفئها بمعدّاته."}],explanation:"بعد أن تخرج، ابقَ في الخارج. انتظر عند نقطة التجمع، وأخبر أحد الكبار."}],media:[{kind:"image",src:"media/images/primary3d_kitchen_matches_safety.webp",title:"مثلث النار",description:"تتكوّن النار من ثلاثة أشياء: الحرارة والوقود والأكسجين."}],steps:[{title:"اصرخ واخرج",detail:"اصرخ بصوتٍ عالٍ ليعرف الجميع. اخرج فورًا، ولا تتوقّف من أجل الألعاب أو الحقائب.",critical:!0},{title:"انخفض تحت الدخان",detail:"إذا كان هناك دخان، فانخفض وازحف على يديك وركبتيك نحو طريق الخروج.",critical:!0},{title:"ابقَ في الخارج",detail:"انتظر عند نقطة التجمع. لا تعُد إلى الداخل أبدًا.",critical:!0},{title:"أخبر أحد الكبار واتصل بالرقم 115",detail:"أخبر أحد الكبار بالحريق. وإذا لم يكن أحدٌ من الكبار قريبًا، فاتصل بالرقم 115 من الخارج.",critical:!0}]},{id:2,icon:"Activity",accent:"#ea580c",title:"الزلزال",subtitle:"كيف نحمي أنفسنا أثناء الزلزال",grades:"1-2",ages:"6-8",summary:"الزلزال ظاهرةٌ طبيعية. لا نستطيع أن نوقفه، لكننا نستطيع أن نحمي أنفسنا.",blocks:[{heading:"انخفض، احتمِ، تمسّك",body:"انزل على ركبتيك، واحتمِ تحت طاولةٍ متينة، وأمسك ساق الطاولة جيدًا حتى ينتهي الاهتزاز. وإذا لم تكن هناك طاولة، فاجلس على ركبتيك بجانب جدارٍ بعيد عن النوافذ، واحمِ رأسك ورقبتك بيديك.",image:"media/images/drop_cover_hold.png"},{heading:"ابتعد عن الزجاج",body:"الزجاج ينكسر ويمكن أن يجرحك. ابتعد عن النوافذ والمرايا، وعن الأشياء الثقيلة التي يمكن أن تسقط.",image:"media/images/earthquake_glass.png"},{heading:"بعد الزلزال",body:"بعد أن ينتهي الاهتزاز، اخرج بهدوء مع المعلّم عبر السلالم. لا تستخدم المصعد. وكن منتبهًا، لأن هزّاتٍ أصغر قد تأتي بعده.",image:"media/images/after_earthquake.png"}],examples:["احتمِ تحت طاولةٍ متينة.","ابتعد عن النوافذ.","استمع إلى المعلّم.","اخرج بهدوء بعد الزلزال."],tips:["اعرف الأماكن الآمنة في الصف وفي المنزل.","جهّزوا مع العائلة الماء وحقيبة الطوارئ.","احفظ الرقم 115."],warnings:["أثناء الزلزال لا تركض، ولا تقف تحت الباب، ولا تستخدم المصعد أبدًا!"],realCase:"أثناء أحد الزلازل، احتمى تلميذٌ تحت طاولة وأمسك ساقها، فبقي سالمًا!",video:"media/videos/lesson_earthquake.mp4",game:{instruction:"أيّ هذه التصرفات صحيحة أثناء الزلزال؟",items:[{text:"احتمِ تحت الطاولة",emoji:"🪑",correct:!0},{text:"استخدم المصعد",emoji:"🛗",correct:!1},{text:"احمِ رأسك",emoji:"🛡️",correct:!0},{text:"قف بجانب النافذة",emoji:"🪟",correct:!1}]},activity:{prompt:"أنت في الصف والأرض تهتز، والمعلّم ليس موجودًا. ماذا ستفعل؟",image:"media/images/activity_eq.png",options:[{text:"أدخل تحت الطاولة، وأحمي رأسي، وأمسك ساق الطاولة",correct:!0,feedback:"هذا هو «انخفض، احتمِ، تمسّك»، وهو يحميك من الأشياء التي تسقط."},{text:"أركض إلى الخارج",correct:!1,feedback:"قد تسقط وتُصاب إذا ركضت؛ انخفض، واحتمِ، وتمسّك."},{text:"أذهب إلى جانب النافذة",correct:!1,feedback:"زجاج النافذة قد ينكسر ويجرحك؛ ابتعد عن النوافذ."},{text:"أبكي",correct:!1,feedback:"لا بأس أن تخاف، لكن البكاء لا يحميك؛ ادخل تحت الطاولة وأمسك ساقها."}]},quiz:[{question:"ما أول شيء تفعله أثناء الزلزال؟",options:[{text:"انخفض، احتمِ، تمسّك",correct:!0,feedback:"«انخفض، احتمِ، تمسّك» يحميك من الأشياء التي تسقط أثناء الاهتزاز."},{text:"اركض إلى الخارج بأسرع ما يمكن",correct:!1,feedback:"لا، فقد تسقط وتُصاب."},{text:"قف على قدميك في وسط الغرفة",correct:!1,feedback:"لا، فقد تسقط الأشياء عليك."}],explanation:"أثناء الزلزال: انزل على ركبتيك، واحتمِ تحت طاولةٍ متينة، وأمسك ساقها حتى ينتهي الاهتزاز."},{question:"ممّ يجب أن نبتعد؟",options:[{text:"النوافذ والزجاج",correct:!0,feedback:"الزجاج ينكسر ويمكن أن يجرحك، لذلك ابقَ بعيدًا عن النوافذ!"},{text:"الطاولة المتينة",correct:!1,feedback:"لا، الطاولة المتينة مكانٌ آمن."},{text:"أرضية الغرفة",correct:!1,feedback:"لا، أثناء الزلزال يجب أن تنزل إلى الأرض."}],explanation:"الزجاج ينكسر ويمكن أن يجرحك. ابتعد عن النوافذ والمرايا والأشياء الثقيلة التي يمكن أن تسقط."},{question:"انتهى الاهتزاز. كيف تخرج من المبنى؟",options:[{text:"بهدوء عبر السلالم، مع المعلّم",correct:!0,feedback:"الخروج بهدوء عبر السلالم مع المعلّم هو الطريق الآمن بعد الاهتزاز."},{text:"بسرعة في المصعد، مع أصدقائي",correct:!1,feedback:"لا، لا تستخدم المصعد. اخرج بهدوء مع المعلّم عبر السلالم."},{text:"ركضًا وحدي، قبل الجميع",correct:!1,feedback:"إذا ركضت فقد تسقط وتُصاب؛ اخرج بهدوء مع المعلّم، وكن منتبهًا لأن هزّاتٍ أصغر قد تأتي بعده."}],explanation:"بعد أن ينتهي الاهتزاز، اخرج بهدوء مع المعلّم عبر السلالم. لا تستخدم المصعد، وكن منتبهًا لأن هزّاتٍ أصغر قد تأتي بعده."},{question:"بدأ الاهتزاز في الصف، وأنت تجلس بجانب نافذةٍ كبيرة. ماذا تفعل؟",options:[{text:"أقف عند النافذة لأرى ما يحدث",correct:!1,feedback:"لا. الزجاج قد ينكسر ويؤذيك. ابتعد عن النوافذ."},{text:"أركض إلى الباب وأقف تحته",correct:!1,feedback:"لا. لا تركض، ولا تقف تحت الباب. تحت الطاولة: انخفض، احتمِ، تمسّك."},{text:"أبتعد عن النافذة وأدخل تحت طاولتي",correct:!0,feedback:"صحيح. الزجاج قد ينكسر ويؤذيك، والطاولة تحميك."}],explanation:"ابتعد عن النوافذ والزجاج. تحت طاولةٍ متينة: انخفض، احتمِ، تمسّك."},{question:"الأرض تهتزّ، ولا توجد طاولة قريبة منك. ماذا تفعل؟",options:[{text:"أجثو بجانب جدارٍ بعيدٍ عن النوافذ وأحمي رأسي ورقبتي",correct:!0,feedback:"صحيح. يداك تحميان رأسك ورقبتك، والجدار يُبقيك بعيدًا عن الزجاج."},{text:"أركض على السلالم وأخرج إلى ساحة المدرسة",correct:!1,feedback:"لا. الركض والأرض تهتزّ قد يُسقطك ويؤذيك. ابقَ في مكانك واحمِ رأسك."},{text:"أقف بجانب خزانة الكتب العالية وأتمسّك بها بيديّ",correct:!1,feedback:"لا. الخزانة العالية قد تسقط عليك. ابتعد عن الأشياء الثقيلة التي قد تسقط."}],explanation:"لا توجد طاولة؟ اجثُ بجانب جدارٍ بعيدٍ عن النوافذ، واحمِ رأسك ورقبتك بيديك."}],media:[{kind:"image",src:"media/images/primary3d_earthquake_drill.webp",title:"انخفض، احتمِ، تمسّك",description:"انزل على ركبتيك، واحتمِ تحت طاولةٍ متينة، وأمسك ساق الطاولة جيدًا حتى ينتهي الاهتزاز. وإذا لم تكن هناك طاولة، فاجلس على ركبتيك بجانب جدارٍ بعيد عن النوافذ، واحمِ رأسك ورقبتك بيديك."}],steps:[{title:"انخفض",detail:"انزل على ركبتيك فورًا.",critical:!0},{title:"احتمِ",detail:"ادخل تحت طاولةٍ متينة. لا توجد طاولة؟ اجثُ بجانب جدارٍ بعيدٍ عن النوافذ، واحمِ رأسك ورقبتك بيديك.",critical:!0},{title:"تمسّك",detail:"أمسك بساق الطاولة جيدًا حتى يتوقّف الاهتزاز.",critical:!0},{title:"اخرج بهدوء مع المعلّم",detail:"عندما يتوقّف الاهتزاز، اخرج عبر السلالم مع المعلّم. لا تستخدم المصعد أبدًا.",critical:!1}]},{id:3,icon:"Zap",accent:"#ca8a04",title:"الكهرباء ومخاطرها",subtitle:"السلامة من الكهرباء",grades:"2-3",ages:"7-9",summary:"الكهرباء قوةٌ خفيّة وقويّة. إذا لم نكن حذرين، فقد تؤذينا أو تقتلنا.",blocks:[{heading:"المقابس الكهربائية",body:"لا تُدخل أصابعك أو أيّ أشياء معدنية في المقابس الكهربائية.",image:"media/images/electric_outlet.png"},{heading:"الماء والكهرباء معًا خطر",body:"لا تلمس الأجهزة والمفاتيح الكهربائية بيدين مبلّلتين.",image:"media/images/water_electric.png"},{heading:"الأسلاك المقطوعة",body:"لا تقترب من الأسلاك المقطوعة أو الساقطة، ولا تلمسها. أخبر أحد الكبار فورًا.",image:"media/images/broken_wire.png"}],examples:["لا تلمس المفاتيح بيدين مبلّلتين.","إذا رأيت سلكًا مقطوعًا، فأخبر أحد الكبار.","لا تستخدم الأجهزة المكسورة.","المس المفاتيح بيدين جافّتين فقط."],tips:["أطفئ الأجهزة الكهربائية عندما لا تستخدمها.","لا تستخدم الأجهزة الكهربائية في الحمّام أو بالقرب من الماء.","لا تلمس الأسلاك."],warnings:["لا تلمس الأسلاك المقطوعة الملقاة على الأرض! الكهرباء تقتل!"],realCase:"رأى تلميذٌ سلكًا مقطوعًا في ساحة المدرسة فلم يقترب منه، وأخبر معلّمه فورًا، فبقي جميع التلاميذ سالمين!",video:"media/videos/lesson_electricity.mp4",game:{instruction:"أيّ هذه الأشياء خطِرة؟",items:[{text:"يدان مبلّلتان ومفتاح كهربائي",emoji:"💧",correct:!0},{text:"كتاب",emoji:"📚",correct:!1},{text:"سلك مقطوع",emoji:"⚡",correct:!0},{text:"حذاء",emoji:"👟",correct:!1}]},activity:{prompt:"يداك مبلّلتان وتريد أن تشغّل المروحة. ماذا ستفعل؟",image:"media/images/activity_elec.png",options:[{text:"أجفّف يديّ أولًا",correct:!0,feedback:"اليدان الجافّتان آمنتان، لأن الماء ينقل الكهرباء."},{text:"أشغّلها بيدين مبلّلتين",correct:!1,feedback:"الماء ينقل الكهرباء، لذلك فاليد المبلّلة على المفتاح خطر؛ جفّفها أولًا."},{text:"لا يهمّ",correct:!1,feedback:"بل هو مهمّ: الماء والكهرباء معًا خطر، لذلك جفّف يديك أولًا."},{text:"آخذها إلى الحمّام وأستخدمها هناك",correct:!1,feedback:"الماء ينقل الكهرباء، لذلك لا تستخدم الأجهزة الكهربائية في الحمّام أو قرب الماء."}]},quiz:[{question:"لماذا تكون اليدان المبلّلتان والكهرباء معًا خطرًا؟",options:[{text:"لأن الماء ينقل الكهرباء",correct:!0,feedback:"الماء ينقل الكهرباء، لذلك جفّف يديك أولًا، ثم المس المفتاح."},{text:"لأن اليدين المبلّلتين تشعران بالحكّة",correct:!1,feedback:"الخطر ليس الحكّة: الماء ينقل الكهرباء، والكهرباء قد تؤذيك."},{text:"لا يهمّ",correct:!1,feedback:"بل هو خطر!"}],explanation:"الماء ينقل الكهرباء. لذلك المس المفاتيح والأجهزة الكهربائية بيدين جافّتين فقط."},{question:"إذا رأيت سلكًا مقطوعًا، فماذا تفعل؟",options:[{text:"لا أقترب منه وأخبر أحد الكبار",correct:!0,feedback:"بابتعادك تبقى آمنًا، وبإخبار أحد الكبار يبقى الجميع آمنين."},{text:"أرفعه بيدي وأبعده عن الطريق",correct:!1,feedback:"لا! قد يبقى في السلك المقطوع كهرباء. ابتعد وأخبر أحد الكبار."},{text:"ألمسه لأرى هل ما زال يعمل",correct:!1,feedback:"لا! الكهرباء تقتل."}],explanation:"الكهرباء تقتل. لا تقترب من الأسلاك المقطوعة أو الساقطة، ولا تلمسها، وأخبر أحد الكبار فورًا."},{question:"يريد طفلٌ أن يُدخل شيئًا معدنيًا في المقبس الكهربائي. هل هذا آمن؟",options:[{text:"لا، لا تُدخل أيّ شيءٍ معدني في المقبس أبدًا",correct:!0,feedback:"صحيح: لا تُدخل أصابعك أو أيّ أشياء معدنية في المقابس الكهربائية، لأن الكهرباء قد تؤذيك أو تقتلك."},{text:"نعم، إذا كانت يداه جافّتين",correct:!1,feedback:"اليدان الجافّتان للمفاتيح الكهربائية؛ أمّا المقبس فلا يدخله أيّ شيءٍ معدني، حتى مع اليدين الجافّتين."},{text:"نعم، إذا كانت كل مصابيح الغرفة مطفأة",correct:!1,feedback:"إطفاء المصابيح لا يجعل المقبس آمنًا؛ لا تُدخل فيه أيّ شيءٍ معدني أبدًا."}],explanation:"لا تُدخل أصابعك أو أيّ أشياء معدنية في المقابس الكهربائية. فالكهرباء قوةٌ قويّة قد تؤذينا أو تقتلنا."},{question:"بعد عاصفة، يوجد سلكٌ مقطوع على الأرض، وصديقك يريد أن يُبعده بعصا. ماذا تقول له؟",options:[{text:"نعم، ولكن بعصا طويلة جدًا فقط",correct:!1,feedback:"لا. الكهرباء قد تؤذيك مع ذلك. لا تقترب من السلك أبدًا."},{text:"لا، ابتعد ولنُخبر أحد الكبار",correct:!0,feedback:"صحيح. لا تلمس السلك المقطوع أبدًا، ولا حتى بعصا. أخبر أحد الكبار."},{text:"نعم، إذا كان يلبس حذاءه",correct:!1,feedback:"لا. الحذاء لا يجعل السلك المقطوع آمنًا. ابتعد وأخبر أحد الكبار."}],explanation:"السلك المقطوع قد يقتل. لا تلمسه بأيّ طريقة. ابتعد، وأبعِد أصدقاءك، وأخبر أحد الكبار."},{question:"يداك مبلّلتان، وتريد أن تُشعل الضوء. ماذا تفعل؟",options:[{text:"أُجفّف يديّ جيدًا أولًا",correct:!0,feedback:"صحيح. الماء ينقل الكهرباء، لذلك اليدان الجافّتان أكثر أمانًا."},{text:"أضغط على المفتاح بسرعة كبيرة",correct:!1,feedback:"لا. حتى اللمسة السريعة باليد المبلّلة خطيرة. جفّف يديك أولًا."},{text:"أنفض يديّ ثم أضغط عليه",correct:!1,feedback:"لا. النفض يترك الماء على يديك. جفّفهما جيدًا بمنشفة أولًا."}],explanation:"الماء ينقل الكهرباء. لا تلمس المفاتيح أو الأجهزة الكهربائية بيدين مبلّلتين أبدًا."}],steps:[{title:"توقّف وابتعد",detail:"إذا رأيت سلكًا مقطوعًا أو شرارات، فلا تقترب ولا تلمس.",critical:!0},{title:"أبعِد أصدقاءك",detail:"قل لأصدقائك أن يبتعدوا هم أيضًا.",critical:!0},{title:"أخبر أحد الكبار",detail:"أخبر أحد الكبار فورًا، وهو يطلب المساعدة.",critical:!0}]},{id:4,icon:"TrafficCone",accent:"#2563eb",title:"السلامة على الطرق",subtitle:"الشارع وحركة المرور",grades:"1-2",ages:"6-8",summary:"الشارع مكانٌ مليء بالمخاطر على الأطفال. هيّا نتعلّم كيف نعبر الطريق بأمان.",blocks:[{heading:"اعبر من ممرّ المشاة",body:"اعبر الطريق دائمًا على الخطوط البيضاء لممرّ المشاة (خطوط الحمار الوحشي).",image:"media/images/crosswalk.png"},{heading:"انظر إلى اليسار واليمين",body:"قف على حافة الطريق. انظر إلى اليسار، ثم إلى اليمين، ثم إلى اليسار مرةً أخرى. وعندما يكون الطريق خاليًا، اعبر بهدوء.",image:"media/images/look_both.png"},{heading:"لغة إشارات المرور",body:"انظر إلى إشارة المشاة، وهي التي فيها صورة شخص صغير. الشخص الأحمر = انتظر على الرصيف. الشخص الأخضر = انظر إلى اليسار ثم اليمين ثم اليسار مرة أخرى، ثم اعبر مباشرة مع شخص كبير. أما الإشارات الكبيرة فهي للسائقين: عندما تكون خضراء تسير السيارات.",image:"media/images/traffic_lights.png"}],examples:["انتبه إلى إشارة المرور.","انظر إلى اليسار واليمين.","اعبر على خطوط المشاة.","أمسك يد أحد الكبار."],tips:["انزع السمّاعات من أذنيك في الشارع.","أمسك يد أحد الكبار عندما تعبر.","كن حذرًا جدًا في الشوارع التي ليس فيها إشارات مرور."],warnings:["لا تعبر أبدًا من بين السيارات المتوقفة!"],realCase:"علّمت تلميذةٌ أصدقاءها كيف يعبرون الطريق بأمان. والآن يذهبون جميعًا إلى المدرسة بسلام!",video:"media/videos/lesson_road.mp4",game:{instruction:"في إشارة المشاة، ماذا يعني الشخص الأخضر؟",items:[{text:"قف",emoji:"🔴",correct:!1},{text:"انظر، ثم اعبر مع شخص كبير",emoji:"🟢",correct:!0},{text:"اركض بسرعة",emoji:"🏃",correct:!1},{text:"اعبر من بين السيارات",emoji:"🚗",correct:!1}]},activity:{prompt:"إشارة المشاة تُظهر الشخص الأحمر، والسيارات قادمة. ماذا ستفعل؟",image:"media/images/activity_road.png",options:[{text:"أنتظر على الرصيف حتى يظهر الشخص الأخضر، ثم أنظر إلى اليسار واليمين ثم اليسار مرة أخرى، وأعبر مع شخص كبير",correct:!0,feedback:"انتظار الشخص الأخضر والنظر مرة أخرى يحميانك من السيارات."},{text:"أركض بسرعة",correct:!1,feedback:"السيارات قادمة والإشارة حمراء؛ الركض ليس آمنًا، لذلك انتظر على الرصيف."},{text:"أعبر دون أن أنظر",correct:!1,feedback:"إذا لم تنظر فلن ترى السيارات؛ انتظر الشخص الأخضر، وانظر إلى اليسار ثم اليمين ثم اليسار مرة أخرى."},{text:"أعبر من بين السيارات",correct:!1,feedback:"العبور من بين السيارات ليس آمنًا؛ اعبر على خطوط المشاة البيضاء عندما يظهر الشخص الأخضر."}]},quiz:[{question:"ماذا يعني الضوء الأحمر؟",options:[{text:"قف",correct:!0,feedback:"الأحمر يعني «قف»، لذلك انتظر بأمان على الرصيف."},{text:"امشِ",correct:!1,feedback:"الأحمر ليس للمشي: انتظر على الرصيف حتى يظهر الشخص الأخضر."},{text:"اركض بسرعة",correct:!1,feedback:"الركض والإشارة حمراء ليس آمنًا؛ قف وانتظر على الرصيف."}],explanation:"الأحمر يعني «قف»: عندما يظهر الشخص الأحمر، انتظر على الرصيف. وعندما يظهر الشخص الأخضر، انظر إلى اليسار ثم اليمين ثم اليسار مرة أخرى، واعبر مع شخص كبير."},{question:"ماذا تفعل قبل أن تعبر الطريق؟",options:[{text:"أنظر إلى اليسار واليمين",correct:!0,feedback:"النظر إلى اليسار ثم اليمين ثم اليسار مرة أخرى يُريك هل الطريق خالٍ أم لا."},{text:"أركض بسرعة كبيرة وأعبر",correct:!1,feedback:"الركض إلى الطريق ليس آمنًا؛ قف أولًا على الحافة وانظر إلى اليسار واليمين."},{text:"لا أفعل شيئًا",correct:!1,feedback:"قبل العبور، قف دائمًا وانظر إلى اليسار واليمين لتعرف أن الطريق خالٍ."}],explanation:"قف على حافة الطريق، وانظر إلى اليسار، ثم إلى اليمين، ثم إلى اليسار مرةً أخرى. ولا تعبر إلا عندما يكون الطريق خاليًا، وبهدوء."},{question:"من أين تعبر الطريق؟",options:[{text:"على الخطوط البيضاء لممرّ المشاة",correct:!0,feedback:"الخطوط البيضاء لممرّ المشاة هي مكان العبور؛ وقبل العبور انظر إلى اليسار ثم اليمين ثم اليسار مرةً أخرى."},{text:"من بين سيارتين متوقفتين",correct:!1,feedback:"لا تعبر أبدًا من بين السيارات المتوقفة؛ اعبر دائمًا على الخطوط البيضاء لممرّ المشاة."},{text:"من أيّ مكانٍ يبدو فيه الطريق قصيرًا",correct:!1,feedback:"لا تعبر من أيّ مكان؛ اعبر دائمًا على الخطوط البيضاء لممرّ المشاة."}],explanation:"اعبر الطريق دائمًا على الخطوط البيضاء لممرّ المشاة، ولا تعبر أبدًا من بين السيارات المتوقفة."},{question:"إشارة المشاة تُظهر الشخص الأخضر. ماذا تفعل أولًا؟",options:[{text:"أركض بسرعة قبل أن تصبح الإشارة حمراء",correct:!1,feedback:"لا. الركض قد يُسقطك في الطريق. انظر أولًا، ثم اعبر بهدوء."},{text:"أعبر فورًا من دون أن أنظر",correct:!1,feedback:"لا. بعض السائقين لا يتوقّفون. انظر دائمًا يسارًا ويمينًا ثم يسارًا."},{text:"أنظر يسارًا ويمينًا ثم يسارًا، ثم أعبر",correct:!0,feedback:"صحيح. قد تكون سيارةٌ ما زالت قادمة. اعبر فقط عندما يكون الطريق خاليًا."}],explanation:"حتى مع الشخص الأخضر، انظر يسارًا ويمينًا ثم يسارًا. واعبر فقط عندما يكون الطريق خاليًا."},{question:"تدحرجت كرتك إلى الطريق. ماذا تفعل؟",options:[{text:"أبقى على الرصيف وأطلب من أحد الكبار",correct:!0,feedback:"صحيح. الكرة تستطيع أن تنتظر، والكبير يستطيع أن يُحضرها بأمان."},{text:"أركض خلفها بسرعة قبل أن تأتي سيارة",correct:!1,feedback:"لا. قد لا يراك السائقون. لا تركض إلى الطريق أبدًا."},{text:"أمرّ بين السيارات المتوقفة لأُحضرها",correct:!1,feedback:"لا. السائقون لا يستطيعون رؤيتك بين السيارات المتوقفة. اطلب من أحد الكبار."}],explanation:"لا تركض إلى الطريق من أجل كرة أبدًا. ابقَ على الرصيف، واطلب المساعدة من أحد الكبار."}],steps:[{title:"توقّف عند الحافة",detail:"توقّف على الرصيف عند حافة الطريق.",critical:!0},{title:"انظر يسارًا ويمينًا ثم يسارًا",detail:"انظر إلى اليسار، ثم إلى اليمين، ثم إلى اليسار مرةً أخرى.",critical:!0},{title:"انتظر الشخص الأخضر",detail:"عند الإشارة، انتظر الشخص الأخضر، وأمسك يد أحد الكبار.",critical:!1},{title:"اعبر مباشرةً",detail:"عندما يصبح الطريق خاليًا، اعبر بهدوء على ممرّ المشاة. لا تركض.",critical:!1}]},{id:5,icon:"HeartPulse",accent:"#16a34a",title:"الإسعافات الأولية",subtitle:"أساسيات الإسعافات الأولية",grades:"3-4",ages:"8-10",summary:"الإسعافات الأولية هي مساعدةٌ فورية لشخصٍ مصاب أو مريض قبل أن تصل سيارة الإسعاف. إذا كانت إصابة شخصٍ ما أو مرضه خطيرًا، فأخبر أحد الكبار ليتصل بالرقم 122 (الإسعاف).",blocks:[{heading:"الجروح الصغيرة",body:"اغسل الجرح بماءٍ نظيف، وضع عليه ضمادةً نظيفة، وأخبر أحد الكبار.",image:"media/images/first_aid_wound.png"},{heading:"الحروق",body:"ضع مكان الحرق تحت ماءٍ جارٍ بارد لمدة 20 دقيقة. لا تضع عليه ثلجًا أو زبدةً أو معجون أسنان. أخبر أحد الكبار؛ ففي الحروق الشديدة يتصلون بالرقم 122.",image:"media/images/first_aid_burn.png"},{heading:"صندوق الإسعافات الأولية",body:"يجب أن يكون في كل منزلٍ ومدرسة صندوقٌ للإسعافات الأولية.",image:"media/images/first_aid_kit.png"}],examples:["استخدم ضمادةً نظيفة.","للحرق: ماءٌ بارد لمدة 20 دقيقة.","الإسعاف = 122؛ أخبر أحد الكبار.","اعرف مكان صندوق الإسعافات الأولية."],tips:["اغسل يديك قبل وضع الضمادة.","لا تلمس داخل الجرح بيدك.","تحدّث مع المصاب بهدوء."],warnings:["لا تعطِ أحدًا أدويةً من تلقاء نفسك أبدًا! قدّم المساعدة البسيطة فقط، وأخبر الكبار."],realCase:"سقط تلميذٌ في الساحة فجُرحت ركبته. فأخبر أحد أصدقائه المعلّمَ فورًا، فنظّف المعلّم الجرح وضمّده، وسرعان ما شُفي!",video:"media/videos/lesson_firstaid.mp4",game:{instruction:"ماذا يوجد في صندوق الإسعافات الأولية؟",items:[{text:"ضمادة",emoji:"🩹",correct:!0},{text:"حلوى",emoji:"🍬",correct:!1},{text:"قطن",emoji:"🩹",correct:!0},{text:"دمية",emoji:"🧸",correct:!1}]},activity:{prompt:"سقط صديقك والدم يسيل من يده. ماذا ستفعل؟",image:"media/images/activity_fa.png",options:[{text:"أضغط على الجرح بمنديلٍ نظيف، وأخبر المعلّم فورًا",correct:!0,feedback:"المنديل النظيف على الجرح يساعد، وبإخبار المعلّم يحصل صديقك على المساعدة بسرعة."},{text:"لا أفعل شيئًا",correct:!1,feedback:"صديقك يحتاج إلى المساعدة؛ اضغط على الجرح بمنديلٍ نظيف وأخبر المعلّم فورًا."},{text:"أركض وأبتعد",correct:!1,feedback:"إذا ركضت بعيدًا بقي صديقك بلا مساعدة؛ أخبر المعلّم فورًا."},{text:"أتابع لعبي",correct:!1,feedback:"صديقك مصاب ويحتاج إلى المساعدة الآن؛ توقّف عن اللعب وأخبر المعلّم فورًا."}]},quiz:[{question:"ماذا نفعل لحرقٍ صغير؟",options:[{text:"ماءٌ جارٍ بارد لمدة 20 دقيقة",correct:!0,feedback:"الماء الجاري البارد لمدة 20 دقيقة يبرّد الحرق؛ ثم أخبر أحد الكبار."},{text:"بعض البهارات من المطبخ",correct:!1,feedback:"للحرق استخدم ماءً جاريًا باردًا لمدة 20 دقيقة، لا البهارات."},{text:"زبدة، كي يقلّ ألم الحرق",correct:!1,feedback:"لا! الزبدة تجعل الحرق أسوأ."}],explanation:"ضع مكان الحرق تحت ماءٍ جارٍ بارد لمدة 20 دقيقة. لا تضع عليه ثلجًا أو زبدةً أو معجون أسنان، وأخبر أحد الكبار."},{question:"ماذا نفعل بأيدينا قبل وضع الضمادة؟",options:[{text:"نغسلها",correct:!0,feedback:"اليدان النظيفتان تساعدان على بقاء الجرح نظيفًا."},{text:"لا نفعل شيئًا",correct:!1,feedback:"اغسل يديك أولًا، لكي يبقى الجرح نظيفًا."},{text:"ننظّفها بملابسنا",correct:!1,feedback:"مسح اليدين بالملابس ليس غسلًا؛ اغسل يديك قبل وضع الضمادة."}],explanation:"اغسل يديك قبل وضع الضمادة، لكي يبقى الجرح نظيفًا. ولا تلمس داخل الجرح."},{question:"صديقك مريض. هل يمكنك أن تعطيه دواءً من تلقاء نفسك؟",options:[{text:"لا، أُخبر أحد الكبار",correct:!0,feedback:"لا تعطِ أحدًا أدويةً من تلقاء نفسك أبدًا؛ قدّم المساعدة البسيطة فقط، وأخبر أحد الكبار."},{text:"نعم، دواءً من المنزل",correct:!1,feedback:"لا تعطِ أحدًا أدويةً من تلقاء نفسك أبدًا، حتى لو كانت من المنزل؛ أخبر أحد الكبار."},{text:"نعم، إذا طلب ذلك",correct:!1,feedback:"حتى لو طلبه منك، لا تعطِه دواءً من تلقاء نفسك؛ أخبر أحد الكبار."}],explanation:"لا تعطِ أحدًا أدويةً من تلقاء نفسك أبدًا! قدّم المساعدة البسيطة فقط، وأخبر الكبار."},{question:"صديقتك حرقت يدها بقِدرٍ ساخن. ماذا تفعل أولًا؟",options:[{text:"أضع عليه الثلج ليبرد بسرعة",correct:!1,feedback:"لا. لا تضع الثلج على الحرق أبدًا. استخدم الماء الجاري البارد."},{text:"أضع يدها تحت ماءٍ جارٍ بارد وأُخبر أحد الكبار",correct:!0,feedback:"صحيح. الماء الجاري البارد مدة 20 دقيقة يساعد الحرق، وسيساعد الكبير أيضًا."},{text:"أضع عليه معجون الأسنان كما يفعل بعض الناس",correct:!1,feedback:"لا. لا تضع معجون الأسنان أو الزبدة على الحرق. استخدم الماء الجاري البارد."}],explanation:"ضع مكان الحرق تحت ماءٍ جارٍ بارد لمدة 20 دقيقة، وأخبر أحد الكبار. لا ثلج ولا زبدة ولا معجون أسنان."},{question:"سقط صديقك وخرج منه دمٌ كثير. ماذا تفعل؟",options:[{text:"أغسله ببطء وأنتظر",correct:!1,feedback:"لا. لا تنتظر مع الجرح الكبير. نادِ أحد الكبار فورًا."},{text:"أضع ضمادةً صغيرة ونُكمل اللعب",correct:!1,feedback:"لا. الضمادة الصغيرة للجروح الصغيرة. الجرح الكبير يحتاج إلى أحد الكبار الآن."},{text:"أنادي أحد الكبار فورًا",correct:!0,feedback:"صحيح. الجرح الكبير يحتاج إلى أحد الكبار بسرعة، وهو يتصل بالرقم 122."}],explanation:"الجروح الصغيرة تحتاج إلى مساعدةٍ بسيطة. أمّا الجرح الكبير فيحتاج إلى أحد الكبار بسرعة، وهو يتصل بالرقم 122 (الإسعاف)."}],steps:[{title:"أخبر أحد الكبار",detail:"أخبر أحد الكبار أن شخصًا قد أُصيب.",critical:!0},{title:"اغسل يديك",detail:"اغسل يديك قبل أن تساعد.",critical:!1},{title:"نظّف الجرح الصغير",detail:"اغسل الجرح الصغير بماءٍ نظيف. لا تلمس داخل الجرح.",critical:!1},{title:"غطِّ الجرح",detail:"ضع ضمادةً نظيفة على الجرح.",critical:!1}]},{id:6,icon:"Waves",accent:"#0891b2",title:"الفيضان والسلامة من المياه",subtitle:"خطر الفيضانات",grades:"2-3",ages:"7-9",summary:"يحدث الفيضان عندما يهطل المطر بغزارة وتتجمّع المياه. الفيضان خطير، ويمكن أن يجرف معه الأشياء والناس.",blocks:[{heading:"ابتعد عن مياه الفيضان",body:"لا تدخل أبدًا في مياه الفيضان. فالماء الجاري بعمق 15 سنتيمترًا فقط يمكن أن يُسقط الإنسان، وبعمق 30 سنتيمترًا يمكن أن يجرف سيارة.",image:"media/images/flood_danger.png"},{heading:"اذهب إلى مكانٍ مرتفع",body:"إذا جاء الفيضان، فاذهبوا فورًا مع الكبار إلى مكانٍ مرتفع.",image:"media/images/flood_high.png"},{heading:"تحذيرات الطقس",body:"استمع إلى تحذيرات الطقس وإلى إرشادات الكبار، وكن مستعدًا.",image:"media/images/flood_warning.png"}],examples:["إذا كان منزلك في مكانٍ مرتفع، فابقَ في المنزل.","اذهب إلى مكانٍ مرتفع.","استمع إلى التحذيرات.","لا تلعب في مياه الفيضان."],tips:["عندما يأتي الفيضان، لا تذهب إلى الأماكن المنخفضة والوديان.","أخبر الكبار.","استعدّ قبل موسم الأمطار."],warnings:["لا تدخل أبدًا في مياه الفيضان ولا تسبح فيها! فمياه الفيضان أقوى منك."],realCase:"أثناء مطرٍ غزير جدًا، دخل الماء إلى الشارع. فأخذ أبٌ أطفاله إلى الطابق الثالث من المبنى، وبقي الجميع سالمين!",video:"media/videos/lesson_flood.mp4",game:{instruction:"ماذا نفعل أثناء الفيضان؟",items:[{text:"اذهب إلى مكانٍ مرتفع",emoji:"⬆️",correct:!0},{text:"اسبح في الماء",emoji:"🏊",correct:!1},{text:"ابقَ في الطابق العلوي من المنزل",emoji:"🏠",correct:!0},{text:"اعبر الماء بالسيارة",emoji:"🚗",correct:!1}]},activity:{prompt:"المطر يهطل بغزارة والماء يتجمّع في الشارع. ماذا ستفعل؟",image:"media/images/activity_flood.png",options:[{text:"أذهب مع الكبار إلى مكانٍ مرتفع",correct:!0,feedback:"الذهاب مع الكبار إلى مكانٍ مرتفع يُبقيك بعيدًا عن مياه الفيضان."},{text:"أمشي في الماء",correct:!1,feedback:"الماء الجاري بعمق 15 سنتيمترًا فقط يمكن أن يُسقط الإنسان؛ لا تمشِ أبدًا في مياه الفيضان."},{text:"أقف بالقرب من الماء وأتفرّج",correct:!1,feedback:"الفيضان يمكن أن يجرف الناس، فلا تبقَ قرب الماء؛ اذهب مع الكبار إلى مكانٍ مرتفع."},{text:"أسبح",correct:!1,feedback:"مياه الفيضان أقوى منك حتى لو كنت تعرف السباحة؛ اذهب مع الكبار إلى مكانٍ مرتفع."}]},quiz:[{question:"إذا جاء الفيضان، فإلى أين نذهب؟",options:[{text:"إلى مكانٍ مرتفع",correct:!0,feedback:"المكان المرتفع يُبقيك بعيدًا عن مياه الفيضان."},{text:"إلى الأماكن المنخفضة",correct:!1,feedback:"الأماكن المنخفضة والوديان ليست آمنة أثناء الفيضان؛ اذهب مع الكبار إلى مكانٍ مرتفع."},{text:"إلى داخل الماء",correct:!1,feedback:"مياه الفيضان أقوى منك ويمكن أن تجرفك؛ لا تدخل فيها أبدًا."}],explanation:"مياه الفيضان أقوى منك: فالماء الجاري بعمق 15 سنتيمترًا فقط يمكن أن يُسقط الإنسان. اذهب فورًا مع الكبار إلى مكانٍ مرتفع."},{question:"أنت تعرف السباحة جيدًا. هل يمكنك أن تسبح في مياه الفيضان؟",options:[{text:"لا، فهي أقوى منك",correct:!0,feedback:"مياه الفيضان أقوى منك حتى لو كنت تعرف السباحة؛ لا تدخل فيها أبدًا."},{text:"نعم، إذا بدا الماء هادئًا",correct:!1,feedback:"لا تسبح أبدًا في مياه الفيضان: فهي أقوى منك، ويمكن أن تجرف الناس."},{text:"نعم، إذا سبح معي صديق",correct:!1,feedback:"الصديق لا يجعل مياه الفيضان آمنة، لأن مياه الفيضان أقوى منك؛ اذهب مع الكبار إلى مكانٍ مرتفع."}],explanation:"لا تدخل أبدًا في مياه الفيضان ولا تسبح فيها! فمياه الفيضان أقوى منك حتى لو كنت تعرف السباحة، ويمكن أن تجرف الناس."},{question:"الفيضان قادم، ومنزلك في مكانٍ مرتفع. ماذا تفعل؟",options:[{text:"أبقى في المنزل مع الكبار",correct:!0,feedback:"إذا كان منزلك في مكانٍ مرتفع، فالبقاء في المنزل يُبقيك بعيدًا عن مياه الفيضان."},{text:"أخرج لأتفرّج على الماء",correct:!1,feedback:"لا تقترب من مياه الفيضان؛ إذا كان منزلك في مكانٍ مرتفع، فابقَ في المنزل."},{text:"أنزل إلى الوادي",correct:!1,feedback:"عندما يأتي الفيضان، فالأماكن المنخفضة والوديان ليست آمنة؛ ابقَ في منزلك المرتفع."}],explanation:"إذا كان منزلك في مكانٍ مرتفع، فابقَ في المنزل. وعندما يأتي الفيضان، لا تذهب إلى الأماكن المنخفضة والوديان، ولا تدخل أبدًا في مياه الفيضان."},{question:"قليلٌ من الماء الجاري يمرّ فوق الطريق. هل تستطيع أن تمشي فيه؟",options:[{text:"لا، الماء الجاري قد يُسقطني",correct:!0,feedback:"صحيح. الماء الجاري بعمق 15 سنتيمترًا فقط يمكن أن يُسقط الإنسان."},{text:"نعم، إذا مشيت ببطء وحذر",correct:!1,feedback:"لا. الماء الجاري أقوى منك، حتى لو مشيت ببطء."},{text:"نعم، إذا أمسكت يد صديقي",correct:!1,feedback:"لا. الماء قد يُسقطكما معًا. لا تدخل الماء، وأخبر أحد الكبار."}],explanation:"الماء الجاري بعمق 15 سنتيمترًا فقط يمكن أن يُسقط الإنسان. لا تدخل مياه الفيضان أبدًا."},{question:"هطل مطرٌ كثير، وأصدقاؤك يريدون اللعب في الوادي. ماذا تفعل؟",options:[{text:"أذهب معهم، ولكن لوقتٍ قصير فقط",correct:!1,feedback:"لا. الفيضان قد يأتي بسرعة كبيرة. لا تذهب إلى الأماكن المنخفضة."},{text:"أبقى بعيدًا عن الوادي وأُخبر أحد الكبار",correct:!0,feedback:"صحيح. الأماكن المنخفضة والوديان ليست آمنة عندما قد يأتي الفيضان."},{text:"أذهب معهم وأقف على صخرةٍ كبيرة هناك",correct:!1,feedback:"لا. مياه الفيضان قد تغطّي الصخور أيضًا. ابقَ بعيدًا عن الوادي."}],explanation:"عندما قد يأتي الفيضان، لا تذهب إلى الأماكن المنخفضة والوديان. ابقَ بعيدًا، وأخبر أحد الكبار."}],media:[{kind:"image",src:"media/images/primary3d_flood_escape.webp",title:"اذهب إلى مكانٍ مرتفع",description:"إذا جاء الفيضان، فاذهبوا فورًا مع الكبار إلى مكانٍ مرتفع."}],steps:[{title:"استمع إلى التحذيرات",detail:"استمع إلى الكبار وإلى تحذيرات الطقس.",critical:!1},{title:"اذهب إلى مكانٍ مرتفع",detail:"اذهب مع الكبار إلى مكانٍ مرتفع فورًا.",critical:!0},{title:"ابتعد عن مياه الفيضان",detail:"لا تمشِ في مياه الفيضان أبدًا، ولا تلعب أو تسبح فيها.",critical:!0},{title:"ابقَ مع الكبار",detail:"ابقَ مع الكبار حتى يقولوا إن المكان آمن.",critical:!1}]},{id:7,icon:"Wind",accent:"#059669",title:"تسرّب الغاز",subtitle:"كيف نعرف خطر الغاز",grades:"3-4",ages:"8-10",summary:"يُستخدم الغاز للطبخ ولتدفئة المنزل. تسرّب الغاز خطير، وقد يسبّب حريقًا أو انفجارًا.",blocks:[{heading:"رائحة الغاز",body:"إذا شممت رائحةً تشبه رائحة البيض الفاسد، فربما يكون الغاز قد تسرّب!",image:"media/images/gas_smell.png"},{heading:"افتح النوافذ",body:"إذا استطعت ذلك بسهولة في طريقك إلى الخارج، فافتح النوافذ والأبواب ليخرج الغاز. ولا تبقَ في الداخل من أجل ذلك: اخرج من المنزل فورًا.",image:"media/images/gas_ventilate.png"},{heading:"لا تُشعل النار!",body:"لا تُشعل عود ثقاب أو ولّاعة، ولا تلمس مفاتيح الكهرباء، ولا تستخدم الهاتف داخل المنزل. فحتى الشرارة الصغيرة يمكن أن تسبّب انفجارًا.",image:"media/images/gas_no_fire.png"}],examples:["رائحة البيض الفاسد = غاز.","افتح النوافذ.","لا تُشعل النار!","اخرجوا، واتصلوا بالرقم 115 من الخارج."],tips:["الأطفال لا يُغلقون الغاز أبدًا: اخرج وأخبر أحد الكبار.","يجب على الكبار أن يفحصوا أنابيب الغاز باستمرار.","اتصلوا بالرقم 115 من خارج المنزل."],warnings:["عندما تشمّ رائحة الغاز، لا تلمس مفاتيح الكهرباء ولا تُشعل النار!"],realCase:"شمّ طفلٌ رائحة الغاز في المطبخ، فلم يلمس المفاتيح، وأخبر والده. فخرج الجميع من المنزل، واتصل الأب بالرقم 115 من الخارج، وبقي الجميع سالمين!",video:"media/videos/lesson_gas.mp4",game:{instruction:"عند شمّ رائحة الغاز، أيّ هذه الأفعال لا يجوز أن نفعلها؟",items:[{text:"نُشعل عود ثقاب",emoji:"🔥",correct:!0},{text:"نفتح النافذة",emoji:"🪟",correct:!1},{text:"نُشغّل مفتاح الكهرباء",emoji:"💡",correct:!0},{text:"نخرج من المنزل",emoji:"🚶",correct:!1}]},activity:{prompt:"في المنزل رائحةٌ تشبه رائحة البيض الفاسد. ماذا ستفعل؟",image:"media/images/activity_gas.png",options:[{text:"لا ألمس المفاتيح، وأخرج وأفتح نافذة في طريقي إن كان ذلك سهلًا، وأخبر أحد الكبار",correct:!0,feedback:"بعدم لمس المفاتيح لا تحدث شرارة، وبالخروج وإخبار أحد الكبار يبقى الجميع آمنين."},{text:"أُشعل المصباح لأرى جيدًا",correct:!1,feedback:"المفتاح قد يُحدث شرارةً صغيرة، والشرارة قد تسبّب انفجارًا؛ لا تلمس المفاتيح."},{text:"أبقى في المنزل",correct:!1,feedback:"الغاز قد يسبّب حريقًا أو انفجارًا، لذلك اخرج من المنزل فورًا وأخبر أحد الكبار."},{text:"أُشعل عود ثقاب",correct:!1,feedback:"عود الثقاب قد يسبّب انفجارًا؛ لا تُشعل النار أبدًا، واخرج وأخبر أحد الكبار."}]},quiz:[{question:"كيف تكون رائحة الغاز؟",options:[{text:"مثل البيض الفاسد",correct:!0,feedback:"رائحةٌ تشبه البيض الفاسد تنبّهك إلى أن الغاز ربما تسرّب."},{text:"مثل الورد",correct:!1,feedback:"رائحة الغاز ليست مثل الورد؛ بل تشبه البيض الفاسد لكي تنتبه إليها."},{text:"ليست له رائحة",correct:!1,feedback:"لا! تُضاف إلى الغاز رائحةٌ لكي نعرف بوجوده."}],explanation:"رائحة الغاز تشبه رائحة البيض الفاسد، لأن رائحةً تُضاف إليه لكي نعرف بوجوده. إذا شممتها، فلا تلمس المفاتيح، واخرج وأخبر أحد الكبار."},{question:"لماذا لا نلمس مفاتيح الكهرباء عندما نشمّ رائحة الغاز؟",options:[{text:"لأن الشرارة الصغيرة قد تسبّب انفجارًا",correct:!0,feedback:"المفتاح قد يُحدث شرارةً صغيرة، والشرارة قد تسبّب انفجارًا."},{text:"لأن المفتاح قد ينكسر",correct:!1,feedback:"الخطر ليس انكسار المفتاح: المفتاح قد يُحدث شرارةً صغيرة، والشرارة قد تسبّب انفجارًا."},{text:"لأن الضوء قد يجعل الرائحة أقوى",correct:!1,feedback:"الخطر ليس الرائحة: المفتاح قد يُحدث شرارةً صغيرة، والشرارة قد تسبّب انفجارًا."}],explanation:"عندما تشمّ رائحة الغاز، لا تلمس مفاتيح الكهرباء ولا تُشعل النار. فحتى الشرارة الصغيرة يمكن أن تسبّب انفجارًا."},{question:"تشمّ رائحة الغاز في المنزل. هل تُغلق الغاز بنفسك؟",options:[{text:"لا، أخرج وأُخبر أحد الكبار",correct:!0,feedback:"الأطفال لا يُغلقون الغاز أبدًا: اخرج وأخبر أحد الكبار، واتصلوا بالرقم 115 من خارج المنزل."},{text:"نعم، أُغلقه قبل أن أخرج",correct:!1,feedback:"الأطفال لا يُغلقون الغاز أبدًا، ولا يبقون في الداخل من أجل ذلك: اخرج فورًا وأخبر أحد الكبار."},{text:"نعم، إذا لم يكن في المنزل أحدٌ من الكبار",correct:!1,feedback:"حتى لو لم يكن في المنزل أحدٌ من الكبار، فالأطفال لا يُغلقون الغاز أبدًا: اخرج واتصل بالرقم 115 من خارج المنزل."}],explanation:"الأطفال لا يُغلقون الغاز أبدًا: اخرج وأخبر أحد الكبار. واتصلوا بالرقم 115 من خارج المنزل."},{question:"تشمّ رائحة الغاز والغرفة مظلمة. ماذا تفعل؟",options:[{text:"أُشعل الضوء لأرى الطريق",correct:!1,feedback:"لا. لا تلمس المفتاح أبدًا عندما تشمّ رائحة الغاز. اخرج في الظلام."},{text:"أخرج من دون أن أُشعل الضوء",correct:!0,feedback:"صحيح. المفتاح قد يُحدث شرارةً صغيرة، والشرارة قد تسبّب انفجارًا."},{text:"أستخدم ضوء الهاتف لأبحث عن مكان التسرّب",correct:!1,feedback:"لا. لا تستخدم الهاتف في الداخل، ولا تبحث عن التسرّب. اخرج."}],explanation:"عندما تشمّ رائحة الغاز: لا مفاتيح، ولا هاتف، ولا نار. اخرج، واتصل بالرقم 115 من الخارج."},{question:"خرجت بعد أن شممت رائحة الغاز، وأخوك الصغير يريد أن يعود إلى الداخل ليُحضر لعبته. ماذا تقول له؟",options:[{text:"لا، نبقى في الخارج وننتظر أحد الكبار",correct:!0,feedback:"صحيح. لا تعُد أبدًا إلى منزلٍ فيه غاز. انتظر في الخارج مع أحد الكبار."},{text:"نعم، إذا دخل وخرج بسرعةٍ كبيرة جدًا",correct:!1,feedback:"لا. حتى الوقت القصير في الداخل خطير. ابقيا في الخارج."},{text:"نعم، إذا أمسك أنفه بيده جيدًا",correct:!1,feedback:"لا. إمساك الأنف لا يوقف الخطر، فالشرارة قد تسبّب انفجارًا مع ذلك."}],explanation:"لا تعُد أبدًا إلى منزلٍ فيه غاز. ابقَ في الخارج، وأخبر أحد الكبار، واتصلوا بالرقم 115."}],steps:[{title:"لا تلمس شيئًا",detail:"داخل المنزل: لا مفاتيح كهرباء، ولا هاتف، ولا نار.",critical:!0},{title:"اخرج",detail:"اخرج من المنزل فورًا. افتح النافذة أو الباب فقط إذا كان في طريق خروجك.",critical:!0},{title:"أخبر أحد الكبار",detail:"أخبر أحد الكبار. الأطفال لا يُغلقون الغاز أبدًا.",critical:!0},{title:"اتصل بالرقم 115 من الخارج",detail:"إذا لم يكن أحدٌ من الكبار قريبًا، فاتصل بالرقم 115 من خارج المنزل.",critical:!0}]},{id:8,icon:"PhoneCall",accent:"#e11d48",title:"رقم الطوارئ 115",subtitle:"الاتصال لطلب المساعدة",grades:"1-2",ages:"6-8",summary:"الرقم 115 هو رقم الدفاع المدني: للحرائق، والإنقاذ، والزلازل، والفيضانات، وتسرّب الغاز. في حالات الطوارئ، أخبر أحد الكبار ليتصل بالرقم 115. وإذا لم يكن بالقرب منك أحدٌ من الكبار، فاتصل أنت بنفسك.",blocks:[{heading:"115 = الدفاع المدني",body:"الحريق، الزلزال، الفيضان، الانفجار، انهيار المباني = اتصل بالرقم 115",image:"media/images/call_115.png"},{heading:"ماذا أقول؟",body:"قل أولًا أين أنت (عنوان المكان أو مكانًا قريبًا منك). ثم قل ما الذي حدث، وكم شخصًا هناك، وهل يوجد مصابون، واذكر اسمك. لا تُغلق الهاتف حتى يطلبوا منك ذلك.",image:"media/images/what_to_say.png"},{heading:"لا تمزح",body:"لا تتصل بالرقم 115 للّعب أبدًا! فقد يكون شخصٌ آخر بحاجةٍ إلى المساعدة.",image:"media/images/no_prank.png"}],examples:["115 = الدفاع المدني.","122 = الإسعاف.","104 = الشرطة.","احفظ هذه الأرقام."],tips:["احفظ عنوان منزلك.","تحدّث بهدوء.","استمع إلى التعليمات."],warnings:["لا تتصل بالرقم 115 للّعب! فهذا تصرّفٌ خاطئ وممنوع."],realCase:"رأى طفلٌ عمره 10 سنوات نارًا بالقرب من منزله، فأخبر أمّه فورًا، فاتصلت أمّه بالرقم 115، وجاء فريق الدفاع المدني بسرعة!",video:"media/videos/lesson_115.mp4",game:{instruction:"الرقم 115 لِمَن؟",items:[{text:"الدفاع المدني",emoji:"🚒",correct:!0},{text:"الشرطة",emoji:"👮",correct:!1},{text:"الإسعاف",emoji:"🏥",correct:!1},{text:"فريق الإطفاء",emoji:"🧯",correct:!0}]},activity:{prompt:"هناك نارٌ بالقرب من المنزل، ولا يوجد أحدٌ من الكبار معك. ماذا ستفعل؟",image:"media/images/activity_115.png",options:[{text:"أبتعد عن النار، وأتصل بالرقم 115، وأذكر عنوان المكان",correct:!0,feedback:"الابتعاد عن النار يحميك، وبذكر عنوان المكان يصل الفريق بسرعة."},{text:"أطفئ النار بنفسي",correct:!1,feedback:"الأطفال لا يُطفئون النار؛ ابتعد، واتصل بالرقم 115، واذكر عنوان المكان."},{text:"أبقى قريبًا وأتفرّج",correct:!1,feedback:"البقاء قرب النار ليس آمنًا؛ ابتعد واتصل بالرقم 115."},{text:"أدخل إلى المنزل",correct:!1,feedback:"دخول المنزل يعرّضك للخطر؛ ابقَ في الخارج، وابتعد، واتصل بالرقم 115."}]},quiz:[{question:"لِمَن الرقم 115؟",options:[{text:"الدفاع المدني",correct:!0,feedback:"الرقم 115 للدفاع المدني: الحرائق والإنقاذ والزلازل والفيضانات وتسرّب الغاز."},{text:"شرطة المرور",correct:!1,feedback:"لا، رقم الشرطة هو 104."},{text:"سيارة الإسعاف",correct:!1,feedback:"لا، رقم الإسعاف هو 122."}],explanation:"الرقم 115 هو رقم الدفاع المدني: للحرائق والإنقاذ والزلازل والفيضانات وتسرّب الغاز. أمّا رقم الشرطة فهو 104، ورقم الإسعاف 122."},{question:"عندما تتصل بالرقم 115، ماذا تقول أولًا؟",options:[{text:"أين أنت",correct:!0,feedback:"عندما تذكر عنوان المكان أولًا يصل الفريق بسرعة."},{text:"اسمك",correct:!1,feedback:"اسمك تذكره في النهاية؛ قل أولًا أين أنت، لكي يصل الفريق بسرعة."},{text:"اسم مدرستك",correct:!1,feedback:"اسم مدرستك ليس أول شيء؛ قل أولًا أين أنت، لكي يصل الفريق بسرعة."}],explanation:"قل أولًا أين أنت (عنوان المكان أو مكانًا قريبًا منك). ثم قل ما الذي حدث، وكم شخصًا هناك، وهل يوجد مصابون، واذكر اسمك."},{question:"عندما تتصل بالرقم 115، متى يمكنك أن تُغلق الهاتف؟",options:[{text:"فقط عندما يطلبون منك ذلك",correct:!0,feedback:"لا تُغلق الهاتف حتى يطلبوا منك ذلك؛ تحدّث بهدوء واستمع إلى التعليمات."},{text:"فور أن تذكر العنوان",correct:!1,feedback:"لا تُغلق الهاتف بعد: استمع إلى التعليمات وانتظر حتى يطلبوا منك ذلك."},{text:"بعد أن تذكر اسمك",correct:!1,feedback:"ذكر اسمك ليس نهاية المكالمة؛ لا تُغلق الهاتف حتى يطلبوا منك ذلك."}],explanation:"لا تُغلق الهاتف حتى يطلبوا منك ذلك. تحدّث بهدوء، واستمع إلى التعليمات."},{question:"منزلك يحترق، ولا يوجد معك أحدٌ من الكبار. من أين تتصل بالرقم 115؟",options:[{text:"من الداخل، قبل أن أخرج",correct:!1,feedback:"لا. النار والدخان ينتشران بسرعة. اخرج أولًا ثم اتصل."},{text:"من غرفتي، والباب مُغلق",correct:!1,feedback:"لا. لا تبقَ في الداخل لتتصل. اخرج أولًا."},{text:"من الخارج، بعد أن أخرج",correct:!0,feedback:"صحيح. اخرج أولًا ثم اتصل، فحياتك تأتي أولًا."}],explanation:"اخرج أولًا، ثم اتصل بالرقم 115 من الخارج. فحياتك تأتي أولًا."},{question:"لا يوجد معك أحدٌ من الكبار، وترى حريقًا كبيرًا. بأيّ رقم تتصل؟",options:[{text:"122",correct:!1,feedback:"لا. الرقم 122 هو الإسعاف، للمرضى والمصابين."},{text:"115",correct:!0,feedback:"صحيح. الرقم 115 هو الدفاع المدني، للحريق والإنقاذ."},{text:"104",correct:!1,feedback:"لا. الرقم 104 هو الشرطة. للحريق اتصل بالرقم 115."}],explanation:"الرقم 115 هو الدفاع المدني للحريق، والرقم 122 هو الإسعاف، والرقم 104 هو الشرطة."}],steps:[{title:"ابتعد عن الخطر أولًا",detail:"ابتعد عن الخطر، وأخبر أحد الكبار.",critical:!0},{title:"اتصل بالرقم 115",detail:"إذا لم يكن أحدٌ من الكبار قريبًا، فاتصل بالرقم 115 وتحدّث بهدوء.",critical:!0},{title:"قل أين أنت أولًا",detail:"قل العنوان أو مكانًا قريبًا منك. ثم قل ماذا حدث، وهل هناك مصابون، واسمك.",critical:!1},{title:"لا تُغلق الهاتف",detail:"استمع، ولا تُغلق الهاتف حتى يطلبوا منك ذلك.",critical:!1}]},{id:9,icon:"DoorOpen",accent:"#7c3aed",title:"خطة الإخلاء",subtitle:"الخروج الآمن",grades:"3-4",ages:"8-10",summary:"تحدّد خطة الإخلاء الطريق الذي نخرج منه من المبنى بأمان، والمكان الذي نتجمّع فيه.",blocks:[{heading:"طرق الخروج",body:"يجب أن يكون في كل منزلٍ ومدرسة طريقان للخروج على الأقل.",image:"media/images/exit_routes.png"},{heading:"نقطة التجمع",body:"هي مكانٌ آمن خارج المبنى، يتجمّع فيه الجميع ليتأكّدوا أنه لم يبقَ أحدٌ في الداخل.",image:"media/images/assembly_point.png"},{heading:"التدريب",body:"تدرّبوا على الإخلاء في المنزل وفي المدرسة مرةً كل ثلاثة أشهر.",image:"media/images/evacuation_drill.png"}],examples:["اعرف طريقين للخروج.","اعرف نقطة التجمع.","اخرج بهدوء.","ارسم خريطة الإخلاء."],tips:["ارسم مع عائلتك خريطة المنزل.","اعرف طرق الخروج جيدًا، بحيث تستطيع الخروج حتى في الظلام.","حدّد نقطة التجمع."],warnings:["أثناء الحريق أو الزلزال لا تستخدم المصعد، بل استخدم السلالم!"],realCase:"خرج تلاميذ إحدى المدارس بسرعة وأمان، لأنهم كانوا قد تدرّبوا على ذلك من قبل!",video:"media/videos/lesson_evacuation.mp4",game:{instruction:"ماذا نستخدم للخروج الآمن؟",items:[{text:"السلالم",emoji:"🪜",correct:!0},{text:"المصعد",emoji:"🛗",correct:!1},{text:"باب مخرج الطوارئ",emoji:"🚪",correct:!0},{text:"النافذة",emoji:"🪟",correct:!1}]},activity:{prompt:"رنّ جرس الإنذار في المدرسة. ماذا ستفعل؟",image:"media/images/activity_evac.png",options:[{text:"أذهب بهدوء عبر السلالم إلى نقطة التجمع",correct:!0,feedback:"النزول بهدوء عبر السلالم آمن، وفي نقطة التجمع نتأكّد أنه لم يبقَ أحدٌ في الداخل."},{text:"أجمع أغراضي",correct:!1,feedback:"الخروج هو أول شيء، لذلك اترك أغراضك واذهب بهدوء إلى نقطة التجمع."},{text:"أنزل بالمصعد",correct:!1,feedback:"قد يتوقّف المصعد وتبقى عالقًا فيه؛ استخدم السلالم."},{text:"أختبئ",correct:!1,feedback:"إذا اختبأت فلن يعرف أحد أنك ما زلت في الداخل؛ اذهب إلى نقطة التجمع."}]},quiz:[{question:"ماذا نستخدم لنخرج من المبنى بأمان؟",options:[{text:"السلالم",correct:!0,feedback:"السلالم هي الطريق الآمن، لأن المصعد قد يتوقّف أثناء الحريق أو الزلزال."},{text:"المصعد",correct:!1,feedback:"لا! فقد يتوقّف المصعد وتبقى عالقًا فيه."},{text:"النافذة",correct:!1,feedback:"طريق الخروج الآمن هو السلالم وباب مخرج الطوارئ، لا النافذة."}],explanation:"أثناء الحريق أو الزلزال استخدم السلالم، لا المصعد. فقد يتوقّف المصعد وتبقى عالقًا فيه."},{question:"لماذا يتجمّع الجميع في نقطة التجمع؟",options:[{text:"لنتأكّد أنه لم يبقَ أحدٌ في الداخل",correct:!0,feedback:"في نقطة التجمع نرى أن الجميع خرجوا، وأنه لم يبقَ أحدٌ في الداخل."},{text:"ليتفرّج الجميع على ما يحدث",correct:!1,feedback:"نقطة التجمع ليست للتفرّج؛ ففيها نتأكّد أنه لم يبقَ أحدٌ في الداخل."},{text:"لكي نعود إلى الداخل ونأخذ حقائبنا",correct:!1,feedback:"الخروج هو أول شيء، لذلك اترك أغراضك؛ وفي نقطة التجمع نتأكّد أنه لم يبقَ أحدٌ في الداخل."}],explanation:"نقطة التجمع مكانٌ آمن خارج المبنى، يتجمّع فيه الجميع ليتأكّدوا أنه لم يبقَ أحدٌ في الداخل."},{question:"كم طريقًا للخروج يجب أن يكون في كل منزلٍ ومدرسة؟",options:[{text:"طريقان على الأقل",correct:!0,feedback:"صحيح: يجب أن يكون في كل منزلٍ ومدرسة طريقان للخروج على الأقل، ليبقى هناك دائمًا طريقٌ آخر."},{text:"طريقٌ واحد فقط، هو الباب الرئيسي",correct:!1,feedback:"طريقٌ واحد لا يكفي؛ يجب أن يكون في كل منزلٍ ومدرسة طريقان للخروج على الأقل."},{text:"طريقٌ واحد إذا كان كبيرًا",correct:!1,feedback:"حتى الباب الكبير هو طريقٌ واحد فقط؛ يجب أن يكون هناك طريقان للخروج على الأقل."}],explanation:"يجب أن يكون في كل منزلٍ ومدرسة طريقان للخروج على الأقل. واعرف طرق الخروج جيدًا، بحيث تستطيع الخروج حتى في الظلام."},{question:"النار تسدّ الباب الرئيسي لمنزلك. ماذا تفعل؟",options:[{text:"أستخدم طريق الخروج الثاني",correct:!0,feedback:"صحيح. لهذا يجب أن يكون في كل منزلٍ طريقان للخروج."},{text:"أنتظر عند الباب حتى تنطفئ النار",correct:!1,feedback:"لا. لا تنتظر قرب النار. استخدم طريق الخروج الآخر."},{text:"أختبئ في غرفتي تحت السرير",correct:!1,feedback:"لا. لا تختبئ أبدًا، فلن يستطيع فريق الدفاع المدني أن يجدك. استخدم الطريق الآخر."}],explanation:"إذا كان أحد طريقَي الخروج مسدودًا، فاستخدم الآخر. لهذا يجب أن يكون في كل منزلٍ طريقان للخروج على الأقل."},{question:"عائلتك عند نقطة التجمع، لكن أختك ليست هناك. ماذا تفعل؟",options:[{text:"أركض إلى الداخل لأبحث عنها",correct:!1,feedback:"لا. لا تعُد إلى الداخل أبدًا، فقد تعلق أنت أيضًا."},{text:"أُخبر أحد الكبار أو فريق 115 فورًا",correct:!0,feedback:"صحيح. لدى فريق 115 المعدّات للبحث عنها بأمان."},{text:"أنتظر بهدوء ولا أقول شيئًا",correct:!1,feedback:"لا. يجب أن يعرف الفريق أن شخصًا مفقود. أخبرهم فورًا."}],explanation:"لا تعُد إلى الداخل أبدًا. أخبر أحد الكبار أو فريق 115 بمن هو مفقود، وهم سيبحثون عنها."}],media:[{kind:"image",src:"media/images/primary3d_school_assembly.webp",title:"نقطة التجمع",description:"هي مكانٌ آمن خارج المبنى، يتجمّع فيه الجميع ليتأكّدوا أنه لم يبقَ أحدٌ في الداخل."}],steps:[{title:"جِد طريقين للخروج",detail:"ابحث مع عائلتك عن طريقين على الأقل للخروج من منزلك.",critical:!1},{title:"ارسم خريطة",detail:"ارسم خريطة منزلك، وحدّد عليها طرق الخروج.",critical:!1},{title:"حدّد نقطة التجمع",detail:"اختر مكانًا آمنًا في الخارج يجتمع فيه الجميع.",critical:!1},{title:"تدرّب",detail:"تدرّب مع عائلتك على الخروج حتى تعرف الطريق جيدًا.",critical:!1}]},{id:10,icon:"FireExtinguisher",accent:"#d97706",title:"معدّات إطفاء الحريق",subtitle:"مطفأة الحريق والأدوات الأخرى",grades:"4-5",ages:"9-11",summary:"مطفأة الحريق (Fire Extinguisher) جهازٌ مهم لإطفاء الحرائق الصغيرة، ويستخدمها الكبار المدرَّبون. أمّا دور الأطفال فهو أن يخرجوا، ويُخبروا أحد الكبار ليتمّ الاتصال بالرقم 115.",blocks:[{heading:"أنواع مطافئ الحريق",body:"هناك مطفأة المسحوق، ومطفأة ثاني أكسيد الكربون (CO₂)، ومطفأة الرغوة. وكل نوعٍ منها مخصّص لأنواعٍ معيّنة من الحرائق.",image:"media/images/ext_types.png"},{heading:"P.A.S.S",body:`الكبار هم من يقرّرون استخدام مطفأة الحريق. ولا يستخدمونها إلا إذا كانت النار صغيرة جدًا وفي بدايتها، ونُبِّه الجميع واتُّصل بالرقم 115، وكان طريق الخروج خلفهم وخاليًا من الدخان، وكانوا مدرَّبين. وإلّا يخرج الجميع. والأطفال لا يستخدمون المطفأة أبدًا: اخرج، وأخبر أحد الكبار، واتصل بالرقم 115.

يستخدم الكبار معظم مطافئ الحريق بهذه الخطوات الأربع: Pull (اسحب مسمار الأمان)، Aim (وجّه فوهة الخرطوم إلى قاعدة النار)، Squeeze (اضغط على المقبض)، Sweep (حرّكها من جانبٍ إلى آخر). ولبعض المطافئ الخاصة خطوات أخرى مكتوبة على ملصقها.`,image:"media/images/pass_method.png"},{heading:"للحرائق الصغيرة فقط",body:"مطفأة الحريق مخصّصة للحرائق الصغيرة جدًا فقط، ويستخدمها الكبار. الأطفال لا يُطفئون النار: اخرج، وأخبر أحد الكبار، واتصلوا بالرقم 115!",image:"media/images/when_use_ext.png"}],examples:["P = Pull: اسحب المسمار.","A = Aim: وجّهها إلى قاعدة النار.","S = Squeeze: اضغط على المقبض.","S = Sweep: حرّكها من جانبٍ إلى آخر."],tips:["يفحص الكبار مطفأة الحريق بالنظر كل شهر، ويأخذونها للصيانة كل سنة.","اعرف أماكن مطافئ الحريق في المدرسة.","أثناء الحريق، نادِ الكبار."],warnings:["الأطفال لا يُطفئون النار! مطفأة الحريق للكبار. أمّا أنت فاخرج، وأخبر أحد الكبار، واتصل بالرقم 115."],realCase:"اشتعلت نارٌ صغيرة في سلّة المهملات في أحد الصفوف. فخرج التلاميذ فورًا، وأخبر أحدهم المعلّم، وكان المعلّم مدرَّبًا، فتأكّد من إطلاق الإنذار والاتصال بالرقم 115. وكانت النار لا تزال صغيرة جدًا وطريق الخروج خلفه، فأطفأها بمطفأة الحريق مستخدمًا طريقة P.A.S.S.",video:"media/videos/lesson_extinguisher.mp4",game:{instruction:"ماذا تعني P.A.S.S؟",items:[{text:"خطوات استخدام مطفأة الحريق",emoji:"🧯",correct:!0},{text:"نوعٌ من الحرائق",emoji:"🔥",correct:!1},{text:"رقم الطوارئ",emoji:"📞",correct:!1},{text:"اسحب، وجّهها إلى قاعدة النار، اضغط، حرّك",emoji:"✅",correct:!0}]},activity:{prompt:"هناك نارٌ صغيرة في سلّة المهملات في الصف، ومطفأة الحريق قريبةٌ منك. ماذا ستفعل؟",image:"media/images/activity_ext.png",options:[{text:"أخرج من الصف فورًا، وأخبر المعلّم، ونتصل بالرقم 115",correct:!0,feedback:"الخروج وإخبار المعلّم والاتصال بالرقم 115 هو دور الأطفال، لا إطفاء النار."},{text:"أسكب الماء على النار",correct:!1,feedback:"الأطفال لا يُطفئون النار، حتى الصغيرة منها؛ اخرج من الصف وأخبر المعلّم."},{text:"أستخدم مطفأة الحريق بنفسي",correct:!1,feedback:"مطفأة الحريق للكبار المدرَّبين؛ أمّا الأطفال فيخرجون، ويُخبرون أحد الكبار، ويتصلون بالرقم 115."},{text:"أبقى في الصف وأتفرّج",correct:!1,feedback:"البقاء قرب النار ليس آمنًا؛ اخرج من الصف فورًا وأخبر المعلّم."}]},quiz:[{question:"ماذا يعني الحرف P في P.A.S.S؟",options:[{text:"Pull: اسحب المسمار",correct:!0,feedback:"الخطوة الأولى هي أن يسحب الشخص الكبير مسمار الأمان (Pull)."},{text:"Push: ادفع المقبض",correct:!1,feedback:"لا توجد خطوة Push: الحرف P يعني Pull، أي سحب مسمار الأمان."},{text:"Pour: اسكبها على النار",correct:!1,feedback:"لا توجد خطوة Pour: الحرف P يعني Pull، أي سحب مسمار الأمان."}],explanation:"الحرف P يعني Pull: اسحب مسمار الأمان. لكنّ الكبار المدرَّبين وحدهم يستخدمون مطفأة الحريق؛ أمّا الأطفال فيخرجون، ويُخبرون أحد الكبار، ويتصلون بالرقم 115."},{question:"بدأت نارٌ صغيرة في الصف. ما دور الأطفال؟",options:[{text:"أن يخرجوا، ويُخبروا أحد الكبار، ويتصلوا بالرقم 115",correct:!0,feedback:"الأطفال لا يُطفئون النار: دورهم أن يخرجوا، ويُخبروا أحد الكبار، ويتصلوا بالرقم 115."},{text:"أن يستخدموا أقرب مطفأة حريق بسرعة",correct:!1,feedback:"مطفأة الحريق للكبار المدرَّبين؛ أمّا الأطفال فيخرجون، ويُخبرون أحد الكبار، ويتصلون بالرقم 115."},{text:"أن يسكبوا الماء عليها",correct:!1,feedback:"الأطفال لا يُطفئون النار، حتى الصغيرة منها؛ اخرج، وأخبر أحد الكبار، واتصل بالرقم 115."}],explanation:"الأطفال لا يستخدمون مطفأة الحريق أبدًا، ولا يُطفئون النار. دور الأطفال أن يخرجوا، ويُخبروا أحد الكبار، ويتصلوا بالرقم 115."},{question:"لأيّ الحرائق تُستخدم مطفأة الحريق فقط؟",options:[{text:"للحرائق الصغيرة جدًا التي بدأت للتو",correct:!0,feedback:"مطفأة الحريق مخصّصة للحرائق الصغيرة جدًا التي في بدايتها فقط، ويستخدمها الكبار المدرَّبون."},{text:"للحرائق الكبيرة التي تنتشر إلى غرفٍ أخرى",correct:!1,feedback:"الحريق الكبير ليس للمطفأة؛ يخرج الجميع ويتصلون بالرقم 115."},{text:"لأيّ حريق، ما دام أحد الكبار يستخدمها",correct:!1,feedback:"لا يستخدم الكبار المطفأة إلا إذا كانت النار صغيرة جدًا وفي بدايتها؛ وإلّا يخرج الجميع."}],explanation:"مطفأة الحريق مخصّصة للحرائق الصغيرة جدًا التي في بدايتها فقط، ويستخدمها الكبار المدرَّبون. وإذا لم تكن النار صغيرة جدًا، يخرج الجميع ويتصلون بالرقم 115."},{question:"ترى مطفأة حريقٍ حمراء في الممر. لمن هي؟",options:[{text:"للأطفال الذين يريدون المساعدة في إطفاء النار",correct:!1,feedback:"لا. الأطفال لا يستخدمون مطفأة الحريق أبدًا. اخرج وأخبر أحد الكبار."},{text:"للكبار المدرَّبين، للحرائق الصغيرة جدًا",correct:!0,feedback:"صحيح. لا يستخدمها إلا الكبار المدرَّبون، وللنار الصغيرة جدًا فقط."},{text:"لأيّ شخصٍ يريد أن يلعب دور رجل الإطفاء",correct:!1,feedback:"لا. مطفأة الحريق أداة سلامة، وليست لعبةً أبدًا."}],explanation:"مطفأة الحريق أداةٌ للكبار المدرَّبين. الأطفال لا يستخدمونها أبدًا: اخرج، وأخبر أحد الكبار، واتصل بالرقم 115."},{question:"بدأت نارٌ صغيرة في سلّة المهملات، ومطفأة الحريق بجانبك. ماذا تفعل؟",options:[{text:"أسحب مسمار الأمان وأرشّ النار",correct:!1,feedback:"لا. هذا عمل الكبار المدرَّبين. اخرج وأخبر أحد الكبار."},{text:"أبقى وأراقب النار حتى يأتي أحد الكبار",correct:!1,feedback:"لا. النار الصغيرة قد تكبر بسرعة. اخرج الآن وأخبر أحد الكبار."},{text:"أخرج وأُخبر أحد الكبار",correct:!0,feedback:"صحيح. حتى لو كانت قريبة، فالأطفال لا يستخدمون مطفأة الحريق أبدًا."}],explanation:"الأطفال لا يستخدمون مطفأة الحريق أبدًا، حتى لو كانت قريبة. اخرج، وأخبر أحد الكبار، واتصل بالرقم 115."}],steps:[{title:"اعرف مكانها",detail:"تعلّم شكل مطفأة الحريق، ومكانها في المدرسة.",critical:!1},{title:"لا تلعب بها أبدًا",detail:"لا تلمس مطفأة الحريق، ولا تسحب مسمار الأمان أبدًا.",critical:!0},{title:"ترى نارًا؟ اخرج",detail:"اخرج فورًا، ولا تذهب إلى مطفأة الحريق.",critical:!0},{title:"أخبر أحد الكبار واتصل بالرقم 115",detail:"أخبر أحد الكبار بمكان النار. وإذا لم يكن أحدٌ من الكبار قريبًا، فاتصل بالرقم 115.",critical:!0}]},{id:11,icon:"CloudFog",accent:"#475569",title:"الدخان والتنفّس",subtitle:"تنفّس الهواء النقي",grades:"2-3",ages:"7-9",summary:"الدخان خطيرٌ جدًا. فهو يجعل التنفّس صعبًا، ويمنعك من أن ترى جيدًا.",blocks:[{heading:"الدخان يرتفع إلى الأعلى",body:"الهواء النقي يكون قريبًا من الأرض. فانخفض وازحف على يديك وركبتيك حتى تخرج.",image:"media/images/smoke_rises.png"},{heading:"منديلٌ مبلّل",body:"إذا كان معك منديلٌ مبلّل، فضعه على فمك وأنفك. ولكن لا تتوقّف للبحث عنه، بل اخرج فورًا.",image:"media/images/wet_cloth.png"},{heading:"افحص الباب",body:"قبل أن تفتح الباب، المسه بظهر يدك. فإذا كان ساخنًا، فلا تفتحه وابحث عن طريقٍ آخر. وبعد أن تخرج، أغلق الباب خلفك.",image:"media/images/check_door.png"}],examples:["انخفض.","ضع منديلًا مبلّلًا على فمك.","افحص الباب بظهر يدك.","ازحف على ركبتيك واخرج."],tips:["ركّبوا جهاز إنذار الدخان في المنزل.","اعرف طريق الخروج حتى في الظلام.","الهواء النقي يكون في الأسفل."],warnings:["في الحرائق، يقتل الدخانُ الناسَ أكثر ممّا تقتلهم النار نفسها! لا تستخدم المصعد."],realCase:"أثناء حريقٍ في أحد المنازل، انخفض طفلٌ عمره 10 سنوات وخرج من المنزل زاحفًا. وهذه المعرفة يمكن أن تنقذ حياتك أنت أيضًا!",video:"media/videos/lesson_smoke.mp4",game:{instruction:"ماذا نفعل عند وجود الدخان؟",items:[{text:"انخفض",emoji:"🐢",correct:!0},{text:"امشِ واقفًا على قدميك",emoji:"🧍",correct:!1},{text:"منديلٌ مبلّل",emoji:"🧣",correct:!0},{text:"افتح النافذة",emoji:"🪟",correct:!1}]},activity:{prompt:"امتلأت الغرفة بالدخان ولا تستطيع أن ترى جيدًا. ماذا ستفعل؟",image:"media/images/activity_smoke.png",options:[{text:"أنخفض، وأضع منديلًا على فمي، وأخرج زاحفًا",correct:!0,feedback:"الهواء في الأسفل أنقى، والزحف يُخرجك من الدخان."},{text:"أمشي بسرعة واقفًا على قدميّ",correct:!1,feedback:"عندما تقف يكون رأسك داخل الدخان؛ انخفض واخرج زاحفًا."},{text:"أفتح النافذة وأبقى هناك",correct:!1,feedback:"البقاء في غرفة مليئة بالدخان خطر؛ انخفض واخرج من الغرفة زاحفًا."},{text:"أبقى في الغرفة",correct:!1,feedback:"الدخان يجعل التنفّس صعبًا، فلا تبقَ؛ انخفض واخرج زاحفًا."}]},quiz:[{question:"لماذا ننخفض عند وجود الدخان؟",options:[{text:"لأن الدخان يرتفع، والهواء النقي في الأسفل",correct:!0,feedback:"الدخان يرتفع والهواء النقي يبقى في الأسفل، لذلك يحميك الانخفاض."},{text:"لأن ذلك ممتع",correct:!1,feedback:"الانخفاض ليس لعبة: فهو يُبقيك في الهواء النقي تحت الدخان."},{text:"لكي نرى الباب وطريق الخروج بشكلٍ أفضل",correct:!1,feedback:"ننخفض لكي نتنفّس: فالدخان يرتفع، والهواء النقي يكون قريبًا من الأرض."}],explanation:"الدخان يرتفع إلى الأعلى، لذلك يكون الهواء النقي قريبًا من الأرض. انخفض وازحف على يديك وركبتيك حتى تخرج."},{question:"كيف تفحص الباب قبل أن تفتحه؟",options:[{text:"ألمسه بظهر يدي",correct:!0,feedback:"لمس الباب بظهر يدك يُريك هل هو ساخن؛ فإذا كان ساخنًا فلا تفتحه."},{text:"أفتحه قليلًا وأنظر إلى الخارج أولًا",correct:!1,feedback:"لا تفتحه أولًا: المسه بظهر يدك، وإذا كان ساخنًا فابحث عن طريقٍ آخر."},{text:"أفتحه بسرعة وأنظر",correct:!1,feedback:"قبل أن تفتح الباب، المسه بظهر يدك؛ فإذا كان ساخنًا فلا تفتحه."}],explanation:"قبل أن تفتح الباب، المسه بظهر يدك. فإذا كان ساخنًا، فلا تفتحه وابحث عن طريقٍ آخر."},{question:"هناك دخان، وليس معك منديلٌ مبلّل. ماذا تفعل؟",options:[{text:"أنخفض وأخرج فورًا",correct:!0,feedback:"لا تتوقّف للبحث عن منديل؛ انخفض واخرج فورًا."},{text:"أبحث عن منديلٍ أولًا",correct:!1,feedback:"المنديل المبلّل يساعد فقط إذا كان معك؛ لا تتوقّف للبحث عنه، بل اخرج فورًا."},{text:"أنتظر حتى أجد ماءً",correct:!1,feedback:"لا تنتظر في الدخان: فالدخان يقتل الناس أكثر ممّا تقتلهم النار نفسها. انخفض واخرج فورًا."}],explanation:"إذا كان معك منديلٌ مبلّل، فضعه على فمك وأنفك. ولكن لا تتوقّف للبحث عنه؛ انخفض واخرج فورًا."},{question:"لمست بابًا بظهر يدك فوجدته ساخنًا. ماذا تفعل؟",options:[{text:"أفتحه بسرعة وأركض عبره",correct:!1,feedback:"لا. النار والدخان قد يندفعان نحوك. لا تفتح الباب الساخن."},{text:"لا أفتحه وأستخدم طريقًا آخر",correct:!0,feedback:"صحيح. الباب الساخن يعني أن النار قد تكون خلفه."},{text:"أفتحه قليلًا لأنظر",correct:!1,feedback:"لا. حتى الفتحة الصغيرة تُدخل الدخان والنار. أبقِه مُغلقًا."}],explanation:"إذا كان الباب ساخنًا، فقد تكون النار خلفه. لا تفتحه، وابحث عن طريقٍ آخر للخروج."},{question:"هناك دخانٌ في المبنى وأنت في الطابق العلوي. كيف تنزل؟",options:[{text:"بالمصعد، لأنه أسرع",correct:!1,feedback:"لا. لا تستخدم المصعد في الحريق أبدًا، فقد يتوقّف أو يمتلئ بالدخان."},{text:"أنتظر في غرفتي حتى يذهب الدخان",correct:!1,feedback:"لا. الدخان قد يقتل. انخفض واخرج عبر السلالم فورًا."},{text:"عبر السلالم، وأنا منخفض",correct:!0,feedback:"صحيح. السلالم هي طريق الخروج في الحريق. ابقَ منخفضًا تحت الدخان."}],explanation:"في الحريق، استخدم السلالم ولا تستخدم المصعد أبدًا. ابقَ منخفضًا تحت الدخان واخرج."}],steps:[{title:"انخفض",detail:"انخفض وازحف على يديك وركبتيك تحت الدخان.",critical:!0},{title:"افحص الباب",detail:"المس الباب بظهر يدك. إذا كان ساخنًا فلا تفتحه، واستخدم طريقًا آخر.",critical:!0},{title:"اخرج وأغلق الباب",detail:"اخرج وأغلق الباب خلفك. استخدم السلالم، ولا تستخدم المصعد أبدًا.",critical:!0},{title:"أخبر أحد الكبار واتصل بالرقم 115",detail:"في الخارج، أخبر أحد الكبار. وإذا لم يكن أحدٌ من الكبار قريبًا، فاتصل بالرقم 115.",critical:!0}]},{id:12,icon:"FlaskConical",accent:"#9333ea",title:"المواد الكيميائية",subtitle:"خطر المواد المجهولة",grades:"4-5",ages:"9-11",summary:"توجد في المنازل موادّ كيميائية، مثل موادّ التنظيف والبنزين. وهذه الموادّ خطيرة إذا استُخدمت بطريقةٍ خاطئة.",blocks:[{heading:"لا تشربها ولا تلمسها",body:"لا تشرب سائلًا مجهولًا ولا تشمّه، فقد يكون سامًّا.",image:"media/images/chem_no_drink.png"},{heading:"رموز الخطر",body:"تعرّف على رموز الخطر الموجودة على الزجاجات والعلب. إذا وجدت رمزًا منها على شيء، فلا تلمسه وأخبر أحد الكبار.",image:"media/images/chem_signs.png"},{heading:"إذا دخلت في العينين",body:"أخبر أحد الكبار فورًا. اغسلوا العينين بماءٍ نظيف جارٍ لمدة 15 دقيقة على الأقل، واتصلوا بالرقم 122 (الإسعاف).",image:"media/images/chem_eye.png"}],examples:["لا تشرب سائلًا مجهولًا.","تعرّف على رموز الخطر.","إذا دخلت في العينين: اغسلهما بالماء.","التسمّم: اتصل بالرقم 122."],tips:["يجب على الكبار أن يضعوا الموادّ الخطيرة في مكانٍ مرتفع ومُغلق.","تعرّف على الرموز.","أخبر الكبار."],warnings:["لا تخلط موادّ التنظيف بعضها ببعض أبدًا! فقد يتكوّن غازٌ سام."],realCase:"رأت طفلةٌ زجاجةً ملوّنة في المطبخ، فلم تشرب منها، بل سألت أمّها، فعرفت أنها مادة تنظيفٍ خطيرة.",video:"media/videos/lesson_chemical.mp4",game:{instruction:"أيّ هذه الأشياء خطِرة؟",items:[{text:"موادّ التنظيف",emoji:"🧴",correct:!0},{text:"الماء",emoji:"💧",correct:!1},{text:"البنزين",emoji:"⛽",correct:!0},{text:"الحليب",emoji:"🥛",correct:!1}]},activity:{prompt:"وجدت في الحمّام زجاجةً فيها سائلٌ مجهول. ماذا ستفعل؟",image:"media/images/activity_chem.png",options:[{text:"لا ألمسها، وأخبر أحد الكبار",correct:!0,feedback:"السائل المجهول قد يكون سامًّا، لذلك تبقى آمنًا إذا لم تلمسه وأخبرت أحد الكبار."},{text:"أشمّها",correct:!1,feedback:"حتى شمّ السائل المجهول خطر، لأنه قد يكون سامًّا؛ أخبر أحد الكبار."},{text:"أسكب منها على يديّ",correct:!1,feedback:"السائل المجهول قد يكون سامًّا، فلا تلمسه؛ أخبر أحد الكبار."},{text:"أشرب منها",correct:!1,feedback:"السائل المجهول قد يكون سامًّا، فلا تشرب منه أبدًا؛ أخبر أحد الكبار فورًا."}]},quiz:[{question:"إذا دخلت مادةٌ كيميائية في عينيك، فماذا تفعل؟",options:[{text:"أغسلهما بماءٍ نظيف لمدة 15 دقيقة على الأقل، وأخبر أحد الكبار",correct:!0,feedback:"الغسل بالماء النظيف لمدة 15 دقيقة على الأقل يُزيل المادة من العينين، ويستطيع الشخص الكبير الاتصال بالرقم 122."},{text:"أفرك عينيّ بيديّ ثم أُغمضهما جيدًا وأنتظر حتى يزول الألم",correct:!1,feedback:"لا! فهذا يزيد الضرر."},{text:"لا أفعل شيئًا",correct:!1,feedback:"المادة الكيميائية في العين تحتاج إلى مساعدةٍ فورية: اغسلها بماءٍ نظيف وأخبر أحد الكبار."}],explanation:"اغسل عينيك بماءٍ نظيف جارٍ لمدة 15 دقيقة على الأقل، وأخبر أحد الكبار فورًا ليتصل بالرقم 122 (الإسعاف)."},{question:"لماذا لا نخلط موادّ التنظيف بعضها ببعض أبدًا؟",options:[{text:"لأنه قد يتكوّن غازٌ سام",correct:!0,feedback:"خلط موادّ التنظيف قد يكوّن غازًا سامًّا، لذلك لا تخلطها أبدًا."},{text:"لأنها لا تعود تنظّف جيدًا",correct:!1,feedback:"الخطر ليس ضعف التنظيف: خلط موادّ التنظيف قد يكوّن غازًا سامًّا."},{text:"لأنها قد تفقد رائحتها الطيبة",correct:!1,feedback:"الخطر ليس الرائحة: خلط موادّ التنظيف قد يكوّن غازًا سامًّا."}],explanation:"لا تخلط موادّ التنظيف بعضها ببعض أبدًا! فقد يتكوّن غازٌ سام."},{question:"على زجاجةٍ رمزُ خطر. ماذا تفعل؟",options:[{text:"لا ألمسها، وأُخبر أحد الكبار",correct:!0,feedback:"رمز الخطر يعني أن المادة خطيرة، لذلك لا تلمسها وأخبر أحد الكبار."},{text:"أفتحها بحذر لأرى ما فيها",correct:!1,feedback:"لا تفتحها؛ إذا وجدت رمز خطر على شيء، فلا تلمسه وأخبر أحد الكبار."},{text:"أشمّها لأعرف ما فيها",correct:!1,feedback:"لا تشرب سائلًا مجهولًا ولا تشمّه، فقد يكون سامًّا. اتركها وأخبر أحد الكبار."}],explanation:"إذا وجدت رمز خطر على شيء، فلا تلمسه وأخبر أحد الكبار. ولا تشرب سائلًا مجهولًا ولا تشمّه، فقد يكون سامًّا."},{question:"وجدت سائلًا صافيًا في قنينة ماءٍ في المخزن، وأنت عطشان. ماذا تفعل؟",options:[{text:"أشرب قليلًا لأتأكّد",correct:!1,feedback:"لا. حتى القليل من السمّ قد يُمرضك كثيرًا. لا تشرب سائلًا مجهولًا أبدًا."},{text:"أشمّه لأعرف إن كان ماءً",correct:!1,feedback:"لا. الشمّ قد يؤذيك أيضًا. اتركه وأخبر أحد الكبار."},{text:"لا أشربه وأُخبر أحد الكبار",correct:!0,feedback:"صحيح. قد تحتوي قنينة الماء على شيءٍ خطير."}],explanation:"لا تشرب سائلًا مجهولًا ولا تشمّه أبدًا، حتى لو كان في قنينة ماء، فقد يكون سامًّا. أخبر أحد الكبار."},{question:"شرب صديقك شيئًا من قنينة موادّ تنظيف. ماذا تفعل؟",options:[{text:"أُخبر أحد الكبار فورًا",correct:!0,feedback:"صحيح. يتصل الكبير بالرقم 122، ويحتفظ بالقنينة ليُريها للأطباء."},{text:"أجعله يتقيّأ ليُخرجه",correct:!1,feedback:"لا. لا تجعل الشخص يتقيّأ أبدًا، فقد يزيد ذلك الضرر. أخبر أحد الكبار."},{text:"أعطيه حليبًا ليشربه",correct:!1,feedback:"لا. لا تعطِه حليبًا ولا أيّ طعامٍ أو شراب. أخبر أحد الكبار."}],explanation:"لا تجعله يتقيّأ، ولا تعطِه أيّ طعامٍ أو شراب. أخبر أحد الكبار فورًا، وهو يتصل بالرقم 122."}],steps:[{title:"لا تلمس",detail:"لا تلمس السائل المجهول، ولا تشربه، ولا تشمّه.",critical:!0},{title:"ابتعد",detail:"ارجع إلى الخلف، وأبعِد أصدقاءك.",critical:!1},{title:"أخبر أحد الكبار",detail:"أخبر أحد الكبار فورًا.",critical:!0},{title:"إذا دخلت عينيك",detail:"اغسل عينيك بماءٍ نظيف جارٍ مدة 15 دقيقة على الأقل، ويتصل أحد الكبار بالرقم 122.",critical:!0}]},{id:13,icon:"AlertTriangle",accent:"#db2777",title:"إشارات السلامة",subtitle:"التعرّف على الإشارات والعلامات",grades:"1-2",ages:"6-8",summary:"إشارات السلامة تخبرنا من دون كلام: هنا يوجد خطر، أو هذا الفعل ممنوع، أو هذا هو طريق الخروج.",blocks:[{heading:"المثلث الأصفر = خطر",body:"المثلث الأصفر الذي فيه صورةٌ سوداء معناه: انتبه، يوجد خطر!",image:"media/images/warning_sign.png"},{heading:"الدائرة الحمراء = ممنوع",body:"الدائرة الحمراء التي يقطعها خطٌّ أحمر معناها: لا تفعل هذا!",image:"media/images/prohibit_sign.png"},{heading:"الأخضر = السلامة",body:"المربّع الأخضر معناه السلامة، مثل طريق مخرج الطوارئ أو مكان الإسعافات الأولية.",image:"media/images/exit_sign.png"}],examples:["المثلث الأصفر = خطر.","الدائرة الحمراء = ممنوع.","المربّع الأخضر = سلامة.","الدائرة الزرقاء = إلزامي (يجب أن تفعله)."],tips:["تعلّم ألوان الإشارات.","ابحث عن الإشارات في المدرسة.","تعرّف على إشارة مخرج الطوارئ."],warnings:["اقرأ الإشارات والتزم بها!"],realCase:"رأت طفلةٌ إشارة خطر الكهرباء على أحد الأبواب، فابتعدت عنه. فقال لها المعلّم: أحسنتِ!",video:"media/videos/lesson_signs.mp4",game:{instruction:"ماذا يعني المثلث الأصفر؟",items:[{text:"خطر!",emoji:"⚠️",correct:!0},{text:"امشِ!",emoji:"🟢",correct:!1},{text:"ممنوع",emoji:"🚫",correct:!1},{text:"انتبه",emoji:"👀",correct:!0}]},activity:{prompt:"ترى إشارةً خضراء فيها سهمٌ أبيض. ماذا تعني؟",image:"media/images/activity_signs.png",options:[{text:"طريق الخروج الآمن",correct:!0,feedback:"الأخضر معناه السلامة، والسهم يدلّ على طريق مخرج الطوارئ."},{text:"ممنوع",correct:!1,feedback:"«ممنوع» تدلّ عليه الدائرة الحمراء التي يقطعها خط؛ أمّا الأخضر فمعناه السلامة، مثل طريق الخروج."},{text:"خطر",correct:!1,feedback:"الخطر هو المثلث الأصفر؛ أمّا الإشارة الخضراء فمعناها السلامة، مثل طريق الخروج."},{text:"قف",correct:!1,feedback:"الإشارة الخضراء لا تعني «قف»؛ فالأخضر سلامة، والسهم يدلّ على طريق الخروج."}]},quiz:[{question:"ماذا تعني الدائرة الحمراء التي يقطعها خط؟",options:[{text:"ممنوع / لا تفعل",correct:!0,feedback:"الدائرة الحمراء التي يقطعها خط تقول لك: لا تفعل هذا."},{text:"امشِ، هذا الطريق آمن",correct:!1,feedback:"الدائرة الحمراء التي يقطعها خط معناها «لا تفعل»، ولا تعني «امشِ» أبدًا."},{text:"خطر: انتبه هنا",correct:!1,feedback:"الخطر يُعرف بالمثلث الأصفر؛ أمّا الدائرة الحمراء التي يقطعها خط فمعناها «لا تفعل»."}],explanation:"الدائرة الحمراء التي يقطعها خطٌّ أحمر معناها: لا تفعل هذا! أمّا المثلث الأصفر فمعناه خطر، والأخضر معناه السلامة."},{question:"ماذا يعني المثلث الأصفر الذي فيه صورةٌ سوداء؟",options:[{text:"خطر: انتبه",correct:!0,feedback:"المثلث الأصفر يحذّرك: انتبه، يوجد خطر!"},{text:"سلامة: طريق الخروج",correct:!1,feedback:"طريق الخروج يُعرف باللون الأخضر؛ أمّا المثلث الأصفر فمعناه: انتبه، يوجد خطر."},{text:"ممنوع: لا تفعل هذا",correct:!1,feedback:"«ممنوع» تدلّ عليه الدائرة الحمراء التي يقطعها خط؛ أمّا المثلث الأصفر فمعناه: انتبه، يوجد خطر."}],explanation:"المثلث الأصفر الذي فيه صورةٌ سوداء معناه: انتبه، يوجد خطر! أمّا الدائرة الحمراء التي يقطعها خط فمعناها ممنوع، والأخضر معناه السلامة."},{question:"ماذا تعني الدائرة الزرقاء؟",options:[{text:"إلزامي: يجب أن تفعله",correct:!0,feedback:"الدائرة الزرقاء تعطي أمرًا إلزاميًا: تخبرك بشيءٍ يجب أن تفعله."},{text:"سلامة: هذا طريق الخروج",correct:!1,feedback:"طريق الخروج إشارةٌ خضراء؛ أمّا الدائرة الزرقاء فهي أمرٌ إلزامي يجب أن تفعله."},{text:"ممنوع: لا يجوز أن تفعله",correct:!1,feedback:"«ممنوع» هي الدائرة الحمراء التي يقطعها خط؛ أمّا الدائرة الزرقاء فهي أمرٌ إلزامي يجب أن تفعله."}],explanation:"الدائرة الزرقاء معناها إلزامي: يجب أن تفعله. أمّا الدائرة الحمراء التي يقطعها خط فمعناها ممنوع، والمثلث الأصفر خطر، والأخضر سلامة."},{question:"هناك حريق في المدرسة. أيّ الإشارات تتبع لتخرج؟",options:[{text:"إشارات الدائرة الحمراء",correct:!1,feedback:"لا. الدائرة الحمراء تعني «ممنوع»، ولا تدلّ على طريق الخروج."},{text:"إشارات الخروج الخضراء",correct:!0,feedback:"صحيح. الإشارات الخضراء تدلّ على السلامة وطريق الخروج."},{text:"إشارات المثلث الأصفر",correct:!1,feedback:"لا. المثلث الأصفر يحذّر من الخطر. اتبع الإشارات الخضراء."}],explanation:"الإشارات الخضراء تدلّ على السلامة، مثل طريق مخرج الطوارئ. اتبعها لتخرج."},{question:"على أحد الأبواب إشارة مثلثٍ أصفر. ماذا تفعل؟",options:[{text:"أفتح الباب لأرى الخطر",correct:!1,feedback:"لا. لا تذهب لترى الخطر. ابقَ بعيدًا واسأل أحد الكبار."},{text:"أدخل بسرعة ثم أخرج",correct:!1,feedback:"لا. حتى الدخول السريع قد يكون خطيرًا. اقرأ الإشارة وابقَ بعيدًا."},{text:"أبقى بعيدًا وأسأل أحد الكبار",correct:!0,feedback:"صحيح. المثلث الأصفر يعني الخطر. كن حذرًا وابقَ بعيدًا."}],explanation:"المثلث الأصفر الذي فيه صورةٌ سوداء يعني الخطر. ابقَ بعيدًا، واسأل أحد الكبار إذا لم تكن متأكّدًا."}],steps:[{title:"انظر إلى اللون والشكل",detail:"انظر إلى شكل الإشارة ولونها.",critical:!1},{title:"انظر إلى الصورة",detail:"الصورة التي في داخلها تُبيّن الخطر أو القاعدة.",critical:!1},{title:"افعل ما تقوله",detail:"التزم بالإشارة. وإذا لم تفهمها، فاسأل أحد الكبار.",critical:!1}]},{id:14,icon:"School",accent:"#0d9488",title:"تدريب الطوارئ في المدرسة",subtitle:"الاستعداد للحوادث",grades:"3-4",ages:"8-10",summary:"تدريب الطوارئ يُعِدّنا لحوادث مثل الحريق والزلزال، لكي نعرف ماذا نفعل عندما تحدث فعلًا.",blocks:[{heading:"استمع إلى المعلّم",body:"استمع دائمًا إلى تعليمات المعلّم.",image:"media/images/listen_teacher.png"},{heading:"اخرج بنظام",body:"لا تدفع أحدًا. اخرج بنظامٍ وبالدور، وساعد من هم أصغر منك.",image:"media/images/orderly_exit.png"},{heading:"نقطة التجمع",body:"ابقَ في نقطة التجمع، وانتظر حتى يقرأ المعلّم اسمك.",image:"media/images/assembly_wait.png"}],examples:["استمع إلى المعلّم.","اخرج بنظام.","ساعد زملاءك.","ابقَ في نقطة التجمع."],tips:["تعامل مع التدريب كأنه حالة طوارئ حقيقية.","تعلّم طرق الخروج.","تحدّث مع زملائك عن خطة الإخلاء."],warnings:["لا تنظر إلى التدريب على أنه لعبة! فهو لحماية حياتك."],realCase:"في أحد الأيام، اندلع حريقٌ في إحدى المدارس. فخرج التلاميذ بهدوء وأمان، لأنهم كانوا قد تدرّبوا من قبل!",video:"media/videos/lesson_drill.mp4",game:{instruction:"ماذا نفعل أثناء التدريب؟",items:[{text:"نستمع إلى المعلّم",emoji:"👂",correct:!0},{text:"نلعب",emoji:"🎮",correct:!1},{text:"نخرج بنظام",emoji:"🚶",correct:!0},{text:"نجمع أغراضنا",emoji:"🎒",correct:!1}]},activity:{prompt:"رنّ جرس الإنذار في أثناء الدرس. ماذا ستفعل؟",image:"media/images/activity_drill.png",options:[{text:"أترك كل شيء وأخرج بنظام",correct:!0,feedback:"بالخروج بنظام ومن دون دفع، يخرج الجميع بأمان."},{text:"أجمع أغراضي",correct:!1,feedback:"أغراضك يمكن أن تنتظر؛ اترك كل شيء واخرج بنظام."},{text:"أبقى في الصف",correct:!1,feedback:"تعامل مع كل جرس إنذار كأنه حالة طوارئ حقيقية؛ اخرج وانتظر في نقطة التجمع."},{text:"أبقى لأرى ماذا سيحدث",correct:!1,feedback:"الجرس يقول: اخرج الآن! فلا تنتظر، واذهب إلى نقطة التجمع."}]},quiz:[{question:"عندما يرنّ جرس الإنذار، ما أول شيء نفعله؟",options:[{text:"اترك كل شيء واخرج",correct:!0,feedback:"بترك كل شيء تخرج بسرعة وبأمان."},{text:"اجمع حقيبتك وكتبك أولًا",correct:!1,feedback:"جمع الأغراض يؤخّرك؛ اترك كل شيء واخرج."},{text:"ابقَ في الصف",correct:!1,feedback:"عندما يرنّ الجرس، يذهب الجميع إلى نقطة التجمع، كي لا يبقى أحدٌ في الداخل."}],explanation:"عندما يرنّ جرس الإنذار، اترك كل شيء واخرج بنظامٍ وبالدور. ثم انتظر في نقطة التجمع حتى يقرأ المعلّم اسمك."},{question:"أنت في نقطة التجمع. ماذا تفعل؟",options:[{text:"أبقى فيها حتى يقرأ المعلّم اسمي",correct:!0,feedback:"البقاء في نقطة التجمع حتى يقرأ المعلّم اسمك يجعل المعلّم يعرف أن الجميع خرجوا."},{text:"أعود إلى الصف لآخذ حقيبتي",correct:!1,feedback:"لا تعد إلى الصف؛ ابقَ في نقطة التجمع حتى يقرأ المعلّم اسمك."},{text:"أذهب إلى البيت لأُخبر عائلتي",correct:!1,feedback:"إذا ذهبت فلن يجدك المعلّم؛ ابقَ في نقطة التجمع حتى يقرأ اسمك."}],explanation:"ابقَ في نقطة التجمع، وانتظر حتى يقرأ المعلّم اسمك."},{question:"كيف نخرج من المبنى أثناء التدريب؟",options:[{text:"بنظامٍ وبالدور، من دون دفع",correct:!0,feedback:"بالخروج بنظامٍ وبالدور ومن دون دفع، يخرج الجميع بأمان."},{text:"بأقصى سرعة، ونحن ندفع الآخرين",correct:!1,feedback:"لا تدفع أحدًا؛ اخرج بنظامٍ وبالدور."},{text:"معًا، ونحن نركض نحو الباب",correct:!1,feedback:"الركض معًا ليس خروجًا بنظام؛ اخرج بالدور وساعد من هم أصغر منك."}],explanation:"لا تدفع أحدًا. اخرج بنظامٍ وبالدور، وساعد من هم أصغر منك."},{question:"رنّ الجرس وأنت في دورة المياه، بعيدًا عن صفّك. ماذا تفعل؟",options:[{text:"أعود إلى صفّي لأجد زملائي",correct:!1,feedback:"لا. قد يكون صفّك قد خرج. اخرج واذهب إلى نقطة التجمع."},{text:"أخرج وأجد صفّي عند نقطة التجمع",correct:!0,feedback:"صحيح. سيرى المعلّم أنك بأمان."},{text:"أبقى في دورة المياه حتى ينتهي التدريب",correct:!1,feedback:"لا. لن يعرف أحدٌ أين أنت. اخرج وانضمّ إلى صفّك."}],explanation:"اخرج من أقرب طريقٍ آمن، وانضمّ إلى صفّك عند نقطة التجمع، ليعرف المعلّم أنك بأمان."},{question:"يضحك صديقك ويقول إن التدريب ليس حقيقيًا. ماذا تفعل؟",options:[{text:"آخذه بجدّية وأفعل ما يقوله المعلّم",correct:!0,feedback:"صحيح. التدريب يعلّمك ماذا تفعل في حالة طوارئ حقيقية."},{text:"أضحك أنا أيضًا وأخرج ببطء",correct:!1,feedback:"لا. تعامل مع التدريب كأنه طوارئ حقيقية. استمع واخرج بنظام."},{text:"أبقى في الصف لأن التدريب ليس حقيقيًا",correct:!1,feedback:"لا. الجميع يشاركون في التدريب. اخرج مع صفّك."}],explanation:"التدريب استعدادٌ لحالة طوارئ حقيقية. خذه بجدّية لتعرف ماذا تفعل."}],media:[{kind:"image",src:"media/images/primary3d_school_fire_alarm.webp",title:"استمع إلى المعلّم",description:"استمع دائمًا إلى تعليمات المعلّم."},{kind:"image",src:"media/images/primary3d_stairwell_evacuation.webp",title:"اخرج بنظام",description:"لا تدفع أحدًا. اخرج بنظامٍ وبالدور، وساعد من هم أصغر منك."}],steps:[{title:"توقّف واستمع",detail:"عندما يرنّ الجرس، توقّف واستمع إلى المعلّم.",critical:!0},{title:"اترك أغراضك",detail:"اترك حقيبتك وكتبك في مكانها.",critical:!1},{title:"اخرج بنظام",detail:"اخرج بالدور ومن دون دفع، واستخدم السلالم.",critical:!0},{title:"انتظر عند نقطة التجمع",detail:"ابقَ مع صفّك حتى ينادي المعلّم اسمك.",critical:!1}]},{id:15,icon:"Award",accent:"#4f46e5",title:"بطل السلامة",subtitle:"المسؤولية والمساعدة",grades:"5-6",ages:"10-12",summary:"بطل السلامة شخصٌ مسؤول، يساعد الناس، ويتصرّف تصرّفًا صحيحًا. والبطل الحقيقي لا يعرّض نفسه للخطر، بل يُخبر الكبار.",blocks:[{heading:"المسؤولية",body:"ينتبه إلى سلامته وسلامة أصدقائه، ويكون يقظًا دائمًا.",image:"media/images/responsibility.png"},{heading:"المساعدة",body:"يساعد من هم أصغر منه، والأشخاص الذين يحتاجون إلى المساعدة.",image:"media/images/help_others.png"},{heading:"تعليم الآخرين",body:"علِّم أصدقاءك ما تتعلّمه. وبهذه الطريقة تزداد المعرفة!",image:"media/images/teach_friends.png"}],examples:["كن مسؤولًا.","ساعد الآخرين.","علِّم أصدقاءك.","كن قدوةً حسنة."],tips:["تعلّم أشياء جديدة.","إذا رأيت خطرًا، فأخبر المعلّم.","كن قدوةً حسنة لأصدقائك."],warnings:["البطل لا يعرّض نفسه للخطر! البطولة هي أن تساعد بذكاء، وأن تُخبر الكبار."],realCase:"علّمت تلميذةٌ في الصف السادس زملاءها الرقمَ 115 وخطةَ الإخلاء. وبعد ذلك، عندما اندلع حريقٌ في المدرسة، خرج جميع زملائها بأمان!",video:"media/videos/lesson_hero.mp4",game:{instruction:"كيف يكون بطل السلامة؟",items:[{text:"مسؤول",emoji:"💪",correct:!0},{text:"يلعب في أثناء الطوارئ",emoji:"🎮",correct:!1},{text:"يساعد الآخرين",emoji:"🤝",correct:!0},{text:"يختبئ",emoji:"🙈",correct:!1}]},activity:{prompt:"أثناء التدريب، يشعر طفلٌ من الصف الأول بالخوف. ماذا ستفعل؟",image:"media/images/activity_hero.png",options:[{text:"أمسك يده، وأريه الطريق بهدوء",correct:!0,feedback:"مساعدة طفلٍ أصغر بهدوء هي ما يفعله بطل السلامة."},{text:"أتركه وأركض",correct:!1,feedback:"الطفل الصغير يحتاج إلى المساعدة ليخرج؛ كن هادئًا وأرِه الطريق."},{text:"أضحك عليه",correct:!1,feedback:"الطفل الخائف يحتاج إلى اللطف؛ أمسك يده وأرِه الطريق بهدوء."},{text:"لا أفعل شيئًا",correct:!1,feedback:"بطل السلامة يساعد من هم أصغر منه؛ أمسك يده وأرِه الطريق بهدوء."}]},quiz:[{question:"ماذا يفعل بطل السلامة؟",options:[{text:"يساعد الآخرين، ويعلّم أصدقاءه، ويكون مسؤولًا",correct:!0,feedback:"المساعدة والتعليم والمسؤولية تُبقيك أنت وأصدقاءك في أمان."},{text:"يهتمّ بنفسه فقط، وينسى أصدقاءه ومن هم أصغر منه",correct:!1,feedback:"بطل السلامة ينتبه أيضًا إلى سلامة أصدقائه، ويساعد من هم أصغر منه."},{text:"لا يفعل شيئًا وينتظر أن يساعد الآخرون",correct:!1,feedback:"بطل السلامة يقظٌ دائمًا: إذا رأى خطرًا أخبر المعلّم."}],explanation:"بطل السلامة مسؤول، يساعد الآخرين ويعلّم أصدقاءه. والبطل الحقيقي لا يعرّض نفسه للخطر، بل يُخبر الكبار."},{question:"يرى بطل السلامة خطرًا في المدرسة. ماذا يفعل؟",options:[{text:"يُخبر المعلّم فورًا",correct:!0,feedback:"إخبار المعلّم بالخطر يحمي الجميع؛ وهذا ما يفعله بطل السلامة."},{text:"يقترب منه لينظر إليه",correct:!1,feedback:"الاقتراب قد يعرّضك للخطر؛ بطل السلامة يُخبر المعلّم."},{text:"يحاول إصلاحه وحده",correct:!1,feedback:"البطل لا يعرّض نفسه للخطر؛ أخبر المعلّم بدلًا من ذلك."}],explanation:"إذا رأيت خطرًا، فأخبر المعلّم. والبطل الحقيقي لا يعرّض نفسه للخطر، بل يُخبر الكبار."},{question:"هل البطل الحقيقي هو من يعرّض نفسه للخطر ليساعد؟",options:[{text:"لا، البطل يساعد بذكاء ويُخبر الكبار",correct:!0,feedback:"البطولة هي أن تساعد بذكاء وأن تُخبر الكبار، والبطل لا يعرّض نفسه للخطر."},{text:"نعم، البطل يعرّض نفسه للخطر لينقذ الآخرين",correct:!1,feedback:"البطل لا يعرّض نفسه للخطر! ساعد بذكاء وأخبر الكبار."},{text:"نعم، إذا احتاج صديقٌ إلى المساعدة",correct:!1,feedback:"حتى إذا احتاج صديقٌ إلى المساعدة، فالبطل لا يعرّض نفسه للخطر؛ أخبر الكبار فورًا."}],explanation:"البطل لا يعرّض نفسه للخطر! البطولة هي أن تساعد بذكاء، وأن تُخبر الكبار."},{question:"طفلٌ أصغر يلعب قرب سلكٍ مقطوع. ماذا يفعل بطل السلامة؟",options:[{text:"يُبعد السلك عن الطفل بعصا طويلة",correct:!1,feedback:"لا. لا تلمس السلك المقطوع أبدًا، ولا حتى بعصا."},{text:"ينادي الطفل من بعيد ويُخبر أحد الكبار",correct:!0,feedback:"صحيح. البطل يساعد بذكاء، من دون أن يقترب من الخطر."},{text:"يركض إلى الطفل ويسحبه بعيدًا عن السلك",correct:!1,feedback:"لا. لا تقترب أنت من السلك. نادِ الطفل من بعيد."}],explanation:"البطل يساعد بذكاء: نادِ الطفل من دون أن تقترب من الخطر، وأخبر أحد الكبار."},{question:"تعلّمت في المدرسة أن تنخفض تحت الدخان. ماذا يستطيع بطل السلامة أن يفعل في البيت؟",options:[{text:"أحتفظ به لنفسي لأنه للمدرسة",correct:!1,feedback:"لا. قواعد السلامة للجميع. شاركها مع عائلتك."},{text:"أنتظر حتى يُخبر المعلّم عائلتي",correct:!1,feedback:"لا. تستطيع أن تشاركه بنفسك. بطل السلامة يعلّم الآخرين."},{text:"أُعلّم عائلتي ما تعلّمته",correct:!0,feedback:"صحيح. عندما تشارك ما تتعلّمه، تزداد المعرفة."}],explanation:"تعليم الآخرين جزءٌ من أن تكون بطل سلامة. شارك ما تتعلّمه مع أصدقائك وعائلتك."}],steps:[{title:"ابقَ آمنًا",detail:"لا تقترب من الخطر.",critical:!0},{title:"أخبر أحد الكبار",detail:"أخبر المعلّم أو أحد الكبار فورًا.",critical:!0},{title:"ساعد الأصغر منك",detail:"نادِ الأطفال الأصغر ليبتعدوا عن الخطر، وابقَ هادئًا.",critical:!1},{title:"شارك ما تتعلّمه",detail:"علّم أصدقاءك وعائلتك قواعد السلامة.",critical:!1}]},{id:16,icon:"FlameKindling",accent:"#ea580c",title:"أنواع الحرائق",subtitle:"نظام NFPA: الفئات A وB وC وD وK",grades:"4-6",ages:"9-12",summary:"ليست كل الحرائق متشابهة! وفقًا لنظام NFPA، هناك خمس فئات للحرائق: A (المواد الصلبة)، وB (السوائل والغازات القابلة للاشتعال)، وC (الأجهزة الكهربائية)، وD (المعادن)، وK (زيت الطبخ). وكل فئة تُطفأ بطريقةٍ خاصة. وإذا وقع الماء على الزيت الساخن المشتعل، فإن النار ترتفع بقوة وتنتشر!",blocks:[{heading:"الفئة A: المواد الصلبة",body:"الخشب، والورق، والقماش، والبلاستيك. وهذه الفئة منتشرة كثيرًا في المنازل والمدارس. ويُطفئها الكبار بالماء أو بمطفأة مسحوق ABC.",image:"media/images/fire_class_a.png"},{heading:"الفئة B: السوائل والغازات القابلة للاشتعال",body:"البنزين، والنفط الأبيض (الكيروسين)، ومخفّف الطلاء (التنر)، والكحول، والغاز. وهي خطيرةٌ جدًا! لا تسكب عليها الماء أبدًا، لأن النار تنتشر. ويُطفئ الكبار السوائل المشتعلة بالرغوة، أو بثاني أكسيد الكربون (CO₂)، أو بمسحوق ABC (وللكحول: CO₂ أو مسحوق ABC أو رغوة خاصة مقاومة للكحول، لأن الرغوة العادية لا تنفع معه). أما الغاز فمختلف: يُغلق الكبار الغاز فقط إذا كان ذلك آمنًا. ولا يُطفأ لهب الغاز ما دام الغاز يتسرّب، لأن الغاز قد ينفجر. وإذا لم يمكن إيقاف الغاز بأمان، يخرج الجميع ويتصلون بالرقم 115.",image:"media/images/fire_class_b.png"},{heading:"الفئة C: الأجهزة الكهربائية",body:"الحاسوب، والتلفاز، والأسلاك، والمقابس الكهربائية. لا تسكب عليها الماء، لأن الكهرباء تقتل! يقطع الكبار الكهرباء أولًا، ثم يُطفئون النار بثاني أكسيد الكربون (CO₂) أو بمسحوق ABC. ملاحظة: يستخدم هذا الدرس أحرف النظام الأمريكي NFPA 10 مرجعًا للمشروع، ولم يُؤكَّد بعدُ النظام الرسمي في دهوك. ويستخدم النظام الأوروبي (EN 2) أحرفًا أخرى: NFPA A = EN A؛ NFPA B (السوائل) = EN B؛ NFPA B (الغازات) = EN C؛ NFPA C (المعدات الكهربائية الموصولة بالتيار) لا فئة لها في EN؛ NFPA D = EN D؛ NFPA K = EN F.",image:"media/images/fire_class_c.png"}],examples:["الفئة A = الخشب والورق والقماش.","الفئة B = البنزين والنفط الأبيض والغاز.","الفئة C = الأجهزة الكهربائية؛ لا تسكب عليها الماء.","الفئة D = المعادن، والفئة K = زيت الطبخ؛ مسحوق ABC لا يصلح لهما."],tips:["من الجيد أن تكون في المنزل مطفأة مسحوق ABC، وأن يعرف الكبار كيف يستخدمونها.","إذا رأيت نارًا، فلا تقترب منها لتعرف ما الذي يحترق: اخرج وأخبر أحد الكبار.","اتصلوا بالرقم 115 عند حدوث أيّ حريق."],warnings:["لا تسكب الماء أبدًا على حريق الزيت (K) أو الحريق الكهربائي (C)!"],realCase:"في أحد المطابخ، اشتعلت النار في الزيت داخل المقلاة. فسكب أحدهم الماء عليها، فارتفعت النار بقوة وانتشرت! وكانت الطريقة الصحيحة أن يُغلق أحد الكبار الغاز، ويضع غطاءً على المقلاة ليقطع عنها الأكسجين. لقد كان هذا حريقًا من الفئة K.",video:"media/videos/lesson_fire_types.mp4",game:{instruction:"أيّ هذه العبارات صحيحة؟ (نظام NFPA)",items:[{text:"الخشب يحترق = الفئة A",emoji:"🪵",correct:!0},{text:"البنزين يحترق = الفئة A",emoji:"🛢️",correct:!1},{text:"الكابل الكهربائي يحترق = الفئة C",emoji:"⚡",correct:!0},{text:"الورق يحترق = الفئة B",emoji:"📄",correct:!1},{text:"زيت المقلاة يحترق = الفئة K",emoji:"🍳",correct:!0}]},activity:{prompt:"رأيت النار قد اشتعلت في أحد حواسيب المدرسة، والمعلّم ينادي: «أحضروا الماء!» ماذا ستفعل؟",image:"media/images/activity_fire_types.png",options:[{text:"أقول: يا أستاذ، لا تسكبوا الماء عليه! هذا حريقٌ كهربائي (الفئة C). ثم نخرج ونتصل بالرقم 115.",correct:!0,feedback:"الكهرباء تقتل، لذلك لا يصلح الماء لحريق كهربائي؛ ثم يخرج الجميع ويتصلون بالرقم 115."},{text:"أُحضر الماء",correct:!1,feedback:"الماء على الحريق الكهربائي (الفئة C) خطر، لأن الكهرباء تقتل؛ أخبر المعلّم واخرج."},{text:"أسكب الماء على الحاسوب",correct:!1,feedback:"الأطفال لا يُطفئون النار، والماء على حريق الحاسوب خطر؛ اخرج واتصلوا بالرقم 115."},{text:"أركض ولا أخبر أحدًا",correct:!1,feedback:"بإخبار الآخرين يبقون هم أيضًا آمنين؛ نبّه المعلّم، واخرجوا معًا، واتصلوا بالرقم 115."}]},quiz:[{question:"إذا اشتعلت النار في البنزين، فماذا يستخدم الكبار؟",options:[{text:"الماء",correct:!1,feedback:"لا! الماء ينشر حريق البنزين."},{text:"الرغوة أو CO₂",correct:!0,feedback:"صحيح! الرغوة أو CO₂ مناسبان للسوائل المشتعلة مثل البنزين (الفئة B)."},{text:"يُهوّون عليها بالورق",correct:!1,feedback:"لا! الهواء يجعل النار أكبر."}]},{question:"أيّ مطفأة تصلح للفئات الثلاث A وB وC؟",options:[{text:"مطفأة الماء",correct:!1,feedback:"لا، الماء يصلح للفئة A فقط."},{text:"مطفأة مسحوق ABC",correct:!0,feedback:"صحيح! مسحوق ABC يصلح للفئات A وB وC، ولكنه لا يصلح للفئتين D وK."},{text:"لا توجد مطفأة كهذه",correct:!1,feedback:"لا، توجد مطفأة مسحوق ABC."}]},{question:"ترى نارًا. هل تقترب منها لتعرف ما الذي يحترق؟",options:[{text:"لا، أخرج وأُخبر أحد الكبار",correct:!0,feedback:"لا تقترب من النار لتعرف ما الذي يحترق: اخرج وأخبر أحد الكبار، واتصلوا بالرقم 115."},{text:"نعم، لأعرف إلى أيّ فئةٍ تنتمي",correct:!1,feedback:"لا تقترب من النار لتعرف ما الذي يحترق؛ اخرج وأخبر أحد الكبار، واتصلوا بالرقم 115."},{text:"نعم، ولكن للحظةٍ قصيرة فقط",correct:!1,feedback:"حتى للحظةٍ قصيرة، الاقتراب من النار ليس آمنًا؛ اخرج وأخبر أحد الكبار."}],explanation:"إذا رأيت نارًا، فلا تقترب منها لتعرف ما الذي يحترق: اخرج وأخبر أحد الكبار. واتصلوا بالرقم 115 عند حدوث أيّ حريق."},{question:"اشتعل الزيت في قِدر، وصديقك يريد أن يرمي عليه الماء. ماذا تقول له؟",options:[{text:"نعم، كوبٌ كبير من الماء سيُطفئها",correct:!1,feedback:"لا. لا تسكب الماء أبدًا على حريق الزيت (K)، فالنار ستنتشر."},{text:"لا، الماء يزيدها سوءًا؛ لنخرج",correct:!0,feedback:"صحيح. الماء على الزيت المشتعل يجعل النار تنتشر. اخرج وأخبر أحد الكبار."},{text:"نعم، ولكن بماءٍ بارد جدًا من الثلاجة فقط",correct:!1,feedback:"لا. الماء البارد يبقى ماءً، ويجعل حريق الزيت ينتشر."}],explanation:"لا تسكب الماء أبدًا على حريق زيت الطهي (K). الأطفال يخرجون ويُخبرون أحد الكبار."},{question:"اشتعلت النار في تلفاز. ماذا يفعل الكبار أولًا؟",options:[{text:"يقطعون الكهرباء",correct:!0,feedback:"صحيح. يقطع الكبار الكهرباء أولًا، أمّا الأطفال فيخرجون ويُخبرون أحد الكبار."},{text:"يسكبون الماء على التلفاز",correct:!1,feedback:"لا. لا تسكب الماء أبدًا على الحريق الكهربائي (C)، فالكهرباء تقتل."},{text:"يفتحون ظهر التلفاز لينظروا",correct:!1,feedback:"لا. فتحه خطير. يقطع الكبار الكهرباء أولًا."}],explanation:"في الحريق الكهربائي (C)، يقطع الكبار الكهرباء أولًا ولا يسكبون الماء أبدًا. أمّا الأطفال فيخرجون ويُخبرون أحد الكبار."}],steps:[{title:"لا تقترب",detail:"لا تقترب من النار لتعرف ما الذي يحترق.",critical:!0},{title:"اخرج",detail:"اخرج فورًا من أكثر الطرق أمانًا.",critical:!0},{title:"أخبر أحد الكبار بما رأيت",detail:"أخبر أحد الكبار بما يحترق، مثل قِدرٍ فيه زيت أو تلفاز.",critical:!0},{title:"اتصل بالرقم 115",detail:"إذا لم يكن أحدٌ من الكبار قريبًا، فاتصل بالرقم 115 من الخارج.",critical:!0}]},{id:17,icon:"Siren",accent:"#dc2626",title:"أبطال الدفاع المدني",subtitle:"عمل فريق 115 ومعدّاته",grades:"5-6",ages:"10-12",summary:"الدفاع المدني مؤسسةٌ حكومية تحمي أرواح الناس وممتلكاتهم. وتستجيب فرقه للحرائق والزلازل والفيضانات وأيّ كارثةٍ أخرى. وفي دهوك، فرقه جاهزةٌ ليلًا ونهارًا.",blocks:[{heading:"مهامّهم",body:"إطفاء الحرائق، وإنقاذ الأشخاص العالقين، والمساعدة أثناء الكوارث، وتعليم الناس قواعد السلامة.",image:"media/images/cd_work.png"},{heading:"معدّاتهم",body:"سيارات الإطفاء الحمراء، وخراطيم المياه الطويلة، والسلالم العالية، وأجهزة التنفّس (BA)، والملابس المقاومة للنار.",image:"media/images/cd_equipment.png"},{heading:"كيف تتصل؟",body:`إذا كان بالقرب منك أحدٌ من الكبار، فأخبره. وإن لم يكن، فاتصل بالرقم 115 وقل:
1. أين أنت (العنوان أو مكان قريب منك)
2. ماذا حدث
3. كم عدد المصابين
4. اسمك

لا تُغلق الهاتف حتى يطلبوا منك ذلك.`,image:"media/images/cd_call.png"}],examples:["السيارة الحمراء ذات صفّارة الإنذار = فريق 115 قادم.","السلّم العالي = يساعد رجال الإطفاء على الوصول إلى النوافذ العالية.","جهاز التنفّس = هواءٌ نقي وسط الدخان.","الملابس المقاومة للنار = تحمي الجسم من حرارة النار."],tips:["احفظ الرقم 115.","اعرف عنوان منزلك.","عندما تسمع صفّارة الإنذار، ابتعد عن الطريق وأفسح المجال للسيارة الحمراء."],warnings:["الاتصال بالرقم 115 ليس لعبة! إذا اتصلت دون سبب، فقد يبقى شخصٌ آخر من دون مساعدة."],realCase:"شبّ حريقٌ في أحد المنازل في دهوك، فاتصل أحد الجيران بالرقم 115. فوصل فريق 115 إلى المكان، وأطفأ النار، وأخرج الأشخاص العالقين بأمان.",video:"media/videos/lesson_cd_work.mp4",game:{instruction:"أيّ هذه الأعمال يقوم بها الدفاع المدني؟",items:[{text:"إطفاء الحرائق",emoji:"🔥",correct:!0},{text:"بيع البيتزا في السوق",emoji:"🍕",correct:!1},{text:"إنقاذ الأشخاص العالقين",emoji:"🆘",correct:!0},{text:"تقديم البرامج في التلفاز",emoji:"📺",correct:!1},{text:"تعليم التلاميذ قواعد السلامة",emoji:"🎓",correct:!0},{text:"المساعدة أثناء الفيضان",emoji:"🌊",correct:!0}]},activity:{prompt:"أنت في الشارع وترى دخانًا يخرج من نافذة أحد المنازل، ولا يوجد أحدٌ في الخارج. ماذا ستفعل؟",image:"media/images/activity_cd_call.png",options:[{text:"أبتعد عن المنزل، وأخبر أحد الكبار أو أتصل بنفسي بالرقم 115، وأذكر عنوان المكان",correct:!0,feedback:"الابتعاد يحميك، وبذكر عنوان المكان يصل فريق 115 بسرعة."},{text:"أدخل إلى المنزل لإنقاذ الناس",correct:!1,feedback:"الإنقاذ عمل فريق 115 بمعدّاته؛ والبطل الحقيقي لا يعرّض نفسه للخطر."},{text:"أركض ولا أخبر أحدًا",correct:!1,feedback:"قد يحتاج مَن في الداخل إلى المساعدة، لذلك أخبر أحد الكبار أو اتصل بالرقم 115 واذكر العنوان."},{text:"أبقى بالقرب من المنزل وأتفرّج",correct:!1,feedback:"البقاء قرب المنزل المحترق ليس آمنًا، والتفرّج لا يجلب المساعدة؛ ابتعد واتصل بالرقم 115."}]},quiz:[{question:"ما رقم الدفاع المدني؟",options:[{text:"122",correct:!1,feedback:"لا، الرقم 122 هو رقم الإسعاف."},{text:"115",correct:!0,feedback:"صحيح! الرقم 115 هو رقم الدفاع المدني."},{text:"104",correct:!1,feedback:"لا، الرقم 104 هو رقم الشرطة."}]},{question:"عندما تسمع صفّارة سيارة الإطفاء الحمراء، ماذا تفعل؟",options:[{text:"أركض في وسط الشارع",correct:!1,feedback:"هذا ليس آمنًا!"},{text:"أبتعد عن الطريق وأفسح لها المجال",correct:!0,feedback:"صحيح! أفسح الطريق لسيارة الدفاع المدني."},{text:"أركض خلف السيارة لأرى إلى أين تذهب",correct:!1,feedback:"هذا ليس آمنًا! قد تصدمك سيارة."}]},{question:"هناك أشخاصٌ عالقون في منزلٍ يحترق. من يدخل لإنقاذهم؟",options:[{text:"فريق 115، بمعدّاته",correct:!0,feedback:"الإنقاذ عمل فريق 115 بمعدّاته، مثل أجهزة التنفّس والملابس المقاومة للنار."},{text:"طفلٌ يريد أن يكون بطلًا حقيقيًا",correct:!1,feedback:"البطل الحقيقي لا يعرّض نفسه للخطر؛ ابتعد، وأخبر أحد الكبار أو اتصل بالرقم 115."},{text:"أحد الجيران",correct:!1,feedback:"يساعد الجيران بالاتصال بالرقم 115؛ أمّا إنقاذ العالقين فهو عمل فريق 115 بمعدّاته."}],explanation:"إنقاذ الأشخاص العالقين عمل فريق 115، بأجهزة التنفّس والملابس المقاومة للنار. والبطل الحقيقي لا يعرّض نفسه للخطر: ابتعد، وأخبر أحد الكبار أو اتصل بالرقم 115."},{question:"وصل فريق 115 إلى الحريق، وأنت تعرف أن شخصًا ما زال في الداخل. ماذا تفعل؟",options:[{text:"أعود إلى الداخل لأُري الفريق الطريق",correct:!1,feedback:"لا. لا تعُد إلى الداخل أبدًا. فقط أخبر الفريق أين الشخص."},{text:"أُخبر أحد الكبار أو فريق 115 فورًا",correct:!0,feedback:"صحيح. هذه المعلومة تساعد الفريق على إيجاد الشخص بسرعة."},{text:"لا أقول شيئًا حتى لا أُزعجهم",correct:!1,feedback:"لا. الفريق يحتاج إلى هذه المعلومة. أخبرهم فورًا."}],explanation:"أخبر أحد الكبار أو فريق 115 فورًا بأن شخصًا في الداخل. ولا تعُد أنت إلى الداخل أبدًا."},{question:"يدخل رجل إطفاء من فريق 115 يلبس جهاز التنفّس إلى غرفةٍ مليئة بالدخان، وأنت خائف. ماذا تفعل؟",options:[{text:"أختبئ تحت السرير حتى يذهب",correct:!1,feedback:"لا. لا تختبئ أبدًا في الحريق. إذا اختبأت، فلن يستطيعوا أن يجدوك."},{text:"أهرب من القناع المخيف",correct:!1,feedback:"لا. الشخص الذي يلبس القناع جاء لينقذك. اذهب إليه."},{text:"أناديه وأذهب إليه",correct:!0,feedback:"صحيح. جهاز التنفّس يساعدهم على التنفّس في الدخان، وقد جاؤوا لمساعدتك."}],explanation:"يلبس فريق 115 أجهزة التنفّس (BA) في الدخان. لا تخف ولا تختبئ أبدًا، بل نادِهم ليجدوك."}],steps:[{title:"ابتعد عن الطريق",detail:"عندما تسمع صفّارة الإنذار، تنحَّ جانبًا ودع السيارة الحمراء تمرّ.",critical:!0},{title:"ابقَ بعيدًا",detail:"لا تقترب من النار أو من عمل الإنقاذ، ولا تتبع السيارة الحمراء.",critical:!0},{title:"أخبرهم بما تعرفه",detail:"إذا كان شخصٌ ما زال في الداخل، فأخبر أحد الكبار أو فريق 115 فورًا.",critical:!0},{title:"افعل ما يقولونه",detail:"استمع إلى فريق 115، وافعل ما يطلبونه منك.",critical:!1}]},{id:18,icon:"ShieldAlert",accent:"#c2410c",title:"أجسام خطرة: الألغام والذخائر غير المنفجرة",subtitle:"لا تلمس، ابتعد، أخبر شخصًا كبيرًا",grades:"1-6",ages:"6-12",summary:"بعد الحرب، قد تبقى بعض الأجسام الغريبة في الأرض سنوات طويلة. وبعضها قد ينفجر، حتى لو بدا قديمًا أو صدئًا. وبضع قواعد سهلة تحميك وتحمي أصدقاءك.",blocks:[{heading:"الأجسام الغريبة قد تنفجر",body:"قد تكون الألغام والمتفجرات الأخرى كبيرة أو صغيرة، وبأي شكل أو لون. بعضها يشبه الألعاب أو العلب أو قطع الحديد القديمة. وقد تختبئ بين الأعشاب أو في التراب أو في المباني القديمة. ولا يمكنك أن تعرف بالنظر إن كانت آمنة."},{heading:"قواعد السلامة",body:`• لا تلمسه، ولا تركله، ولا تلتقطه.
• لا ترمِه بالحجارة.
• لا تقترب لتنظر إليه.
• ابتعد وأبعِد أصدقاءك أيضًا.
• أخبر شخصًا كبيرًا فورًا.`},{heading:"العلامات والأماكن الخطرة",body:"العلامات الحمراء والأسيجة والأشرطة والحجارة الحمراء تدلّ على مكان خطر. لا تتجاوزها أبدًا، ولا تنزع العلامة أبدًا. والمكان الذي لا علامة فيه قد يكون خطرًا أيضًا. امشِ والعب فقط حيث يمشي الناس ويلعبون كل يوم."},{heading:"إذا ظننت أنك في مكان خطر",body:"توقّف. اثبت في مكانك تمامًا. نادِ طلبًا للمساعدة. انتظر حتى يأتي شخص كبير أو منقذ. لا تركض ولا تعُد إلى الوراء."}],examples:["جسم معدني غريب بين الأعشاب = لا تلمسه، وأخبر شخصًا كبيرًا.","علامة حمراء عليها جمجمة = خطر، لا تدخل.","جسم يشبه اللعبة في حقل = اتركه وأخبر شخصًا كبيرًا.","الكبار يتصلون بالرقم 115 = رقم الدفاع المدني."],tips:["امشِ على الطرق والممرات التي يستخدمها الناس كل يوم.","أخبر شخصًا كبيرًا عن كل جسم غريب تراه.","ذكّر أصدقاءك بقواعد السلامة."],warnings:["لا تلمس جسمًا غريبًا أبدًا، ولا تركله، ولا تلتقطه، ولا ترمِه بالحجارة!"],realCase:"في طريق العودة من المدرسة، رأت فتاة جسمًا معدنيًّا غريبًا بجانب الطريق. لم تقترب منه، وطلبت من صديقاتها أن يبقين بعيدًا، ومشين إلى البيت على الطريق. أخبرت أمها، فاتصلت أمها بالرقم 115 وقالت لها: «لقد فعلتِ الصواب!»",game:{instruction:"ترى جسمًا غريبًا. ما الأفعال الآمنة؟",items:[{text:"أخبر شخصًا كبيرًا",emoji:"🗣️",correct:!0},{text:"اركله",emoji:"🦶",correct:!1},{text:"ابتعد",emoji:"🚶",correct:!0},{text:"التقطه",emoji:"✋",correct:!1},{text:"أبعِد أصدقاءك",emoji:"👫",correct:!0},{text:"ارمِه بالحجارة",emoji:"🪨",correct:!1}]},activity:{prompt:"وجدتَ أنت وصديقك جسمًا معدنيًّا غريبًا قرب الملعب، ويريد صديقك أن يلتقطه. ماذا تفعل؟",options:[{text:"أقول: «توقّف، لا تلمسه!»، ثم نبتعد وأخبر شخصًا كبيرًا",correct:!0,feedback:"الأجسام الغريبة قد تنفجر. الابتعاد معًا وإخبار شخص كبير يحميكما كليكما."},{text:"ننظر إليه عن قرب لنعرف ما هو",correct:!1,feedback:"الاقتراب خطر. ابتعد وأخبر شخصًا كبيرًا."},{text:"نرميه بحجارة صغيرة من بعيد",correct:!1,feedback:"رمي أي شيء عليه قد يجعله ينفجر. ابتعد وأخبر شخصًا كبيرًا."},{text:"نأخذه إلى البيت لنريه لعائلتنا",correct:!1,feedback:"لا تحمل جسمًا غريبًا أبدًا: فقد ينفجر. اتركه في مكانه وأخبر شخصًا كبيرًا."}]},quiz:[{question:"ماذا تفعل إذا رأيت جسمًا غريبًا على الأرض؟",options:[{text:"أبتعد وأخبر شخصًا كبيرًا",correct:!0},{text:"ألتقطه وآخذه إلى المعلّم لأريه إياه",correct:!1},{text:"أركله ليبتعد",correct:!1}],explanation:"الأجسام الغريبة قد تنفجر. لا تلمسها ولا تركلها: ابتعد وأخبر شخصًا كبيرًا فورًا."},{question:"ماذا تعني العلامة الحمراء التي عليها جمجمة؟",options:[{text:"خطر: لا تتجاوزها",correct:!0},{text:"مكان جيد للعب الغمّيضة",correct:!1},{text:"طريق مختصر إلى البيت",correct:!1}],explanation:"العلامة الحمراء التي عليها جمجمة تحذّر من الخطر. لا تتجاوزها أبدًا ولا تنزعها أبدًا."},{question:"تظن أنك في مكان خطر. ماذا تفعل؟",options:[{text:"أتوقّف ولا أتحرّك، وأنادي طلبًا للمساعدة، وأنتظر",correct:!0},{text:"أركض بأقصى سرعة أستطيعها لأخرج من هذا المكان",correct:!1},{text:"أعود بحذر شديد على آثار قدميّ نفسها حتى أصل إلى الطريق",correct:!1}],explanation:"عندما تثبت في مكانك لا تطأ جسمًا خطرًا آخر. نادِ طلبًا للمساعدة وانتظر شخصًا كبيرًا أو منقذًا."},{question:"وجد صديقك شيئًا معدنيًا قديمًا في حقل، ويريد أن يأخذه إلى البيت. ماذا تقول له؟",options:[{text:"لا! اتركه، وابتعد، ولنُخبر شخصًا كبيرًا",correct:!0,feedback:"صحيح. الأجسام الغريبة قد تنفجر. ابتعد وأخبر شخصًا كبيرًا."},{text:"نعم، ولكن احمله ببطء وحذر شديد",correct:!1,feedback:"لا. لا تلتقط جسمًا غريبًا أبدًا، حتى بحذر، فقد ينفجر."},{text:"نعم، ولكن اغسل الطين عنه أولًا",correct:!1,feedback:"لا. لا تلمسه أبدًا. اتركه، وابتعد، وأخبر شخصًا كبيرًا."}],explanation:"الأجسام الغريبة قد تنفجر. لا تلمسها أبدًا، ولا تلتقطها، ولا تأخذها إلى البيت. ابتعد، وأبعِد أصدقاءك، وأخبر شخصًا كبيرًا."},{question:"لا توجد علامة قرب مبنى قديم. هل اللعب هناك آمن؟",options:[{text:"نعم، عدم وجود علامة يعني أن المكان آمن",correct:!1,feedback:"لا. المكان الذي لا علامة فيه قد يكون خطرًا أيضًا."},{text:"نعم، إذا كان الأطفال الأكبر يلعبون هناك أيضًا",correct:!1,feedback:"لا. الأطفال الأكبر قد يخطئون أيضًا. العب فقط حيث يلعب الناس كل يوم."},{text:"ليس بالضرورة؛ ألعب حيث يلعب الناس كل يوم",correct:!0,feedback:"صحيح. المكان الذي لا علامة فيه قد يكون خطرًا أيضًا."}],explanation:"المكان الذي لا علامة فيه قد يكون خطرًا أيضًا. امشِ والعب فقط حيث يمشي الناس ويلعبون كل يوم."}],steps:[{title:"لا تلمس",detail:"لا تلمس الجسم الغريب، ولا تركله، ولا تلتقطه.",critical:!0},{title:"ابتعد",detail:"لا تقترب أكثر. ابتعد، وأبعِد أصدقاءك أيضًا.",critical:!0},{title:"أخبر شخصًا كبيرًا",detail:"أخبر شخصًا كبيرًا فورًا، وقل له أين رأيته. والكبير يتصل بالرقم 115.",critical:!0},{title:"في مكانٍ خطر: توقّف وانتظر",detail:"توقّف. اثبت في مكانك. نادِ طلبًا للمساعدة. انتظر شخصًا كبيرًا أو منقذًا.",critical:!0}]},{id:19,icon:"LifeBuoy",accent:"#0284c7",title:"السلامة في الماء",subtitle:"السباحة واللعب بالقرب من الماء",grades:"1-6",ages:"6-12",summary:"السباحة واللعب في الماء ممتعان، لكن الماء قد يكون خطيرًا. فالأنهار والسدود وقنوات المياه والبرك والمسابح قد تكون عميقة أو باردة أو سريعة الجريان. وقد يحدث الغرق بسرعة وبصمت، لذلك ابقَ دائمًا مع شخص كبير يراقبك.",blocks:[{heading:"الماء قد يكون خطيرًا",body:"الأنهار والسدود وقنوات المياه والبرك والمسابح قد تكون عميقة. وقد يكون الماء باردًا وسريع الجريان، حتى لو بدا هادئًا. ولا يمكنك أن ترى القاع ولا ما يختبئ تحت الماء."},{heading:"دائمًا مع شخص كبير يراقبك",body:"استأذن أحد الكبار قبل أن تقترب من الماء. لا تسبح ولا تلعب في الماء إلا إذا كان معك شخص كبير يراقبك طوال الوقت. لا تسبح وحدك أبدًا، حتى لو كنت تجيد السباحة."},{heading:"قبل أن تنزل إلى الماء",body:"البس سترة نجاة على مقاسك بالقرب من الأنهار والبحيرات والسدود وفي القارب. لا تقفز أبدًا في ماء لا تعرف عمقه: فقد تختبئ تحت الماء صخور أو أماكن ضحلة."},{heading:"إذا كان أحدٌ في خطر في الماء",body:`لا تنزل إلى الماء. اصرخ بصوت عالٍ لتنادي أحد الكبار. ارمِ شيئًا يطفو، مثل كرة أو طوق نجاة، وابقَ بعيدًا عن الحافة. وإذا لم يكن أحد من الكبار قريبًا، فاتصل بالرقم 115.

الطفل لا ينزل إلى الماء أبدًا لإنقاذ أحد.`}],examples:["حتى النهر الهادئ قد يكون عميقًا وباردًا وسريع الجريان.","عندما تسبح، يراقبك شخص كبير طوال الوقت.","سترة النجاة التي على مقاسك تساعدك على الطفو.","أحدٌ في خطر في الماء: اصرخ لتنادي أحد الكبار وارمِ شيئًا يطفو."],tips:["استأذن أحد الكبار دائمًا قبل أن تقترب من الماء.","لا تسبح وحدك أبدًا.","تعلّم السباحة مع مدرّب مؤهَّل. حتى السبّاحون الماهرون يحتاجون إلى شخص كبير يراقبهم."],warnings:["لا تنزل إلى الماء أبدًا لإنقاذ أحد! اصرخ لتنادي أحد الكبار وارمِ شيئًا يطفو."],realCase:"في يوم صيفي حار، كان صديقان بالقرب من قناة مياه. أراد أحدهما أن يقفز في الماء ليبرد جسمه. فرفض الصديق الآخر: فهما لا يعرفان عمق الماء، ولم يكن معهما أحد من الكبار. فعادا إلى البيت وأخبرا والديهما. وفي وقت لاحق، سبحا في مسبح وكان شخص كبير يراقبهما طوال الوقت.",game:{instruction:"أيّ هذه الأفعال آمنة بالقرب من الماء؟ اختر الإجابات الصحيحة:",items:[{text:"استأذن أحد الكبار قبل الاقتراب من الماء",emoji:"🙋",correct:!0},{text:"اسبح وحدك في النهر",emoji:"🌊",correct:!1},{text:"البس سترة نجاة على مقاسك",emoji:"🦺",correct:!0},{text:"اقفز في ماء لا تعرف عمقه",emoji:"🤸",correct:!1},{text:"اصرخ لتنادي أحد الكبار وارمِ شيئًا يطفو",emoji:"📣",correct:!0},{text:"انزل إلى الماء لإنقاذ صديقك",emoji:"🏊",correct:!1}]},activity:{prompt:"أنت تلعب مع صديقك بالقرب من بركة. انزلق صديقك وسقط في الماء العميق. ماذا ستفعل؟",options:[{text:"لا أنزل إلى الماء، وأصرخ بصوت عالٍ لأنادي أحد الكبار، وأرمي شيئًا يطفو",correct:!0,feedback:"الطفل لا ينزل إلى الماء أبدًا لإنقاذ أحد. الصراخ يجلب أحد الكبار، والشيء الذي يطفو يساعد صديقك على البقاء فوق الماء."},{text:"أقفز في الماء وأُخرج صديقي",correct:!1,feedback:"إذا نزلت إلى الماء فقد تغرق أنت أيضًا. ابقَ خارج الماء، واصرخ لتنادي أحد الكبار، وارمِ شيئًا يطفو."},{text:"أنحني فوق الحافة وأمسك يد صديقي",correct:!1,feedback:"قد تنزلق أنت أيضًا أو تُسحب إلى الماء. ابتعد عن الحافة، واصرخ لتنادي أحد الكبار، وارمِ شيئًا يطفو."},{text:"أركض إلى البيت من الخوف ولا أخبر أحدًا",correct:!1,feedback:"صديقك يحتاج إلى المساعدة بسرعة. اصرخ فورًا لتنادي أحد الكبار؛ وإذا لم يكن أحد منهم قريبًا، فاتصل بالرقم 115."}]},quiz:[{question:"عندما تسبح أو تلعب بالقرب من الماء، من يجب أن يكون معك؟",options:[{text:"شخص كبير يراقبك طوال الوقت",correct:!0},{text:"صديق في مثل عمرك يجيد السباحة",correct:!1},{text:"لا أحد، إذا كنت تجيد السباحة من قبل",correct:!1}],explanation:"قد يحدث الغرق بسرعة وبصمت. يجب أن يكون شخص كبير قريبًا منك ويراقبك طوال الوقت، حتى لو كنت تعرف السباحة."},{question:"صديقك في خطر في الماء. ماذا تفعل؟",options:[{text:"لا تنزل إلى الماء، واصرخ لتنادي أحد الكبار، وارمِ شيئًا يطفو",correct:!0},{text:"اقفز بسرعة في الماء واسحب صديقك إلى حافة الماء",correct:!1},{text:"ابقَ صامتًا على الحافة حتى يخرج صديقك من الماء وحده",correct:!1}],explanation:"الطفل لا ينزل إلى الماء أبدًا لإنقاذ أحد. الصراخ يجلب أحد الكبار، والشيء الذي يطفو يساعد صديقك على البقاء فوق الماء."},{question:"تريد أن تقفز في نهر، لكنك لا تعرف عمقه. ما التصرف الصحيح؟",options:[{text:"لا تقفز: فقد تختبئ تحت الماء صخور أو أماكن ضحلة",correct:!0},{text:"اقفز، لأن الأطفال الأكبر سنًّا يقفزون في الماء هناك",correct:!1},{text:"اقفز برأسك أولًا حتى تصل إلى الماء العميق بسرعة",correct:!1}],explanation:"لا يمكنك أن ترى ما تحت الماء. فالصخرة المختبئة أو المكان الضحل قد يسببان إصابة خطيرة جدًّا. لا تقفز أبدًا في ماء لا تعرف عمقه."},{question:"تذهب مع عائلتك إلى النهر. ماذا تلبس بالقرب من الماء؟",options:[{text:"سترة النجاة الخاصة بأخي الكبير",correct:!1,feedback:"لا. يجب أن تكون سترة النجاة على مقاسك. الكبيرة لا تناسبك."},{text:"سترة نجاة على مقاسي",correct:!0,feedback:"صحيح. بالقرب من الأنهار والبحيرات والسدود، البس سترة نجاة على مقاسك."},{text:"لا شيء، لأنني أجيد السباحة",correct:!1,feedback:"لا. حتى السبّاحون الماهرون يحتاجون قرب النهر إلى سترة نجاة وشخصٍ كبير يراقبهم."}],explanation:"البس سترة نجاة على مقاسك بالقرب من الأنهار والبحيرات والسدود وفي القارب."},{question:"يبدو الماء هادئًا وغير عميق. هل تستطيع أن تسبح هناك وحدك؟",options:[{text:"نعم، الماء الهادئ آمن دائمًا",correct:!1,feedback:"لا. قد يكون الماء عميقًا وباردًا وسريع الجريان، حتى لو بدا هادئًا."},{text:"نعم، إذا بقيت قرب الحافة",correct:!1,feedback:"لا. لا تسبح وحدك أبدًا، حتى قرب الحافة. يجب أن يراقبك شخصٌ كبير."},{text:"لا، فقط عندما يراقبني شخصٌ كبير",correct:!0,feedback:"صحيح. يجب أن يراقبك شخصٌ كبير طوال الوقت وأنت في الماء."}],explanation:"قد يكون الماء عميقًا وباردًا وسريع الجريان، حتى لو بدا هادئًا. لا تسبح وحدك أبدًا؛ يجب أن يراقبك شخصٌ كبير طوال الوقت."}],steps:[{title:"لا تنزل إلى الماء",detail:"لا تنزل إلى الماء أبدًا لإنقاذ أحد.",critical:!0},{title:"نادِ أحد الكبار",detail:"اصرخ بصوتٍ عالٍ لتنادي أحد الكبار.",critical:!0},{title:"ارمِ شيئًا يطفو",detail:"ارمِ كرةً أو طوق نجاة، وابقَ بعيدًا عن الحافة.",critical:!0},{title:"اتصل بالرقم 115",detail:"إذا لم يكن أحدٌ من الكبار قريبًا، فاتصل بالرقم 115.",critical:!0}]},{id:20,icon:"Fuel",accent:"#b45309",title:"المدافئ والمولّدات وأول أكسيد الكربون",subtitle:"خطر لا تراه ولا تشمّه",grades:"1-6",ages:"6-12",summary:"المدافئ والمولّدات ومناقل الفحم تدفئنا وتعطينا الضوء. لكنها عندما تحرق الوقود تصنع غازًا اسمه أول أكسيد الكربون (CO). هذا الغاز بلا لون ولا رائحة، وقد يجعل الناس مرضى جدًا. تعلّم ماذا تفعل إذا شعرت بتعب بالقرب منها.",blocks:[{heading:"غاز لا تراه",body:"المدافئ والمولّدات ومناقل الفحم والسيارات تصنع أول أكسيد الكربون عندما تحرق الوقود. لا يمكنك أن تراه أو تشمّه. وفي غرفة مغلقة قد يتجمّع ويجعل الجميع مرضى."},{heading:"علامات الخطر",body:"الصداع والدوار والغثيان أو النعاس الشديد قرب مدفأة أو مولّدة قد تكون علامات على CO. وإذا شعر عدة أشخاص بالشيء نفسه في الوقت نفسه فهذه علامة قوية. وإذا رنّ جهاز إنذار CO يخرج الجميع."},{heading:"المولّدة تبقى في الخارج",body:"تعمل المولّدة في الخارج فقط، بعيدًا عن الأبواب والنوافذ، وليس داخل البيت أو المرآب أبدًا، حتى لو كانت الأبواب مفتوحة. ولا يلمس الأطفال المولّدة أو وقودها أو أسلاكها أبدًا. ولا يُدخَل منقل الفحم إلى البيت لتدفئة الغرفة أبدًا."},{heading:"إذا شعرت بالتعب أو رنّ الإنذار",body:"أخبر أحد الكبار فورًا. يخرج الجميع إلى الهواء الطلق. اتصل بالرقم 115 من الخارج. ولا يعود أحد إلى الداخل حتى يقول الدفاع المدني إن المكان آمن."}],examples:["منقل الفحم في غرفة مغلقة خطير.","تعمل المولّدة في الخارج، بعيدًا عن الأبواب والنوافذ.","الجميع يشعرون بالصداع قرب المدفأة: اخرج وأخبر أحد الكبار.","رنّ جهاز إنذار CO: يخرج الجميع."],tips:["اطلب من أسرتك تركيب جهاز إنذار CO في البيت.","أبعد الألعاب والملابس والستائر عن المدفأة.","يطفئ أحد الكبار المدفأة قبل أن ينام الجميع."],warnings:["لا تُدخل المولّدة أو منقل الفحم إلى البيت أبدًا!","لا تلمس المدفأة أو المولّدة أو وقودهما أو أسلاكهما أبدًا!"],realCase:"في ليلة شتوية باردة، دفّأت أسرة غرفتها بمنقل فحم وأغلقت الباب. وبعد مدة، شعر الأطفال بالصداع والغثيان. تذكّرت الأخت الكبرى درسها: أيقظت أمها وقالت إن عليهم الخروج. خرجت الأسرة إلى الهواء الطلق واتصلت بالرقم 115. وقال لهم الدفاع المدني ألّا يحرقوا الفحم في غرفة مغلقة أبدًا.",game:{instruction:"أيّ هذه الأفعال آمنة؟ اختر الإجابات الصحيحة:",items:[{text:"المولّدة في الخارج بعيدًا عن النوافذ",emoji:"🏠",correct:!0},{text:"أدخل منقل الفحم إلى غرفة النوم",emoji:"🔥",correct:!1},{text:"اخرج إلى الهواء الطلق عندما تشعر بالصداع",emoji:"🌬️",correct:!0},{text:"العب قرب المولّدة ووقودها",emoji:"⛽",correct:!1},{text:"أخبر أحد الكبار عندما يرنّ إنذار CO",emoji:"🔔",correct:!0},{text:"نم قرب مدفأة مشتعلة في غرفة مغلقة",emoji:"😴",correct:!1}]},activity:{prompt:"في الشتاء، كل أسرتك في غرفة مغلقة والمدفأة مشتعلة. أنت وأخوك تشعران بالصداع والدوار. ماذا ستفعل؟",options:[{text:"أنام حتى يذهب الصداع",correct:!1,feedback:"النوم في غرفة فيها CO خطير جدًا. أخبر أحد الكبار واخرجوا إلى الهواء الطلق."},{text:"أخبر أحد الكبار فورًا ونخرج جميعًا إلى الهواء الطلق",correct:!0,feedback:"الصداع والدوار قرب المدفأة قد يكونان علامتين على CO. الهواء الطلق ومساعدة الكبار أولًا، ثم اتصلوا بالرقم 115 من الخارج."},{text:"أطفئ المدفأة بنفسي وأبقى في الغرفة",correct:!1,feedback:"الأطفال لا يلمسون المدفأة، والغاز يبقى في الغرفة. أخبر أحد الكبار واخرج."},{text:"أفتح النافذة قليلًا وأواصل اللعب",correct:!1,feedback:"النافذة المفتوحة قليلًا لا تكفي. يجب أن يخرج الجميع إلى الهواء الطلق ويتصل أحد الكبار بالرقم 115."}]},quiz:[{question:"هل يمكنك أن تشمّ أول أكسيد الكربون (CO)؟",options:[{text:"لا، فهو بلا لون ولا رائحة",correct:!0},{text:"نعم، رائحته مثل البيض الفاسد",correct:!1},{text:"نعم، يصنع دائمًا دخانًا أسود كثيفًا",correct:!1}],explanation:"غاز CO بلا لون ولا رائحة، ولهذا هو خطير جدًا ويساعد جهاز الإنذار على كشفه."},{question:"أين يجب أن تعمل المولّدة؟",options:[{text:"داخل المرآب والباب مفتوح",correct:!1},{text:"في الخارج، بعيدًا عن الأبواب والنوافذ",correct:!0},{text:"في الممر الداخلي قرب باب البيت الأمامي",correct:!1}],explanation:"المولّدة تصنع CO، لذلك تعمل في الخارج فقط بعيدًا عن الأبواب والنوافذ، ولا تعمل داخل البيت أو المرآب أبدًا."},{question:"كل من في الغرفة يشعرون بالصداع قرب المدفأة. ماذا تفعل أولًا؟",options:[{text:"أستلقي وأرتاح حتى يذهب الصداع",correct:!1},{text:"أغلق الباب ليبقى المكان دافئًا",correct:!1},{text:"أخبر أحد الكبار وأخرج إلى الهواء الطلق",correct:!0}],explanation:"إذا شعر عدة أشخاص بالصداع معًا فقد يكون السبب CO. الهواء الطلق وإخبار الكبار قبل كل شيء."},{question:"رنّ جهاز إنذار CO في البيت. ما التصرف الصحيح؟",options:[{text:"يخرج الجميع ويتصل أحد الكبار بالرقم 115",correct:!0},{text:"أطفئ الإنذار بنفسي لأن صوته عالٍ",correct:!1},{text:"أبحث عن المكان الذي يأتي منه الغاز",correct:!1}],explanation:"الإنذار يعني أن في البيت CO. يخرج الجميع ويتصلون بالرقم 115 من الخارج، ولا يعود أحد حتى يُقال إن المكان آمن."},{question:"يريد ابن عمك تدفئة غرفة النوم بمنقل فحم. ماذا تقول؟",options:[{text:"فكرة جيدة، لكن والباب مغلق فقط",correct:!1},{text:"لا، لا نحرق الفحم داخل الغرفة أبدًا",correct:!0},{text:"نعم، إذا نمنا بعيدًا عن المنقل",correct:!1}],explanation:"الفحم المشتعل يصنع CO الذي يتجمّع في الغرفة المغلقة، لذلك لا يُدخَل منقل الفحم إلى البيت أبدًا."}],steps:[{title:"أخبر أحد الكبار",detail:"أخبر أحد الكبار فورًا.",critical:!0},{title:"اخرج",detail:"يخرج الجميع إلى الهواء الطلق.",critical:!0},{title:"اتصل بالرقم 115",detail:"اتصل بالرقم 115 من الخارج.",critical:!0},{title:"ابقَ في الخارج",detail:"لا تعد إلى الداخل حتى يقول الدفاع المدني إن المكان آمن.",critical:!0}]},{id:21,icon:"Sparkles",accent:"#7c3aed",title:"الألعاب النارية وإطلاق النار في المناسبات",subtitle:"نحتفل دون أن نتأذّى",grades:"1-6",ages:"6-12",summary:"في الأعراس والأعياد والفوز في مباريات كرة القدم، يستعمل بعض الناس الألعاب النارية أو يطلقون النار في الهواء. الألعاب النارية قد تحرق اليدين والوجه والعينين وتسبّب الحرائق. والرصاصة التي تُطلق في الهواء تعود إلى الأرض وقد تؤذي أو تقتل شخصًا بعيدًا. ويمكنك أن تحتفل بطرق أخرى آمنة.",blocks:[{heading:"الألعاب النارية ليست ألعابًا",body:"الألعاب النارية والشرارات اليدوية حارّة جدًا وقد تنفجر في يدك. يمكن أن تحرق جلدك وتؤذي عينيك. ولا يُشعل الأطفال الألعاب النارية ولا يمسكونها ولا يرمونها أبدًا، حتى الشرارات اليدوية الصغيرة."},{heading:"لعبة نارية لم تنفجر",body:"أحيانًا لا تنفجر اللعبة النارية، لكنها قد تنفجر لاحقًا. لا تقترب منها أبدًا، ولا تلتقطها، ولا تحاول إشعالها مرة أخرى. أخبر أحد الكبار."},{heading:"الرصاصة تعود إلى الأرض",body:"الرصاصة التي تُطلق في الهواء لا تختفي، بل تعود إلى الأرض بسرعة وقد تؤذي أو تقتل شخصًا بعيدًا. عندما يطلق الناس النار احتفالًا، ادخل إلى البيت تحت سقف متين، بعيدًا عن السطوح والساحات المكشوفة."},{heading:"الأسلحة والرصاص",body:"لا تلمس أبدًا سلاحًا أو رصاصة أو ظرف رصاصة تجده. ابتعد وأخبر أحد الكبار فورًا. وإذا أُصيب أحد فاتصل بالرقم 115 أو 122."}],examples:["الشرارة اليدوية حارّة جدًا وقد تحرق يدك.","اللعبة النارية التي لم تنفجر قد تنفجر لاحقًا.","الرصاصة التي تُطلق في الهواء تعود إلى الأرض.","عندما يطلق الناس النار، ادخل تحت سقف متين."],tips:["احتفل بالأغاني والدبكة والطبول والبالونات.","شاهد الألعاب النارية من بعيد فقط ومع أحد الكبار.","اطلب من أسرتك أن تحتفل دون سلاح."],warnings:["لا تُشعل الألعاب النارية ولا تمسكها ولا ترمها أبدًا، حتى الشرارات اليدوية الصغيرة!","لا تلمس أبدًا سلاحًا أو رصاصة تجدها: ابتعد وأخبر أحد الكبار!"],realCase:"في عرس في الحيّ، بدأ بعض الضيوف يطلقون النار في الهواء. وكان صبيّ وأخته الصغيرة يلعبان على السطح. ناداهما عمّهما، فدخلا البيت بسرعة وبقيا تحت سقفه المتين. وفي الصباح، وجد الصبي في الشارع لعبة نارية لم تنفجر. لم يلمسها، بل أخبر أباه، فأبعد الأب الأطفال الآخرين عنها.",game:{instruction:"أيّ هذه الأفعال آمنة؟ اختر الإجابات الصحيحة:",items:[{text:"احتفل بالأغاني والطبول",emoji:"🥁",correct:!0},{text:"أمسك شرارة يدوية بيدك",emoji:"✨",correct:!1},{text:"ادخل البيت عندما يطلقون النار",emoji:"🏠",correct:!0},{text:"التقط لعبة نارية لم تنفجر",emoji:"🎆",correct:!1},{text:"أخبر أحد الكبار عندما تجد رصاصة",emoji:"🙋",correct:!0},{text:"العب على السطح أثناء إطلاق النار",emoji:"🎉",correct:!1}]},activity:{prompt:"في حفلة العيد، يعطيك صبيّ أكبر منك لعبة نارية وولّاعة ويقول إن إشعالها ممتع. ماذا ستفعل؟",options:[{text:"أشعلها لكن أبعدها عن وجهي",correct:!1,feedback:"قد تنفجر الألعاب النارية في يدك وتحرقك. الأطفال لا يُشعلون الألعاب النارية أبدًا."},{text:"أقول لا، ولا آخذها، وأخبر أحد الكبار",correct:!0,feedback:"صحيح. الألعاب النارية ليست ألعابًا، والكبار يستطيعون إبعادها بأمان."},{text:"آخذها وأرميها في الشارع",correct:!1,feedback:"قد يجدها شخص آخر ويتأذّى. لا تأخذها وأخبر أحد الكبار."},{text:"أضعها في جيبي لوقت لاحق",correct:!1,feedback:"اللعبة النارية في الجيب قد تحرقك. قل لا وأخبر أحد الكبار."}]},quiz:[{question:"ماذا يحدث للرصاصة التي تُطلق في الهواء؟",options:[{text:"تعود إلى الأرض وقد تؤذي أحدًا",correct:!0},{text:"تصعد إلى السماء وتختفي",correct:!1},{text:"تتكسّر إلى قطع صغيرة غير مؤذية",correct:!1}],explanation:"الرصاصة لا تختفي، بل تعود بسرعة وقد تقتل أو تؤذي شخصًا بعيدًا."},{question:"بدأ الناس يطلقون النار في عرس قرب بيتك. إلى أين تذهب؟",options:[{text:"أصعد إلى السطح لأشاهدهم",correct:!1},{text:"أخرج إلى الساحة المكشوفة لألعب",correct:!1},{text:"أدخل البيت تحت سقف متين",correct:!0}],explanation:"الرصاص يسقط من السماء. السقف المتين يحميك، أما السطوح والساحات المكشوفة فخطيرة."},{question:"رأيت في الشارع لعبة نارية لم تنفجر. ماذا تفعل؟",options:[{text:"ألتقطها وأشعلها مرة أخرى",correct:!1},{text:"أبتعد وأخبر أحد الكبار",correct:!0},{text:"أركلها بقدمي بعيدًا عن البيت",correct:!1}],explanation:"اللعبة النارية التي لم تنفجر قد تنفجر لاحقًا. لا تلمسها وأخبر أحد الكبار."},{question:"هل يمكن للطفل أن يمسك شرارة يدوية صغيرة؟",options:[{text:"لا، فالشرارات حارّة جدًا وقد تحرق",correct:!0},{text:"نعم، الشرارات الصغيرة آمنة دائمًا",correct:!1},{text:"نعم، إذا أمسكها بطرف كمّه",correct:!1}],explanation:"الشرارات اليدوية من الألعاب النارية أيضًا وهي حارّة جدًا، ولا يمسكها الأطفال."},{question:"وجدت رصاصة على الأرض بعد الحفلة. ما التصرف الصحيح؟",options:[{text:"ألتقطها وآخذها إلى البيت لأريها لأصدقائي",correct:!1},{text:"أخفيها في حقيبتي حتى لا يجدها أحد",correct:!1},{text:"لا ألمسها، وأبتعد، وأخبر أحد الكبار",correct:!0}],explanation:"قد تنفجر الرصاصة وهي ليست لعبة. لا تلمسها، فالكبار يعرفون ماذا يفعلون."}],steps:[{title:"ادخل البيت",detail:"عند إطلاق النار، ادخل تحت سقف متين.",critical:!0},{title:"لا تلمس",detail:"لا تلمس الألعاب النارية أو الأسلحة أو الرصاص أبدًا.",critical:!0},{title:"أخبر أحد الكبار",detail:"أخبره عن أي شيء خطير تجده.",critical:!0},{title:"اطلب المساعدة",detail:"إذا أُصيب أحد، فاتصل بالرقم 115 أو 122.",critical:!0}]},{id:22,icon:"Sun",accent:"#f59e0b",title:"حرّ الصيف والسيارات الحارّة",subtitle:"ابقَ باردًا في الأيام الحارّة",grades:"1-6",ages:"6-12",summary:"قد تكون أيام الصيف حارّة جدًا، والحرّ الشديد قد يُمرض جسمك. والسيارة المتوقفة تسخن من الداخل بسرعة كبيرة، حتى لو كانت النافذة مفتوحة قليلًا. تعلّم كيف تبقى باردًا، وماذا تفعل إذا تعبت أنت أو صديقك من الحرّ.",blocks:[{heading:"الحرّ قد يُمرضك",body:"في اليوم الحار يفقد جسمك الماء بالعرق. اشرب الماء كثيرًا، حتى قبل أن تشعر بالعطش. العب في الظل واسترح، وابقَ في الداخل في أشد أوقات النهار حرًّا."},{heading:"علامات مهمّة",body:"الصداع أو الدوار أو الغثيان أو التعب الشديد أو العطش الشديد قد تعني أن الحرّ يؤذيك. توقّف عن اللعب، واذهب إلى مكان بارد، واشرب الماء، وأخبر أحد الكبار."},{heading:"السيارة المتوقفة فخّ",body:"لا تلعب ولا تختبئ أبدًا في سيارة متوقفة. فالسيارة تصبح حارّة جدًا من الداخل بسرعة، وقد لا تستطيع الخروج منها بسهولة. وإذا رأيت طفلًا أو حيوانًا وحده في سيارة حارّة، فأخبر أحد الكبار فورًا. وإذا لم يكن أحد من الكبار قريبًا، فاتصل بالرقم 115."},{heading:"إذا ارتبك صديقك أو سقط",body:"الصديق الذي يتكلم بطريقة غريبة أو يرتبك أو يسقط في الحرّ يحتاج إلى مساعدة سريعة. اصرخ لتنادي أحد الكبار واتصل بالرقم 122. ولا تعطِ شرابًا لمن هو مرتبك."}],examples:["اشرب الماء كثيرًا في الأيام الحارّة.","العب في الظل والبس قبّعة.","السيارة المتوقفة تصبح حارّة جدًا من الداخل.","سقط صديق في الحرّ: نادِ أحد الكبار واتصل بالرقم 122."],tips:["البس قبّعة وملابس خفيفة وواسعة.","احمل قارورة ماء إلى المدرسة واللعب.","قبل أن تنزل أنت وأسرتك من السيارة، انظر إلى المقاعد الخلفية."],warnings:["لا تلعب ولا تختبئ أبدًا في سيارة متوقفة!","إذا رأيت طفلًا وحده في سيارة، فأخبر أحد الكبار فورًا!"],realCase:"في ظهيرة صيفية حارّة، كان ابنا عمّ يلعبان الاختباء. أراد الأصغر أن يختبئ في سيارة الأسرة في الفناء. فرفض الأكبر: السيارة المغلقة تصبح حارّة جدًا من الداخل، وقد لا يستطيعان الخروج بسهولة. فاختبآ خلف شجرة في الظل. وبعد ذلك شربا الماء واستراحا داخل البيت.",game:{instruction:"أيّ هذه الأفعال آمنة؟ اختر الإجابات الصحيحة:",items:[{text:"اشرب الماء كثيرًا",emoji:"💧",correct:!0},{text:"اختبئ في سيارة متوقفة",emoji:"🚗",correct:!1},{text:"العب في الظل",emoji:"🌳",correct:!0},{text:"العب الكرة تحت الشمس في أشد أوقات الحرّ",emoji:"☀️",correct:!1},{text:"البس قبّعة في الخارج",emoji:"👒",correct:!0},{text:"ابقَ وحدك في السيارة بينما تتسوّق الأسرة",emoji:"🛒",correct:!1}]},activity:{prompt:"اليوم حارّ جدًا. تذهب أسرتك إلى السوق ويقول أبوك: «ابقَ في السيارة، سنعود بسرعة.» ماذا تفعل؟",options:[{text:"أبقى في السيارة وأغلق كل النوافذ",correct:!1,feedback:"السيارة المغلقة تسخن جدًا بسرعة. اطلب أن تذهب معهم."},{text:"أبقى وأفتح النافذة قليلًا",correct:!1,feedback:"النافذة المفتوحة قليلًا لا تُبرّد السيارة. اطلب أن تذهب معهم."},{text:"أطلب أن أذهب معهم ولا أبقى وحدي في السيارة",correct:!0,feedback:"صحيح. لا يبقى الطفل وحده في سيارة متوقفة أبدًا، خاصة في الأيام الحارّة."},{text:"أنام في المقعد الخلفي حتى يعودوا",correct:!1,feedback:"النوم في سيارة حارّة خطير جدًا. اطلب أن تذهب معهم."}]},quiz:[{question:"متى تشرب الماء في اليوم الحار؟",options:[{text:"كثيرًا، حتى قبل أن أشعر بالعطش",correct:!0},{text:"في الليل فقط عندما أنام",correct:!1},{text:"فقط عندما يجفّ فمي كثيرًا",correct:!1}],explanation:"يفقد الجسم الماء بالعرق، والشرب كثيرًا يساعدك على ألّا تمرض."},{question:"هل اللعب في سيارة متوقفة آمن في يوم حار؟",options:[{text:"نعم، إذا كانت نافذة مفتوحة قليلًا",correct:!1},{text:"لا، فهي تسخن من الداخل بسرعة كبيرة",correct:!0},{text:"نعم، إذا بقيت فيها وقتًا قصيرًا",correct:!1}],explanation:"السيارة المتوقفة تسخن بسرعة كبيرة حتى مع نافذة مفتوحة قليلًا، فلا تلعب فيها أبدًا."},{question:"رأيت طفلًا صغيرًا وحده في سيارة حارّة. ماذا تفعل؟",options:[{text:"أطرق النافذة ثم أكمل طريقي وأمشي بعيدًا",correct:!1},{text:"أنتظر لأرى هل يعود والداه",correct:!1},{text:"أخبر أحد الكبار فورًا أو أتصل بالرقم 115",correct:!0}],explanation:"الطفل في سيارة حارّة يحتاج إلى مساعدة سريعة. نادِ أحد الكبار، أو اتصل بالرقم 115 إذا لم يكن أحد قريبًا."},{question:"وأنت تلعب تحت الشمس، أصابك صداع ودوار. ما التصرف الصحيح؟",options:[{text:"أواصل اللعب بقوة حتى تنتهي المباراة",correct:!1},{text:"أتوقف وأرتاح في الظل وأشرب وأخبر أحد الكبار",correct:!0},{text:"أركض تحت الشمس إلى الدكان لأشتري حلوى",correct:!1}],explanation:"هذه علامات على أن الحرّ يؤذيك. توقّف، وتبرّد، واشرب الماء، وأخبر أحد الكبار."},{question:"سقط صديقك في الحرّ وصار يتكلم بطريقة غريبة. ماذا تفعل؟",options:[{text:"أعطي صديقي ماءً كثيرًا بسرعة",correct:!1},{text:"أنادي أحد الكبار وأتصل بالرقم 122",correct:!0},{text:"أترك صديقي ينام وحده تحت الشمس",correct:!1}],explanation:"السقوط والكلام الغريب في الحرّ قد يكونان خطيرين ويحتاجان إلى مساعدة سريعة. لا تعطِ شرابًا لمن هو مرتبك."}],steps:[{title:"توقّف عن اللعب",detail:"اذهب إلى الظل أو غرفة باردة.",critical:!1},{title:"اشرب الماء",detail:"اشرب الماء ببطء.",critical:!1},{title:"أخبر أحد الكبار",detail:"قل له بماذا تشعر.",critical:!0},{title:"اتصل بالرقم 122",detail:"إذا ارتبك صديق أو سقط، نادِ أحد الكبار واتصل بالرقم 122.",critical:!0}]},{id:23,icon:"Users",accent:"#0d9488",title:"الضياع بعد الكارثة: لا تذهب إلا مع شخص كبير تعرفه",subtitle:"ماذا تفعل إذا أضعت أسرتك",grades:"1-6",ages:"6-12",summary:"بعد الزلزال أو الفيضان أو الحريق، يتحرك الناس بسرعة وقد تتفرّق الأسر. إذا لم تجد أسرتك فابقَ هادئًا وابقَ في مكان آمن. لا تذهب إلا مع شخص كبير تعرفه، أو اطلب المساعدة من مُنقذ يرتدي زيًّا رسميًّا أو من معلّمك.",blocks:[{heading:"اعرف معلوماتك",body:"احفظ اسمك الكامل واسمَي والديك ورقم هاتف أحدهما. ويمكن لأسرتك أيضًا أن تكتب الرقم على بطاقة في حقيبتك."},{heading:"إذا ضعت",body:"توقّف وابقَ في مكان آمن، بعيدًا عن المباني المتضرّرة والنار والماء. لا تتجوّل وحدك بحثًا عنهم. وإذا كان لأسرتك مكان تجمّع فاذهب إليه فقط إذا كان الطريق آمنًا."},{heading:"من يستطيع مساعدتك",body:"اطلب المساعدة من مُنقذ يرتدي زيًّا رسميًّا، مثل الدفاع المدني أو الشرطة، أو من معلّمك. أخبرهم باسمك ورقم هاتف أحد والديك، وابقَ في المكان الذي يطلبونه منك."},{heading:"فقط مع شخص كبير تعرفه",body:"لا تذهب أبدًا إلى أي مكان مع شخص غريب، حتى لو قال إنه يعرف أسرتك أو عرض عليك طعامًا أو هدية. لا تذهب إلا مع أسرتك أو مع شخص كبير تعرفه وتثق به أسرتك. وابقَ مع المنقذين أو معلّمك حتى تأتي أسرتك."}],examples:["احفظ رقم هاتف أحد والديك.","ضعت؟ توقّف وابقَ في مكان آمن.","اطلب المساعدة من مُنقذ بزيّ رسمي أو من معلّمك.","غريب يعرض أن يأخذك إلى البيت: قل لا وابقَ مع المنقذين."],tips:["اتفق مع أسرتك على مكان تجمّع خارج البيت.","احتفظ في حقيبتك ببطاقة عليها اسمك ورقم هاتف أحد والديك.","تدرّب على قول اسمك ورقم هاتف أحد والديك."],warnings:["لا تذهب أبدًا مع شخص غريب، حتى لو عرض عليك طعامًا أو هدية!","لا تعد إلى مبنى متضرّر لتبحث عن أسرتك!"],realCase:"بعد زلزال، ركض الجميع خارجين من سوق مزدحمة. أضاعت فتاة أمها بين الناس. فوقفت في مكان واسع مكشوف بعيدًا عن المباني. قال لها رجل لا تعرفه إنه سيأخذها إلى أمها، لكنها رفضت. وطلبت المساعدة من مُنقذ من الدفاع المدني يرتدي زيًّا رسميًّا، وأخبرته باسمها ورقم هاتف أمها. فاتصل المنقذ بأمها، والتقتا من جديد.",game:{instruction:"أيّ هذه الأفعال آمنة؟ اختر الإجابات الصحيحة:",items:[{text:"احفظ رقم هاتف أحد والديك",emoji:"📱",correct:!0},{text:"اذهب مع غريب يعطيك الحلوى",emoji:"🍬",correct:!1},{text:"اطلب المساعدة من مُنقذ بزيّ رسمي",emoji:"🦺",correct:!0},{text:"تجوّل وحدك في الشوارع المتضرّرة",emoji:"🏚️",correct:!1},{text:"ابقَ في مكان مكشوف آمن",emoji:"🧍",correct:!0},{text:"عد إلى مبنى متضرّر لتبحث",emoji:"🚪",correct:!1}]},activity:{prompt:"بعد فيضان، أنت في مكان تجمّع مزدحم ولا تجد والديك. تقول لك امرأة لا تعرفها: «تعال معي، سآخذك إليهما.» ماذا تفعل؟",options:[{text:"أذهب معها لأنها تتكلم بلطف",correct:!1,feedback:"الغريب، حتى لو كان لطيفًا، ليس شخصًا تعرفه. ابقَ مع المنقذين أو معلّمك."},{text:"أقول لا وأطلب المساعدة من مُنقذ أو من معلّمي",correct:!0,feedback:"صحيح. يستطيع المنقذ أو المعلّم الاتصال بأسرتك بأمان."},{text:"أمشي وحدي في الماء عائدًا إلى البيت",correct:!1,feedback:"ماء الفيضان خطير جدًا. ابقَ في المكان الآمن واطلب المساعدة."},{text:"أختبئ في مكان حتى لا يراني أحد",correct:!1,feedback:"إذا اختبأت فلن تجدك أسرتك ولا المنقذون. ابقَ في مكان ظاهر واطلب المساعدة."}]},quiz:[{question:"ماذا يجب أن تحفظ؟",options:[{text:"اسمي ورقم هاتف أحد والديّ",correct:!0},{text:"لون سيارة جاري",correct:!1},{text:"أسماء كل الدكاكين في شارعي",correct:!1}],explanation:"باسمك ورقم الهاتف يستطيع المنقذ أو المعلّم أن يجد أسرتك بسرعة."},{question:"ضعت بعد زلزال. ماذا تفعل أولًا؟",options:[{text:"أتجوّل وحدي في الشوارع لأجدهم",correct:!1},{text:"أتوقف وأبقى في مكان مكشوف آمن",correct:!0},{text:"أعود إلى داخل مبنى لأبحث عنهم",correct:!1}],explanation:"إذا بقيت في مكان آمن فسيجدونك بسهولة أكبر وتبقى بعيدًا عن خطر المباني المتضرّرة."},{question:"ممّن يمكنك أن تطلب المساعدة؟",options:[{text:"من أي شخص يعطيني حلوى أو هدية",correct:!1},{text:"من مجموعة أطفال أكبر لا أعرفهم",correct:!1},{text:"من مُنقذ بزيّ رسمي أو من معلّمي",correct:!0}],explanation:"المنقذون بالزيّ الرسمي والمعلّمون يعرفون كيف يجدون أسرتك بأمان."},{question:"يقول رجل: «أعرف أباك، تعال معي.» وأنت لا تعرفه. ماذا تفعل؟",options:[{text:"أقول لا وأبقى مع المنقذين أو معلّمي",correct:!0},{text:"أذهب معه لأنه يعرف اسم أبي",correct:!1},{text:"أذهب معه إذا وعد أن يشتري لي طعامًا",correct:!1}],explanation:"لا تذهب إلا مع أسرتك أو شخص كبير تعرفه، وابقَ مع المنقذين أو المعلّم حتى تأتي أسرتك."},{question:"مكان تجمّع أسرتك في الجهة الأخرى من شارع غمرته المياه. ما التصرف الصحيح؟",options:[{text:"أعبر الماء بسرعة لأصل إليه",correct:!1},{text:"أنتظر حتى ينخفض الماء قليلًا ثم أعبر",correct:!1},{text:"أبقى في المكان الآمن وأطلب المساعدة من مُنقذ",correct:!0}],explanation:"تذهب إلى مكان التجمّع فقط إذا كان الطريق آمنًا. لا تدخل ماء الفيضان أبدًا."}],steps:[{title:"توقّف",detail:"توقّف وابقَ في مكان آمن.",critical:!0},{title:"اطلب المساعدة",detail:"من مُنقذ بزيّ رسمي أو من معلّمك.",critical:!0},{title:"قل من أنت",detail:"قل اسمك ورقم هاتف أحد والديك.",critical:!1},{title:"فقط مع من تعرفه",detail:"لا تذهب إلا مع أسرتك أو شخص كبير تعرفه.",critical:!0}]},{id:24,icon:"HeartHandshake",accent:"#db2777",title:"المشاعر بعد الكارثة",subtitle:"لا بأس أن تشعر بالخوف أو الحزن",grades:"1-6",ages:"6-12",summary:"بعد الزلزال أو الفيضان أو الحريق أو أي حدث مخيف، يشعر كثير من الأطفال والكبار بالخوف أو الحزن أو الغضب. هذه المشاعر طبيعية. والحديث مع شخص كبير تثق به، والبقاء قرب أسرتك، والقيام بأشياء هادئة معًا، كلها تساعدك على أن تشعر بتحسّن.",blocks:[{heading:"مشاعر كثيرة طبيعية",body:"قد تشعر بالخوف أو الحزن أو الغضب أو القلق. وقد ترى أحلامًا مزعجة، أو يؤلمك بطنك، أو لا ترغب في اللعب. وقد تجعلك الأصوات العالية تفزع. كثير من الناس يشعرون بهذا بعد حدث مخيف."},{heading:"تحدّث مع شخص تثق به",body:"أخبر والديك أو معلّمك أو شخصًا كبيرًا آخر تثق به بما تشعر. ويمكنك أيضًا أن ترسم صورة أو تكتب عن ذلك. مشاعرك مهمّة، ولا بأس أن تبكي."},{heading:"أشياء تساعد",body:"تنفّس ببطء: خذ النفس من أنفك وأخرجه من فمك. نَم وكُل والعب في أوقاتك المعتادة. وافعل أشياء هادئة تحبها مع أسرتك وأصدقائك. وابتعد عن الصور والفيديوهات المخيفة عن الكارثة."},{heading:"ساعد الآخرين أيضًا",body:"كن لطيفًا مع صديقك الحزين. العبا معًا واستمع إليه. وإذا بقيت أنت أو صديقك تشعران بسوء شديد مدة طويلة، فأخبر أحد الكبار ليجد لكما مساعدة أكثر."}],examples:["الخوف بعد الزلزال أمر طبيعي.","رسم صورة يساعدك على التعبير عن مشاعرك.","التنفس البطيء يساعد جسمك على الهدوء.","الصديق الحزين يحتاج إلى اللطف وإلى من يستمع إليه."],tips:["استمرّ في الأشياء المعتادة: المدرسة والطعام والنوم واللعب.","اسأل أحد الكبار عندما لا تفهم ما حدث.","أطفئ الأخبار والفيديوهات المخيفة عن الكارثة."],warnings:["لا تُخفِ المشاعر السيئة مدة طويلة: أخبر شخصًا كبيرًا تثق به!","لا تضحك أبدًا على صديق خائف أو يبكي!"],realCase:"بعد زلزال قوي، لم يستطع صبيّ أن ينام جيدًا. كان كل صوت عالٍ يُفزعه، ولم يرغب في الذهاب إلى المدرسة. وفي مساء أحد الأيام أخبر أمه. فعانقته وقالت إن كثيرًا من الناس يشعرون بهذا. وتدرّبا معًا على التنفس البطيء ورسما صورًا. وساعده معلّمه أيضًا. وشيئًا فشيئًا صار الصبي أهدأ، وعاد يلعب مع أصدقائه.",game:{instruction:"أيّ هذه الأفعال تساعد؟ اختر الإجابات الصحيحة:",items:[{text:"أخبر أحد الكبار بما تشعر",emoji:"🗣️",correct:!0},{text:"أخفِ خوفك",emoji:"🤐",correct:!1},{text:"تنفّس ببطء",emoji:"🌬️",correct:!0},{text:"شاهد فيديوهات الكارثة المخيفة مرة بعد مرة",emoji:"📺",correct:!1},{text:"ارسم صورة لمشاعرك",emoji:"🎨",correct:!0},{text:"اضحك على صديق يبكي",emoji:"😆",correct:!1}]},activity:{prompt:"بعد فيضان، صار صديقك في المدرسة صامتًا جدًا ولا يريد اللعب. ماذا ستفعل؟",options:[{text:"أقول له أن يكفّ عن التصرّف كالرضيع",correct:!1,feedback:"هذا الكلام يجرح صديقك. الخوف والحزن طبيعيان، فكن لطيفًا."},{text:"أجلس مع صديقي وأستمع إليه وأخبر المعلّم",correct:!0,feedback:"صحيح. البقاء قربه والاستماع إليه يساعدانه، والمعلّم يستطيع أن يجد مساعدة أكثر."},{text:"أترك صديقي وحده وألعب مع الآخرين",correct:!1,feedback:"قد يشعر صديقك بالوحدة. ابقَ قريبًا منه وأخبر المعلّم."},{text:"أحكي له قصصًا مخيفة عن الفيضان",correct:!1,feedback:"القصص المخيفة تزيد الخوف. افعلا أشياء هادئة وأخبر المعلّم."}]},quiz:[{question:"بعد زلزال تشعر بالخوف وترى أحلامًا مزعجة. هل هذا طبيعي؟",options:[{text:"نعم، هذا طبيعي وإخبار الكبار يساعد",correct:!0},{text:"لا، الرضّع فقط يخافون هكذا",correct:!1},{text:"لا، يجب أن تخفيه عن الجميع",correct:!1}],explanation:"الخوف والأحلام المزعجة بعد حدث مخيف أمر طبيعي، والحديث مع الكبار يساعدك."},{question:"ما الذي يساعدك على أن تهدأ؟",options:[{text:"مشاهدة فيديوهات الكارثة المخيفة",correct:!1},{text:"التنفس البطيء والحديث مع أحد الكبار",correct:!0},{text:"البقاء وحدك في غرفتك طوال اليوم",correct:!1}],explanation:"التنفس البطيء يهدّئ الجسم، والحديث مع شخص كبير تثق به يساعدك."},{question:"يبكي صديقك عندما يسمع صوتًا عاليًا. ماذا تفعل؟",options:[{text:"أضحك حتى ينسى صديقي الصوت",correct:!1},{text:"أخبر كل التلاميذ في الصف بما حدث له",correct:!1},{text:"أكون لطيفًا وأبقى قريبًا وأخبر المعلّم",correct:!0}],explanation:"الصديق الخائف يحتاج إلى اللطف، والمعلّم يستطيع مساعدته."},{question:"لمن تتحدّث عن مشاعرك؟",options:[{text:"أحد والديّ أو المعلّم أو شخص كبير أثق به",correct:!0},{text:"لا أحد، لأن المشاعر يجب أن تبقى سرًّا",correct:!1},{text:"فقط أشخاص أعرفهم على الإنترنت",correct:!1}],explanation:"الشخص الكبير الذي تثق به يستطيع أن يستمع إليك ويجد لك المساعدة."},{question:"بعد أسابيع، ما زلت تشعر بسوء شديد كل يوم. ما التصرف الصحيح؟",options:[{text:"أخفي ذلك وأنتظر حتى يذهب وحده",correct:!1},{text:"أخبر أحد الكبار ليجد لي مساعدة أكثر",correct:!0},{text:"أتوقف عن الأكل والنوم جيدًا",correct:!1}],explanation:"إذا بقيت المشاعر السيئة مدة طويلة، يستطيع الكبار أن يجدوا لك مساعدة أكثر من المختصين."}],steps:[{title:"لاحظ مشاعرك",detail:"الخوف أو الحزن أو الغضب أمر طبيعي.",critical:!1},{title:"تنفّس ببطء",detail:"خذ النفس من أنفك وأخرجه من فمك.",critical:!1},{title:"أخبر أحد الكبار",detail:"تحدّث مع شخص كبير تثق به.",critical:!1},{title:"افعل أشياء هادئة",detail:"ارسم والعب وابقَ قرب أسرتك.",critical:!1}]},{id:25,icon:"Leaf",accent:"#65a30d",title:"حرائق الأعشاب والحقول",subtitle:"العشب الجاف يشتعل بسهولة",grades:"1-6",ages:"6-12",summary:"في الصيف يصبح العشب والحقول جافّة جدًا. وشرارة صغيرة قد تُشعل حريقًا كبيرًا، والرياح قد تنشره بسرعة. لا يلعب الأطفال بالنار أبدًا، ولا يحاولون إطفاء حريق العشب أبدًا. بل يبتعدون، ويخبرون أحد الكبار، ويتصلون بالرقم 115.",blocks:[{heading:"العشب الجاف يحترق بسرعة",body:"العشب الجاف وحقول القمح والشجيرات تشتعل بسهولة في الصيف. والرياح تدفع النار إلى الأمام بسرعة كبيرة، وقد تغيّر النار اتجاهها فجأة."},{heading:"كيف يبدأ حريق العشب",body:"الكبريت والولّاعات والسجائر والألعاب النارية وحرق النفايات قد تُشعل حريق العشب. وحتى الزجاجات والزجاج المكسور تحت الشمس قد تُشعل النار. لا تلعب بالكبريت أو الولّاعات أبدًا."},{heading:"إذا رأيت حريق عشب",body:"ابتعد فورًا عن النار والدخان. اذهب إلى طريق، أو أرض مكشوفة بلا عشب، أو إلى مبنى. أخبر أحد الكبار واتصل بالرقم 115. لا تحاول أبدًا إطفاء النار بنفسك، ولا تقترب أبدًا لتتفرّج."},{heading:"ساعد 115 على إيجاد الحريق",body:"عندما تتصل بالرقم 115، قل أولًا أين الحريق، وهل هناك ناس أو بيوت قريبة. ثم ابقَ مع أحد الكبار في مكان آمن."}],examples:["شرارة صغيرة قد تُشعل العشب الجاف.","الرياح تنشر حريق العشب بسرعة.","حريق عشب: ابتعد، وأخبر أحد الكبار، واتصل بالرقم 115.","لا تقترب أبدًا لتتفرّج على النار."],tips:["ضع الزجاجات والزجاج المكسور في سلة النفايات.","لا تلعب بالكبريت أو الولّاعات أبدًا.","أخبر أحد الكبار إذا رأيت من يحرق النفايات قرب العشب الجاف."],warnings:["لا تحاول أبدًا إطفاء حريق العشب بنفسك: ابتعد واتصل بالرقم 115!","لا تلعب أبدًا بالكبريت أو الولّاعات أو الألعاب النارية قرب العشب!"],realCase:"في يوم صيفي عاصف، كان بعض الأطفال يلعبون قرب حقل قمح جاف. فرأوا دخانًا ونارًا صغيرة عند طرف الحقل. أراد أحدهم أن يضرب النار بعصا. فرفض صديقه: ذهبوا بسرعة إلى الطريق بعيدًا عن الدخان، وأخبروا مزارعًا. فاتصل المزارع بالرقم 115 وقال أين الحريق. وجاء رجال الإطفاء وأطفؤوا النار قبل أن تصل إلى البيوت.",game:{instruction:"أيّ هذه الأفعال آمنة؟ اختر الإجابات الصحيحة:",items:[{text:"ابتعد عن النار والدخان",emoji:"🏃",correct:!0},{text:"اضرب النار بعصا",emoji:"🪵",correct:!1},{text:"أخبر أحد الكبار واتصل بالرقم 115",emoji:"📞",correct:!0},{text:"اقترب لتتفرّج على النار",emoji:"👀",correct:!1},{text:"ضع الزجاج المكسور في سلة النفايات",emoji:"🗑️",correct:!0},{text:"العب بالولّاعة في الحقل",emoji:"🔥",correct:!1}]},activity:{prompt:"أنت عائد إلى البيت بجانب حقل. ترى دخانًا ونارًا في العشب الجاف، والرياح تهبّ نحوك. ماذا ستفعل؟",options:[{text:"أدوس على النار بقدميّ لأوقفها",correct:!1,feedback:"حريق العشب ينتشر بسرعة وقد يحرقك. الأطفال لا يحاولون إطفاء النار أبدًا."},{text:"أقف وأصوّر النار بالفيديو",correct:!1,feedback:"الرياح تدفع النار نحوك. التوقّف خطير، فابتعد فورًا."},{text:"أختبئ خلف كومة قش في الحقل",correct:!1,feedback:"القش يشتعل بسهولة. اخرج من الحقل إلى الطريق أو أرض مكشوفة."},{text:"أبتعد عن النار والدخان وأخبر أحد الكبار وأتصل بالرقم 115",correct:!0,feedback:"صحيح. الابتعاد يحميك، و115 يرسل رجال الإطفاء."}]},quiz:[{question:"لماذا ينتشر حريق العشب بسرعة في الصيف؟",options:[{text:"لأن العشب جاف والرياح تدفع النار",correct:!0},{text:"لأن العشب رطب ويصنع بخارًا كثيرًا",correct:!1},{text:"لأن النار تتحرك ليلًا فقط عندما يبرد الجو",correct:!1}],explanation:"العشب الجاف يشتعل بسهولة، والرياح تدفع النار بسرعة."},{question:"رأيت حريق عشب صغيرًا قرب مدرستك. ماذا تفعل؟",options:[{text:"أرمي عليه التراب والحجارة بنفسي",correct:!1},{text:"أبتعد وأخبر أحد الكبار وأتصل بالرقم 115",correct:!0},{text:"أقترب لأرى كم هو كبير",correct:!1}],explanation:"حتى الحريق الصغير قد يكبر بسرعة. الأطفال يبتعدون ويطلبون المساعدة."},{question:"دخان حريق الحقل يتجه نحوك. إلى أين تذهب؟",options:[{text:"أدخل العشب الطويل لأختبئ من الدخان",correct:!1},{text:"أقترب من النار لأراها جيدًا",correct:!1},{text:"بعيدًا عن الدخان إلى طريق أو أرض مكشوفة",correct:!0}],explanation:"الطريق والأرض المكشوفة ليس فيهما عشب يحترق. ابتعد عن الدخان."},{question:"أيّ هذه قد يُشعل حريق عشب؟",options:[{text:"ولّاعة يلعب بها أحد",correct:!0},{text:"زجاجة ماء بارد في سلة النفايات",correct:!1},{text:"شجرة خضراء تحت المطر",correct:!1}],explanation:"الولّاعات والكبريت تُشعل النار، ولا يلعب بها الأطفال أبدًا."},{question:"عندما تتصل بالرقم 115 بسبب حريق عشب، ماذا تقول أولًا؟",options:[{text:"بماذا تشعر اليوم تجاه الحريق",correct:!1},{text:"أين الحريق وهل هناك بيوت قريبة",correct:!0},{text:"اسم معلّمك في المدرسة",correct:!1}],explanation:"يحتاج رجال الإطفاء إلى معرفة مكان الحريق ليصلوا إليه بسرعة."}],steps:[{title:"ابتعد",detail:"ابتعد عن النار والدخان.",critical:!0},{title:"اذهب إلى مكان آمن",detail:"طريق أو أرض مكشوفة أو مبنى.",critical:!0},{title:"أخبر أحد الكبار",detail:"أخبر أقرب شخص كبير.",critical:!0},{title:"اتصل بالرقم 115",detail:"قل أين الحريق.",critical:!0}]}],t={lessons:e};export{t as default,e as lessons};
